export type CalendarDateValue = Date | string | number | null | undefined;

// Epoch seconds remain below this threshold until November 2286. Using 1e12
// would mistake ordinary pre-2001 millisecond dates for seconds.
const EPOCH_SECONDS_CUTOFF = 10_000_000_000;

/** Parse a calendar value without introducing relative-time or product policy. */
export function parseCalendarDate(value: CalendarDateValue): Date | null {
  if (value == null || value === "") return null;

  if (value instanceof Date) {
    return Number.isNaN(value.getTime()) ? null : value;
  }

  if (typeof value === "number") {
    if (Number.isInteger(value) && value >= 1000 && value <= 9999) {
      return new Date(Date.UTC(value, 0, 1));
    }
    const parsed = new Date(Math.abs(value) < EPOCH_SECONDS_CUTOFF ? value * 1000 : value);
    return Number.isNaN(parsed.getTime()) ? null : parsed;
  }

  const trimmed = value.trim();
  if (!trimmed) return null;
  if (/^\d{4}$/.test(trimmed)) {
    return new Date(Date.UTC(Number(trimmed), 0, 1));
  }
  if (/^\d{4}-\d{2}$/.test(trimmed)) {
    const [year, month] = trimmed.split("-").map(Number);
    if (year && month && month >= 1 && month <= 12) {
      return new Date(Date.UTC(year, month - 1, 1));
    }
  }

  const parsed = new Date(trimmed);
  return Number.isNaN(parsed.getTime()) ? null : parsed;
}

/** Format an absolute career date. This deliberately never says "ago". */
export function formatCalendarDate(
  value: CalendarDateValue,
  locale = "en",
): string | null {
  if (typeof value === "number" && Number.isInteger(value) && value >= 1000 && value <= 9999) {
    return String(value);
  }
  if (typeof value === "string" && /^\d{4}$/.test(value.trim())) {
    return value.trim();
  }

  const parsed = parseCalendarDate(value);
  if (!parsed) return null;
  return new Intl.DateTimeFormat(locale, {
    month: "short",
    year: "numeric",
    timeZone: "UTC",
  }).format(parsed);
}

import type { CallParticipant, CallSegment } from "@epicbagel/saas-kit/primitives/call-card";

export type { CallParticipant, CallSegment };

/** A person a call can be attached to: whatever record the host keeps, with a display name. */
export interface CallPerson {
  id: string | number;
  name: string;
}

/** The full transcript of a call, fetched on demand by the host. */
export interface CallTranscript {
  content: string;
  segments?: readonly CallSegment[] | null;
}

/**
 * Finds people for a typed name. Called with the trimmed query once it is at
 * least two characters and typing has paused; the signal aborts when the
 * query changes or the component unmounts, so pass it to your fetch.
 */
export type SearchCallPeople<TPerson extends CallPerson = CallPerson> = (
  query: string,
  signal: AbortSignal,
) => Promise<readonly TPerson[]>;

/** Where the host's check of a call against its open roles stands. */
export type CallInsightsStatus = "idle" | "ready" | "failed";

/**
 * The host's insight state for one call, as the call cards read it. The
 * host runs the check, polls for it and words the error; the cards only show
 * the state and call `onGenerate`.
 */
export interface CallInsights {
  /** `ready` once insights exist; `failed` when the last attempt left none. */
  status: CallInsightsStatus;
  /** A check is running: the generate control is disabled and shows progress. */
  generating: boolean;
  /** The last error, already worded. */
  error?: string | null;
  /** Starts a check. `force` is true when insights already exist, to regenerate them. */
  onGenerate: (force: boolean) => void;
}

/**
 * Turns raw participants (names, email addresses, or `{ name, email }`
 * objects) into the call card's participants: trimmed, with blanks dropped
 * and each person listed once, matched by email or else by name, ignoring
 * case. A bare string with an `@` is read as an email address.
 */
export function normalizeCallParticipants(raw: readonly unknown[]): CallParticipant[] {
  const seen = new Set<string>();
  const output: CallParticipant[] = [];
  for (const participant of raw) {
    let name: string | undefined;
    let email: string | undefined;
    if (typeof participant === "string") {
      if (participant.includes("@")) email = participant.trim();
      else name = participant.trim();
    } else if (participant && typeof participant === "object") {
      const value = participant as { name?: string; email?: string };
      name = value.name?.trim() || undefined;
      email = value.email?.trim() || undefined;
    }
    if (!name && !email) continue;
    const key = (email || name || "").toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    output.push({ name, email });
  }
  return output;
}

/** Keeps the transcript turns that have text to show, dropping anything else in the list. */
export function normalizeCallSegments(raw: readonly unknown[]): CallSegment[] {
  return raw.filter(
    (segment): segment is CallSegment =>
      segment != null &&
      typeof segment === "object" &&
      typeof (segment as { text?: unknown }).text === "string" &&
      (segment as { text: string }).text !== "",
  );
}

import { useCallback, useEffect, useRef, useState, type ReactNode } from "react";

import type {
  CallPerson,
  CallSegment,
  CallTranscript,
  SearchCallPeople,
} from "./call-data";

/** The shortest query that is searched. */
export const CALL_PEOPLE_SEARCH_MIN_LENGTH = 2;
/** How long typing must pause before a search runs. */
export const CALL_PEOPLE_SEARCH_DELAY_MS = 250;

/**
 * Debounced people search for the call cards. The host's search runs with
 * the trimmed query once it is long enough and typing has paused; a newer
 * query, closing the search or unmounting aborts the one in flight and
 * discards its results. A failed search shows no results.
 */
export function useCallPeopleSearch<TPerson extends CallPerson>(
  query: string,
  enabled: boolean,
  search: SearchCallPeople<TPerson>,
) {
  const [results, setResults] = useState<readonly TPerson[]>([]);
  const [searching, setSearching] = useState(false);
  // The latest search function, so a host passing an inline arrow doesn't
  // restart the debounce on every render.
  const searchRef = useRef(search);
  useEffect(() => {
    searchRef.current = search;
  });

  useEffect(() => {
    const term = query.trim();
    if (!enabled || term.length < CALL_PEOPLE_SEARCH_MIN_LENGTH) {
      setResults((current) => (current.length ? [] : current));
      setSearching(false);
      return;
    }
    const controller = new AbortController();
    setSearching(true);
    const timer = setTimeout(async () => {
      try {
        const found = await searchRef.current(term, controller.signal);
        if (!controller.signal.aborted) setResults(found);
      } catch {
        if (!controller.signal.aborted) setResults([]);
      } finally {
        if (!controller.signal.aborted) setSearching(false);
      }
    }, CALL_PEOPLE_SEARCH_DELAY_MS);
    return () => {
      controller.abort();
      clearTimeout(timer);
    };
  }, [query, enabled]);

  return { results, searching };
}

/**
 * A call card's transcript: the preview the host passed, until the first time
 * the transcript is opened loads the full one through `loadTranscript`. It
 * loads at most once at a time and keeps what it loaded; a failed or empty
 * load leaves the preview in place.
 */
export function useCallTranscript({
  transcript,
  segments,
  loadTranscript,
}: {
  transcript?: ReactNode;
  segments?: readonly CallSegment[] | null;
  loadTranscript?: () => Promise<CallTranscript | null | undefined>;
}) {
  const [full, setFull] = useState<CallTranscript | null>(null);
  const loading = useRef(false);

  const load = useCallback(async () => {
    if (!loadTranscript || full || loading.current) return;
    loading.current = true;
    try {
      const next = await loadTranscript();
      if (next) setFull(next);
    } catch {
      // The preview stays; the host reports its own failures.
    } finally {
      loading.current = false;
    }
  }, [full, loadTranscript]);

  return {
    transcript: full?.content ?? transcript,
    segments: (full?.segments ?? segments ?? undefined) as CallSegment[] | undefined,
    onLoadTranscript: loadTranscript ? () => void load() : undefined,
  };
}

"use client";

import { Badge } from "@epicbagel/saas-kit/primitives/badge";
import { Button } from "@epicbagel/saas-kit/primitives/button";
import { CallCard, type CallParticipant } from "@epicbagel/saas-kit/primitives/call-card";
import { EmptyState } from "@epicbagel/saas-kit/primitives/empty-state";
import { FlexItem } from "@epicbagel/saas-kit/primitives/flex-item";
import { Icon } from "@epicbagel/saas-kit/primitives/icon";
import { Input } from "@epicbagel/saas-kit/primitives/input";
import { InteractiveCard } from "@epicbagel/saas-kit/primitives/interactive-card";
import { List, ListItem } from "@epicbagel/saas-kit/primitives/list";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import { UserPlus, UserSearch } from "lucide-react";
import { lazy, Suspense, useState, type ReactNode } from "react";

import type {
  CallPerson,
  CallSegment,
  CallTranscript,
  SearchCallPeople,
} from "./call-data";
import { CALL_PEOPLE_SEARCH_MIN_LENGTH, useCallPeopleSearch, useCallTranscript } from "./call-hooks";

/** Host-owned wording for the card's fixed parts. */
export interface CallReconcileCardLabels {
  /** The heading when the call has no title. */
  untitled: string;
  /** The transcript toggle while it is closed. */
  showTranscript: string;
  /** What the footer asks the recruiter to do. */
  heading: ReactNode;
  dismiss: ReactNode;
  /** Starts the hint when the host suggests a person it couldn't find. */
  notFound: (name: string) => ReactNode;
  /** The rest of the hint under the heading. */
  hint: ReactNode;
  /** The rest of the hint when the host picks the person (`onPickOther`). */
  pickHint: ReactNode;
  /** The button that hands picking a person to the host, worded by whether there are possible matches above it. */
  pickOther: (hasMatches: boolean) => ReactNode;
  /** The eyebrow over the possible matches. */
  possibleMatches: ReactNode;
  /** The search field's placeholder, given the suggested person's name when there is one. */
  searchPlaceholder: (suggestedName?: string) => string;
  /** Opens the dialog that adds a new person from the call. */
  addManually: ReactNode;
  searching: ReactNode;
  noMatchesTitle: string;
  noMatchesDescription: string;
  createTitle: ReactNode;
  /** The eyebrow over the participant shortcuts in the create dialog. */
  useParticipant: ReactNode;
  name: ReactNode;
  namePlaceholder: string;
  email: ReactNode;
  emailPlaceholder: string;
  createSubmit: ReactNode;
  /** The preview dialog's title, read by screen readers only. */
  previewTitle: ReactNode;
  cancel: ReactNode;
  attach: ReactNode;
}

const DEFAULT_LABELS: CallReconcileCardLabels = {
  untitled: "Untitled call",
  showTranscript: "Show full transcript",
  heading: "Attach this call to a person",
  dismiss: "Dismiss",
  notFound: (name) => `We couldn't find ${name}.`,
  hint: "Search or add them below to attach the conversation and keep their history and future recommendations together.",
  pickHint: "Pick who it was with to attach the conversation and keep their history and future recommendations together.",
  pickOther: (hasMatches) => (hasMatches ? "Someone else" : "Attach to…"),
  possibleMatches: "Possible matches",
  searchPlaceholder: (name) => (name === undefined ? "Search by name" : `Search for ${name}`),
  addManually: "Manually add",
  searching: "Searching…",
  noMatchesTitle: "No people match that name",
  noMatchesDescription: "Try a different spelling, or add them manually.",
  createTitle: "Create candidate from this call",
  useParticipant: "Use a participant",
  name: "Name",
  namePlaceholder: "Full name",
  email: "Email",
  emailPlaceholder: "email@example.com",
  createSubmit: "Create & attach this call",
  previewTitle: "Candidate preview",
  cancel: "Cancel",
  attach: "Attach this call",
};

/** Whose call this is, already worded. */
export interface CallReconcileOwner {
  label: ReactNode;
  /** The person viewing owns the call: a filled badge rather than an outline. */
  isViewer?: boolean;
}

/** Someone on the call the host believes is new, not yet among its people. */
export interface CallReconcileSuggestedPerson {
  name: string;
  email?: string | null;
}

/** The person to create from the call and attach it to. */
export interface CallReconcileNewPerson {
  name: string;
  email?: string;
}

/** What every reconcile card shows, however the person is picked. */
export interface CallReconcileCardBaseProps {
  title?: ReactNode;
  source?: ReactNode;
  /** The gist of the call, clamped with a show-more toggle when long. */
  summary?: ReactNode;
  timestamp?: ReactNode;
  /** Who was on the call. Also offered as shortcuts in the create dialog. */
  participants?: readonly CallParticipant[];
  /** The transcript preview, until the full transcript loads. */
  transcript?: ReactNode;
  segments?: readonly CallSegment[] | null;
  /** Fetches the full transcript the first time it is opened. */
  loadTranscript?: () => Promise<CallTranscript | null | undefined>;
  /** Whose call it is, as a badge in the header. */
  owner?: CallReconcileOwner;
  /**
   * The host's own controls for the people the call may be about, under the
   * possible-matches eyebrow: buttons that confirm before attaching, say.
   * Shown in place of the buttons `guesses` renders.
   */
  suggestions?: ReactNode;
  /** Named in the hint and the search, and seeds the create dialog. */
  suggestedPerson?: CallReconcileSuggestedPerson | null;
  onDismiss: () => void;
  labels?: Partial<CallReconcileCardLabels>;
  /** Class for the card. Its root is the kit's CallCard, which takes no other attributes. */
  className?: string;
}

/**
 * The card picks the person itself: likely guesses and people found by name
 * are previewed before the call attaches, and a person can be created from
 * the call.
 */
export interface CallReconcileSearchProps<TPerson extends CallPerson = CallPerson> {
  /** People the call may be about, offered first. */
  guesses?: readonly TPerson[];
  searchPeople: SearchCallPeople<TPerson>;
  /** Beside the search field, such as a button that looks the suggested person up elsewhere. */
  externalSearch?: ReactNode;
  /** Attaches the call to a person picked from the guesses or the search, after the preview. */
  onAttach: (person: TPerson) => void;
  /** Creates a person from the create dialog and attaches the call to them. */
  onCreateAttach: (person: CallReconcileNewPerson) => void;
  /**
   * The preview of a picked person, above Cancel and Attach this call. `close`
   * dismisses the preview without attaching.
   */
  renderPreview: (person: TPerson, close: () => void) => ReactNode;
  onPickOther?: never;
}

/**
 * The host picks the person: the card offers the host's `suggestions` and one
 * button that opens the host's own people picker, and has no search, preview
 * or create dialog of its own.
 */
export interface CallReconcilePickerProps {
  /** Opens the host's people picker. */
  onPickOther: () => void;
  guesses?: never;
  searchPeople?: never;
  externalSearch?: never;
  onAttach?: never;
  onCreateAttach?: never;
  renderPreview?: never;
}

export type CallReconcileCardProps<TPerson extends CallPerson = CallPerson> =
  CallReconcileCardBaseProps & (CallReconcileSearchProps<TPerson> | CallReconcilePickerProps);

// The create and preview dialogs (and the drawer the kit's ResponsiveDialog
// renders on a phone) are a chunk of their own. Search mode mounts them with
// the card, so the chunk loads at once, closed; picker mode never mounts
// them, so a host with its own picker never downloads them.
const CallReconcileDialogs = lazy(() =>
  import("./call-reconcile-dialogs").then((module) => ({ default: module.CallReconcileDialogs })),
);

const isShown = (node: ReactNode) =>
  node != null && node !== false && node !== "" && !(Array.isArray(node) && node.length === 0);

const noSearch: SearchCallPeople<never> = async () => [];

/**
 * A call nobody has been attached to yet, and the one decision it needs:
 * attach it to an existing person (a likely guess, or one found by name, each
 * previewed first), create a person from it, or dismiss it. The host owns
 * what each choice saves and removes the card afterwards.
 *
 * With `onPickOther` the host picks the person instead: the card shows the
 * host's `suggestions` and one button for its own picker.
 */
export function CallReconcileCard<TPerson extends CallPerson>({
  title,
  source,
  summary,
  timestamp,
  participants = [],
  transcript,
  segments,
  loadTranscript,
  owner,
  suggestions,
  guesses = [],
  suggestedPerson,
  searchPeople,
  externalSearch,
  onDismiss,
  onAttach,
  onCreateAttach,
  renderPreview,
  onPickOther,
  labels,
  className,
}: CallReconcileCardProps<TPerson>) {
  const text = { ...DEFAULT_LABELS, ...labels };
  const call = useCallTranscript({ transcript, segments, loadTranscript });
  const [query, setQuery] = useState("");
  const { results, searching } = useCallPeopleSearch<TPerson>(
    query,
    searchPeople != null,
    searchPeople ?? noSearch,
  );
  const [preview, setPreview] = useState<TPerson | null>(null);
  const [createOpen, setCreateOpen] = useState(false);
  const [newName, setNewName] = useState("");
  const [newEmail, setNewEmail] = useState("");
  const closePreview = () => setPreview(null);
  const picker = onPickOther != null;
  // The host's suggestions, or else a button that previews each guess.
  const matches = suggestions !== undefined
    ? suggestions
    : guesses.map((guess) => (
      <Button key={guess.id} size="sm" variant="outline" onClick={() => setPreview(guess)}>
        {guess.name}
      </Button>
    ));
  const hasMatches = isShown(matches);

  return (
    <>
      <CallCard
        className={className}
        title={title || text.untitled}
        source={source}
        headerAside={owner ? (
          <Badge variant={owner.isViewer ? "secondary" : "outline"} shrink>{owner.label}</Badge>
        ) : undefined}
        summary={summary}
        timestamp={timestamp}
        participants={participants as CallParticipant[]}
        transcript={call.transcript}
        segments={call.segments}
        transcriptLabel={text.showTranscript}
        onLoadTranscript={call.onLoadTranscript}
        actions={(
          <Stack gap="md" width="full" textAlign="start" padding="sm">
            <Stack gap="xs">
              <Stack direction="horizontal" gap="md" align="center" justify="between">
                <Text size="sm" weight="medium">{text.heading}</Text>
                <Button variant="quiet" size="compact" shrink onClick={() => onDismiss()}>
                  {text.dismiss}
                </Button>
              </Stack>
              <Text size="xs" tone="muted">
                {suggestedPerson && <>{text.notFound(suggestedPerson.name)} </>}
                {picker ? text.pickHint : text.hint}
              </Text>
            </Stack>

            {picker ? (
              <Stack gap="xs" border="top" paddingTop="md">
                {hasMatches && <Text size="xs" tone="muted">{text.possibleMatches}</Text>}
                <Stack direction="horizontal" gap="sm" align="center" wrap>
                  {matches}
                  <Button variant="outline" size="sm" onClick={() => onPickOther?.()}>
                    <Icon icon={UserPlus} size="sm" />
                    {text.pickOther(hasMatches)}
                  </Button>
                </Stack>
              </Stack>
            ) : (
              <>
                {hasMatches && (
                  <Stack gap="xs" border="top" paddingTop="md">
                    <Text size="xs" tone="muted">{text.possibleMatches}</Text>
                    <Stack direction="horizontal" gap="sm" wrap>
                      {matches}
                    </Stack>
                  </Stack>
                )}

                <Stack direction="horizontal" gap="sm" align="center" wrap border="top" paddingTop="md">
                  <FlexItem grow minWidth="zero" basis="md">
                    <Input
                      type="text"
                      value={query}
                      onChange={(event) => setQuery(event.target.value)}
                      placeholder={text.searchPlaceholder(suggestedPerson ? suggestedPerson.name : undefined)}
                    />
                  </FlexItem>
                  {externalSearch}
                  <Button
                    variant="outline"
                    size="sm"
                    shrink
                    onClick={() => {
                      const seed = participants.find((participant) => participant.email) ?? participants[0];
                      setNewName(suggestedPerson?.name ?? seed?.name ?? "");
                      setNewEmail(suggestedPerson?.email ?? seed?.email ?? "");
                      setCreateOpen(true);
                    }}
                  >
                    {text.addManually}
                  </Button>
                </Stack>
                {(results.length > 0 || searching) && (
                  <List surface="bordered" radius="md">
                    {searching && results.length === 0 && (
                      <ListItem padding="md" textSize="xs" tone="soft">{text.searching}</ListItem>
                    )}
                    {results.map((person) => (
                      <ListItem key={person.id}>
                        <InteractiveCard
                          display="block"
                          radius="none"
                          border="none"
                          padding="row"
                          textSize="sm"
                          onClick={() => setPreview(person)}
                        >
                          {person.name}
                        </InteractiveCard>
                      </ListItem>
                    ))}
                  </List>
                )}
                {!searching && query.trim().length >= CALL_PEOPLE_SEARCH_MIN_LENGTH && results.length === 0 && (
                  <EmptyState
                    variant="search"
                    size="inline"
                    icon={UserSearch}
                    title={text.noMatchesTitle}
                    description={text.noMatchesDescription}
                  />
                )}
              </>
            )}
          </Stack>
        )}
      />

      {/* The host's picker replaces both dialogs, so picker mode mounts neither. */}
      {picker ? null : (
        // Closed dialogs render nothing, so there is nothing to show while
        // the chunk loads.
        <Suspense fallback={null}>
          <CallReconcileDialogs
            labels={text}
            participants={participants}
            create={{
              open: createOpen,
              onOpenChange: setCreateOpen,
              name: newName,
              onNameChange: setNewName,
              email: newEmail,
              onEmailChange: setNewEmail,
              onSubmit: () => {
                const name = newName.trim();
                const email = newEmail.trim();
                setCreateOpen(false);
                onCreateAttach?.({ name, email: email || undefined });
              },
            }}
            preview={{
              open: preview !== null,
              content: preview ? renderPreview?.(preview, closePreview) : null,
              onClose: closePreview,
              onAttach: () => {
                const person = preview;
                setPreview(null);
                if (person) onAttach?.(person);
              },
            }}
          />
        </Suspense>
      )}
    </>
  );
}

"use client";

import { Button } from "@epicbagel/saas-kit/primitives/button";
import type { CallParticipant } from "@epicbagel/saas-kit/primitives/call-card";
import { FlexItem } from "@epicbagel/saas-kit/primitives/flex-item";
import { Input } from "@epicbagel/saas-kit/primitives/input";
import {
  ResponsiveDialog,
  ResponsiveDialogBody,
  ResponsiveDialogContent,
  ResponsiveDialogHeader,
  ResponsiveDialogTitle,
} from "@epicbagel/saas-kit/primitives/responsive-dialog";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import type { ReactNode } from "react";

import type { CallReconcileCardLabels } from "./call-reconcile-card";

/** The create dialog: a new person to attach the call to. */
export interface CallReconcileCreateDialogState {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  name: string;
  onNameChange: (name: string) => void;
  email: string;
  onEmailChange: (email: string) => void;
  /** Saves the trimmed name and email; the card closes the dialog first. */
  onSubmit: () => void;
}

/** The preview dialog: a picked person, before the call attaches. */
export interface CallReconcilePreviewDialogState {
  open: boolean;
  /** The host's preview of the picked person. */
  content: ReactNode;
  onClose: () => void;
  onAttach: () => void;
}

export interface CallReconcileDialogsProps {
  labels: CallReconcileCardLabels;
  participants: readonly CallParticipant[];
  create: CallReconcileCreateDialogState;
  preview: CallReconcilePreviewDialogState;
}

/**
 * CallReconcileCard's create and preview dialogs, for its search mode. A
 * module of its own that the card loads only in search mode, so a host that
 * picks the person itself (`onPickOther`) never downloads the dialogs or the
 * drawer the kit's ResponsiveDialog renders on a phone. Not exported: render
 * CallReconcileCard.
 */
export function CallReconcileDialogs({ labels: text, participants, create, preview }: CallReconcileDialogsProps) {
  return (
    <>
      <ResponsiveDialog open={create.open} onOpenChange={create.onOpenChange}>
        <ResponsiveDialogContent>
          <ResponsiveDialogHeader>
            <ResponsiveDialogTitle>{text.createTitle}</ResponsiveDialogTitle>
          </ResponsiveDialogHeader>
          <ResponsiveDialogBody>
            <Stack gap="sm">
              {participants.length > 0 && (
                <Stack gap="xs">
                  <Text variant="small" tone="muted">{text.useParticipant}</Text>
                  <Stack direction="horizontal" gap="sm" wrap>
                    {participants.map((participant, index) => (
                      <Button
                        key={`${participant.email ?? participant.name}-${index}`}
                        variant="outline"
                        size="sm"
                        onClick={() => {
                          create.onNameChange(participant.name ?? "");
                          create.onEmailChange(participant.email ?? "");
                        }}
                      >
                        {participant.name || participant.email}
                      </Button>
                    ))}
                  </Stack>
                </Stack>
              )}
              <Stack gap="xs">
                <Text variant="small" tone="muted">{text.name}</Text>
                <Input value={create.name} onChange={(event) => create.onNameChange(event.target.value)} placeholder={text.namePlaceholder} />
              </Stack>
              <Stack gap="xs">
                <Text variant="small" tone="muted">{text.email}</Text>
                <Input type="email" value={create.email} onChange={(event) => create.onEmailChange(event.target.value)} placeholder={text.emailPlaceholder} />
              </Stack>
              <Button size="sm" disabled={!create.name.trim()} onClick={() => create.onSubmit()}>
                {text.createSubmit}
              </Button>
            </Stack>
          </ResponsiveDialogBody>
        </ResponsiveDialogContent>
      </ResponsiveDialog>

      <ResponsiveDialog open={preview.open} onOpenChange={(open) => !open && preview.onClose()}>
        <ResponsiveDialogContent presentation="preview">
          <ResponsiveDialogHeader visibility="screen-reader">
            <ResponsiveDialogTitle>{text.previewTitle}</ResponsiveDialogTitle>
          </ResponsiveDialogHeader>
          {preview.open && (
            <Stack gap="none" minHeight="zero" grow>
              <FlexItem grow minHeight="zero" overflow="hidden">
                {preview.content}
              </FlexItem>
              <Stack direction="horizontal" gap="sm" align="center" justify="end" border="top" surface="background" padding="action-row">
                <Button variant="outline" size="sm" onClick={preview.onClose}>{text.cancel}</Button>
                <Button size="sm" onClick={() => preview.onAttach()}>
                  {text.attach}
                </Button>
              </Stack>
            </Stack>
          )}
        </ResponsiveDialogContent>
      </ResponsiveDialog>
    </>
  );
}

"use client";

import { Button } from "@epicbagel/saas-kit/primitives/button";
import { EmptyState } from "@epicbagel/saas-kit/primitives/empty-state";
import { Icon, type IconProps } from "@epicbagel/saas-kit/primitives/icon";
import { SectionHeader } from "@epicbagel/saas-kit/primitives/section-header";
import { Skeleton } from "@epicbagel/saas-kit/primitives/skeleton";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import { Timeline, TimelineRow, type TimelineProps } from "@epicbagel/saas-kit/primitives/timeline";
import { History } from "lucide-react";
import {
  forwardRef,
  useId,
  useState,
  type ButtonHTMLAttributes,
  type ElementType,
  type HTMLAttributes,
  type Key,
  type MouseEvent,
  type ReactNode,
} from "react";

import type { CandidateEmptyCopy } from "./candidate-empty-copy";

interface CandidateActivityItemBase {
  /** Identifies the item within its group. */
  id: Key;
  /** The glyph for what kind of activity it is, as a component such as a lucide icon. */
  icon?: ElementType;
  /** The glyph's colour, such as `info` for a meeting or `success` for a reply. Defaults to `muted`. */
  iconTone?: IconProps["tone"];
  /** What happened, such as an email's subject. Clamped to two lines. */
  title: ReactNode;
  /** One line of context under the title, such as the channel and who it was with. */
  subtitle?: ReactNode;
  /** When it happened, already formatted. */
  timestamp?: ReactNode;
}

/** A row that holds longer content, such as a transcript or an email body, behind a toggle. */
export interface CandidateActivityDetailItem extends CandidateActivityItemBase {
  /** The longer content, kept as written: line breaks are preserved. */
  body?: ReactNode;
  /** The toggle's text while the body is hidden, such as how long it is. */
  bodyLabel?: ReactNode;
  href?: never;
  onSelect?: never;
}

/** A row that opens something: a link with `href`, otherwise a button. */
export interface CandidateActivityLinkItem extends CandidateActivityItemBase {
  /** Makes the row a link. */
  href?: string;
  /**
   * Called when the row is activated. With `href`, it runs before the link
   * is followed, so a client-side router can prevent the default and
   * navigate itself.
   */
  onSelect?: (event: MouseEvent<HTMLElement>) => void;
  body?: never;
  bodyLabel?: never;
}

/**
 * One thing that happened with a person. A row either holds a `body` behind a
 * toggle or opens something (`href` or `onSelect`), never both, so a control
 * never sits inside another.
 */
export type CandidateActivityItem = CandidateActivityDetailItem | CandidateActivityLinkItem;

/** The items in one period, such as "Today" or "This month", newest first. */
export interface CandidateActivityGroup {
  id: Key;
  /** The period's heading, already worded. */
  label: ReactNode;
  /** Shown beside the heading in the kit's count badge, such as how many items the period holds. */
  count?: number;
  items: readonly CandidateActivityItem[];
}

/** Host-owned wording for the timeline's fixed parts. */
export interface CandidateActivityTimelineLabels {
  /** The body toggle while the body is hidden, when the item has no `bodyLabel`. */
  showBody: ReactNode;
  /** The body toggle while the body is shown. */
  hideBody: ReactNode;
}

const DEFAULT_LABELS: CandidateActivityTimelineLabels = {
  showBody: "Show full text",
  hideBody: "Hide full text",
};

export interface CandidateActivityTimelineProps
  extends Omit<HTMLAttributes<HTMLElement>, "children"> {
  /** The periods, in order, usually newest first. Empty groups are left out. */
  groups: readonly CandidateActivityGroup[];
  /** Skeleton rows in place of the timeline. */
  loading?: boolean;
  /** The blank slate's wording. Defaults to "No activity yet". */
  empty?: CandidateEmptyCopy;
  /** The kit Timeline's spacing between rows in a period. Defaults to `tight`. */
  spacing?: TimelineProps["spacing"];
  labels?: Partial<CandidateActivityTimelineLabels>;
}

function present(value: ReactNode): boolean {
  return value != null && value !== false && value !== "";
}

function ActivityBody({
  body,
  label,
  labels,
}: {
  body: ReactNode;
  label?: ReactNode;
  labels: CandidateActivityTimelineLabels;
}) {
  const [open, setOpen] = useState(false);
  const bodyId = useId();

  return (
    <Stack gap="xs" marginTop="xs" align="start">
      <Button
        type="button"
        variant="link-muted"
        size="bare"
        align="start"
        aria-expanded={open}
        aria-controls={open ? bodyId : undefined}
        onClick={() => setOpen((value) => !value)}
      >
        <Text variant="inherit" as="span" size="xs">
          {open ? labels.hideBody : present(label) ? label : labels.showBody}
        </Text>
      </Button>
      {open ? (
        <Stack id={bodyId} gap="none" surface="muted" radius="md" padding="sm" width="full">
          <Text as="div" size="xs" tone="muted" whitespace="pre-wrap">
            {body}
          </Text>
        </Stack>
      ) : null}
    </Stack>
  );
}

/** The element of a row that opens something without a URL. */
const RowButton = forwardRef<HTMLButtonElement, ButtonHTMLAttributes<HTMLButtonElement>>(
  function RowButton(props, ref) {
    return <button ref={ref} type="button" {...props} />;
  },
);

function ActivityRow({
  item,
  labels,
}: {
  item: CandidateActivityItem;
  labels: CandidateActivityTimelineLabels;
}) {
  const icon = item.icon ? (
    <Icon icon={item.icon} size="sm" tone={item.iconTone ?? "muted"} align="start" />
  ) : undefined;
  // The kit row truncates its title to one line; let it wrap to two instead,
  // keeping the row's own type.
  const title = <span className="line-clamp-2 whitespace-normal">{item.title}</span>;
  const shared = { icon, title, subtitle: item.subtitle, timestamp: item.timestamp };

  if (item.href != null || item.onSelect != null) {
    const select = item.onSelect;
    const onClick = select ? (event: MouseEvent) => select(event as MouseEvent<HTMLElement>) : undefined;
    return item.href != null ? (
      <TimelineRow {...shared} as="a" href={item.href} interactive onClick={onClick} />
    ) : (
      // A button centres its text; the row reads from the start like the others.
      <TimelineRow {...shared} as={RowButton} interactive onClick={onClick} className="w-full text-left" />
    );
  }

  return (
    <TimelineRow {...shared}>
      {present(item.body) ? (
        <ActivityBody body={item.body} label={item.bodyLabel} labels={labels} />
      ) : null}
    </TimelineRow>
  );
}

/**
 * A person's history, grouped by period: each period under its own heading,
 * each item a kit TimelineRow with a glyph, a title, a line of context and a
 * timestamp. A row can hold a longer body (a transcript, an email) behind a
 * toggle, or open something. A skeleton shows while it loads, and the kit's
 * empty state when nothing has happened.
 *
 * The host owns which records count as activity, how they are grouped and
 * worded, and what a row opens. The root is marked
 * `data-slot="candidate-activity-timeline"`; each period is a `section`
 * marked `data-slot="candidate-activity-period"`. Given an `aria-label` or
 * `aria-labelledby`, the root is a `region` (a host `role` wins), since a
 * label on a plain element is ignored by assistive technology.
 */
export function CandidateActivityTimeline({
  groups,
  loading = false,
  empty = { title: "No activity yet" },
  spacing = "tight",
  labels,
  role,
  ...rest
}: CandidateActivityTimelineProps) {
  const text = { ...DEFAULT_LABELS, ...labels };
  const labelled = rest["aria-label"] != null || rest["aria-labelledby"] != null;
  const props = { ...rest, role: role ?? (labelled ? "region" : undefined) };
  const shown = groups.filter((group) => group.items.length > 0);

  if (loading && shown.length === 0) {
    return (
      <Stack data-slot="candidate-activity-timeline" aria-busy gap="xs" {...props}>
        <Skeleton preset="row-compact" />
        <Skeleton preset="row-compact" />
        <Skeleton preset="row-compact" />
      </Stack>
    );
  }

  if (shown.length === 0) {
    return (
      <Stack data-slot="candidate-activity-timeline" gap="none" {...props}>
        <EmptyState
          variant="empty"
          size="inline"
          icon={History}
          title={empty.title}
          // Without host wording, no description: the kit's generic one ("Get
          // started by creating...") doesn't fit a history.
          description={empty.description ?? ""}
        />
      </Stack>
    );
  }

  return (
    <Stack data-slot="candidate-activity-timeline" gap="lg" {...props}>
      {shown.map((group) => (
        <Stack key={group.id} as="section" data-slot="candidate-activity-period" gap="none">
          <SectionHeader label={group.label} count={group.count} />
          <Timeline spacing={spacing}>
            {group.items.map((item) => (
              <ActivityRow key={item.id} item={item} labels={text} />
            ))}
          </Timeline>
        </Stack>
      ))}
    </Stack>
  );
}

"use client";

import { Button } from "@epicbagel/saas-kit/primitives/button";
import { EmptyState } from "@epicbagel/saas-kit/primitives/empty-state";
import { Icon } from "@epicbagel/saas-kit/primitives/icon";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@epicbagel/saas-kit/primitives/popover";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@epicbagel/saas-kit/primitives/select";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import { ToggleGroup, ToggleGroupItem } from "@epicbagel/saas-kit/primitives/toggle-group";
import { Briefcase, Check, ClipboardCheck, Loader2 } from "lucide-react";
import { useState, type ElementType, type ReactNode } from "react";

import type { CandidateEmptyCopy } from "./candidate-empty-copy";

/** One choice in the popover's job, stage or assessor select. */
export interface CandidateAddToJobOption<TValue extends string = string> {
  value: TValue;
  label: ReactNode;
}

/** How the popover adds people: straight to a stage, or through an assessment. */
export type CandidateAddToJobMode = "stage" | "assess";

export interface CandidateAddToJobPopoverLabels {
  /** The default trigger's text. */
  trigger: ReactNode;
  /** The popover's heading, for how many people it adds. */
  title: (count: number) => ReactNode;
  /** The job select's accessible name. */
  job: string;
  /** The job select's placeholder. */
  jobPlaceholder: ReactNode;
  /** The stage select's accessible name. */
  stage: string;
  /** Each stage in the stage select, from its label. */
  stageOption: (label: ReactNode) => ReactNode;
  /** The assessor select's accessible name. */
  assessor: string;
  /** The assessor select's placeholder. */
  assessorPlaceholder: ReactNode;
  /** The mode toggle's accessible name. */
  mode: string;
  /** The toggle that picks a stage. */
  setStage: ReactNode;
  /** The toggle that picks an assessor, and the submit button in that mode. */
  assess: ReactNode;
  /** The submit button in stage mode. */
  confirm: ReactNode;
  /** The submit button while a stage add is in flight. */
  adding: ReactNode;
  /** The submit button while an assessment is in flight. */
  assessing: ReactNode;
}

const LABELS: CandidateAddToJobPopoverLabels = {
  trigger: "Add to job",
  title: (count) => (count > 1 ? `Add ${count} candidates to a job` : "Add to job"),
  job: "Job",
  jobPlaceholder: "Pick a job…",
  stage: "Stage",
  stageOption: (label) => <>at {label}</>,
  assessor: "Assessor",
  assessorPlaceholder: "Pick an assessor…",
  mode: "How to add candidates",
  setStage: "Set stage",
  assess: "Assess",
  confirm: "Confirm",
  adding: "Adding…",
  assessing: "Assessing…",
};

export interface CandidateAddToJobPopoverProps<
  TJob extends string = string,
  TStage extends string = string,
  TAssessor extends string = string,
> {
  /** The jobs people can be added to, in order. */
  jobs: readonly CandidateAddToJobOption<TJob>[];
  /** The stages they can land at, in order. */
  stages: readonly CandidateAddToJobOption<TStage>[];
  /**
   * The stage picked each time the popover opens. Defaults to the first
   * stage, as does a value `stages` doesn't list.
   */
  defaultStage?: TStage;
  /**
   * The job picked each time the popover opens, such as a suggested match. A
   * value `jobs` doesn't list, such as a job the person was just added to and
   * the host has since left out, counts as no pick.
   */
  defaultJob?: TJob;
  /** How many people this adds; the default heading says so when it is more than one. */
  count?: number;
  /**
   * Adds the people to the picked job at the picked stage. The popover closes
   * once it settles; if it throws, it stays open with its choices, so report
   * the failure here.
   */
  onConfirm: (job: TJob, stage: TStage) => void | Promise<void>;
  /**
   * Who or what can assess people for the job instead of a stage being set,
   * such as a screening checklist. With `onAssess`, a toggle offers this
   * second mode.
   */
  assessors?: readonly CandidateAddToJobOption<TAssessor>[];
  /** Adds the people to the job and has the picked assessor assess them. */
  onAssess?: (job: TJob, assessor: TAssessor) => void | Promise<void>;
  /** The assess mode's glyph, on its toggle and submit button. */
  assessIcon?: ElementType;
  /** The element that opens the popover. Defaults to an outline "Add to job" button. */
  trigger?: ReactNode;
  /** Where the popover lines up with its trigger. Defaults to `start`. */
  align?: "start" | "center" | "end";
  /** The empty state inside the job select when there are no jobs. */
  empty?: CandidateEmptyCopy;
  labels?: Partial<CandidateAddToJobPopoverLabels>;
}

/** `value` when `options` lists it, otherwise "" (nothing picked). */
function listed(options: readonly CandidateAddToJobOption[], value: string | undefined): string {
  return value !== undefined && options.some((option) => option.value === value) ? value : "";
}

/**
 * Adds one or more people to a job: a select for the job, then one for the
 * stage they land at, and Confirm. With `assessors` and `onAssess`, a toggle
 * offers a second mode that has an assessor of your choosing assess them
 * instead. You add them and run the assessment; the popover closes once
 * your callback settles, and stays open with its choices if it throws.
 * Each time it opens it starts again from `defaultJob` and `defaultStage`,
 * so a job picked last time, which the host may since have left out of
 * `jobs`, is never submitted twice.
 *
 * The popover surface is marked `data-slot="candidate-add-to-job-popover"`.
 */
export function CandidateAddToJobPopover<
  TJob extends string = string,
  TStage extends string = string,
  TAssessor extends string = string,
>({
  jobs,
  stages,
  defaultStage,
  defaultJob,
  count = 1,
  onConfirm,
  assessors = [],
  onAssess,
  assessIcon = ClipboardCheck,
  trigger,
  align = "start",
  empty = { title: "No open jobs", description: "Create a job first, then add people to it." },
  labels,
}: CandidateAddToJobPopoverProps<TJob, TStage, TAssessor>) {
  const copy = { ...LABELS, ...labels };
  const initialStage = () => listed(stages, defaultStage) || (stages[0]?.value ?? "");
  const [open, setOpen] = useState(false);
  const [pickedJob, setJob] = useState<string>(() => listed(jobs, defaultJob));
  const [pickedStage, setStage] = useState<string>(initialStage);
  const [pickedAssessor, setAssessor] = useState<string>("");
  const [mode, setMode] = useState<CandidateAddToJobMode>("stage");
  const [busy, setBusy] = useState(false);

  // A pick the current options no longer list counts as no pick, so the
  // select shows its placeholder and Confirm stays disabled.
  const job = listed(jobs, pickedJob);
  const stage = listed(stages, pickedStage);
  const assessor = listed(assessors, pickedAssessor);

  const canAssess = assessors.length > 0 && !!onAssess;
  const assessing = canAssess && mode === "assess";

  const onOpenChange = (next: boolean) => {
    if (next) {
      setJob(listed(jobs, defaultJob));
      setStage(initialStage());
      setAssessor("");
      setMode("stage");
    }
    setOpen(next);
  };

  const submit = async () => {
    if (!job || (assessing ? !assessor : !stage)) return;
    setBusy(true);
    try {
      if (assessing) await onAssess!(job as TJob, assessor as TAssessor);
      else await onConfirm(job as TJob, stage as TStage);
      setOpen(false);
    } catch {
      // You report a failure in your own callback; the popover stays open
      // with its choices, so trying again is one tap.
    } finally {
      setBusy(false);
    }
  };

  return (
    <Popover open={open} onOpenChange={onOpenChange}>
      <PopoverTrigger asChild>
        {trigger ?? (
          <Button variant="outline" size="sm">
            <Icon icon={Briefcase} size="sm" />
            {copy.trigger}
          </Button>
        )}
      </PopoverTrigger>
      <PopoverContent
        data-slot="candidate-add-to-job-popover"
        align={align}
        padding="compact"
        spacing="compact"
      >
        <Text as="div" variant="eyebrow">
          {copy.title(count)}
        </Text>

        <Select value={job} onValueChange={setJob}>
          <SelectTrigger aria-label={copy.job}>
            <SelectValue placeholder={copy.jobPlaceholder} />
          </SelectTrigger>
          <SelectContent>
            {jobs.length === 0 && (
              <EmptyState
                variant="empty"
                size="inline"
                icon={Briefcase}
                title={empty.title}
                description={empty.description ?? ""}
              />
            )}
            {jobs.map((option) => (
              <SelectItem key={option.value} value={option.value}>
                {option.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>

        {canAssess && (
          <ToggleGroup
            type="single"
            value={mode}
            onValueChange={(value) => {
              if (value === "stage" || value === "assess") setMode(value);
            }}
            variant="outline"
            size="sm"
            aria-label={copy.mode}
          >
            <ToggleGroupItem value="stage" grow textSize="xs">
              {copy.setStage}
            </ToggleGroupItem>
            <ToggleGroupItem value="assess" grow textSize="xs">
              <Icon icon={assessIcon} size="xs" />
              {copy.assess}
            </ToggleGroupItem>
          </ToggleGroup>
        )}

        {assessing ? (
          <Select value={assessor} onValueChange={setAssessor}>
            <SelectTrigger aria-label={copy.assessor}>
              <SelectValue placeholder={copy.assessorPlaceholder} />
            </SelectTrigger>
            <SelectContent>
              {assessors.map((option) => (
                <SelectItem key={option.value} value={option.value}>
                  {option.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        ) : (
          <Select value={stage} onValueChange={setStage}>
            <SelectTrigger aria-label={copy.stage}>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {stages.map((option) => (
                <SelectItem key={option.value} value={option.value}>
                  {copy.stageOption(option.label)}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        )}

        <Button
          type="button"
          onClick={() => void submit()}
          disabled={!job || (assessing ? !assessor : !stage) || busy}
          width="full"
          size="sm"
        >
          {busy ? (
            <Icon icon={Loader2} size="md" spin />
          ) : assessing ? (
            <Icon icon={assessIcon} size="md" />
          ) : (
            <Icon icon={Check} size="md" />
          )}
          {busy
            ? assessing ? copy.assessing : copy.adding
            : assessing ? copy.assess : copy.confirm}
        </Button>
      </PopoverContent>
    </Popover>
  );
}

"use client";

import { DefinitionItem, DefinitionList } from "@epicbagel/saas-kit/primitives/definition-list";
import { Icon } from "@epicbagel/saas-kit/primitives/icon";
import { List, ListItem } from "@epicbagel/saas-kit/primitives/list";
import { PanelSection } from "@epicbagel/saas-kit/primitives/panel-section";
import { SectionHeader } from "@epicbagel/saas-kit/primitives/section-header";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import { Check } from "lucide-react";
import type { HTMLAttributes, ReactNode } from "react";

import { CandidateSummaryBullets, type CandidateSummaryBullet } from "./candidate-pipeline-list";

export interface CandidateAssessmentFact {
  label: ReactNode;
  value: ReactNode;
}

export interface CandidateAssessmentLabels {
  summary: ReactNode;
  evidence: ReactNode;
  caveats: ReactNode;
  signals: ReactNode;
}

export interface CandidateAssessmentProps
  extends HTMLAttributes<HTMLElement> {
  grade?: ReactNode;
  facts?: readonly CandidateAssessmentFact[];
  summary?: ReactNode;
  /** The evidence section's content, as a slot. Takes precedence over `evidenceItems`. */
  evidence?: ReactNode;
  /**
   * The evidence as points, drawn as a list with a check mark on each. An
   * empty list draws no section.
   */
  evidenceItems?: readonly ReactNode[];
  /** The caveats section's content, as a slot. Takes precedence over `caveatItems`. */
  caveats?: ReactNode;
  /** The caveats as points, drawn as a bulleted list. An empty list draws no section. */
  caveatItems?: readonly ReactNode[];
  /** The signals section's content, as a slot. Takes precedence over `signalItems`. */
  signals?: ReactNode;
  /**
   * The signals as lines, each with the host's sentiment, drawn through
   * CandidateSummaryBullets. An empty list draws no section.
   */
  signalItems?: readonly CandidateSummaryBullet[];
  labels?: Partial<CandidateAssessmentLabels>;
  /**
   * The kit PanelSection's padding. `default` pads the assessment like a
   * card's section. `none` sits it flush in a container the host already
   * pads, such as a profile dialog's body, so it lines up with whatever
   * follows it there.
   */
  padding?: "none" | "compact" | "default";
}

const DEFAULT_LABELS: CandidateAssessmentLabels = {
  summary: "Assessment",
  evidence: "Evidence",
  caveats: "Caveats",
  signals: "Signals",
};

function AssessmentSection({
  label,
  children,
}: {
  label: ReactNode;
  children: ReactNode;
}) {
  return (
    <Stack gap="sm">
      <SectionHeader label={label} spacing="none" />
      <Text as="div" variant="muted" size="sm">
        {children}
      </Text>
    </Stack>
  );
}

function EvidenceList({ items }: { items: readonly ReactNode[] }) {
  return (
    <List data-slot="candidate-assessment-evidence" spacing="tight" marker="none" textSize="sm">
      {items.map((item, index) => (
        <ListItem key={index} layout="row" gap="sm" align="start">
          <Icon icon={Check} tone="success" align="start" />
          <Text as="span" variant="inherit" size="sm">{item}</Text>
        </ListItem>
      ))}
    </List>
  );
}

function CaveatList({ items }: { items: readonly ReactNode[] }) {
  return (
    <List data-slot="candidate-assessment-caveats" spacing="tight" marker="disc" textSize="sm" tone="muted">
      {items.map((item, index) => (
        <ListItem key={index}>{item}</ListItem>
      ))}
    </List>
  );
}

/** The host's slot when it gave one, else its items drawn as a list, else nothing. */
function sectionContent<T>(
  slot: ReactNode,
  items: readonly T[] | undefined,
  draw: (items: readonly T[]) => ReactNode,
): ReactNode {
  if (slot != null) return slot;
  return items && items.length > 0 ? draw(items) : null;
}

/**
 * Presentation-only assessment. Hosts own scoring, thresholds, and policy.
 *
 * Evidence, caveats and signals each take a slot or items. Items are drawn in
 * the package's own lists: evidence with a check mark on each point, caveats
 * as bullets, and signals through CandidateSummaryBullets with the host's
 * sentiment on each line. A section with neither is left out. The root is the
 * kit PanelSection, marked `data-slot="candidate-assessment"`; the evidence
 * and caveat lists are marked `candidate-assessment-evidence` and
 * `candidate-assessment-caveats`.
 */
export function CandidateAssessment({
  grade,
  facts = [],
  summary,
  evidence,
  evidenceItems,
  caveats,
  caveatItems,
  signals,
  signalItems,
  labels,
  padding = "default",
  ...props
}: CandidateAssessmentProps) {
  const resolvedLabels = { ...DEFAULT_LABELS, ...labels };
  const evidenceContent = sectionContent(evidence, evidenceItems, (items) => <EvidenceList items={items} />);
  const caveatContent = sectionContent(caveats, caveatItems, (items) => <CaveatList items={items} />);
  const signalContent = sectionContent(signals, signalItems, (items) => <CandidateSummaryBullets bullets={items} presentation="body" />);

  return (
    <PanelSection data-slot="candidate-assessment" padding={padding} {...props}>
      <Stack gap="lg">
        {grade}
        {facts.length > 0 ? (
          <DefinitionList>
            {facts.map((fact, index) => (
              <DefinitionItem key={index} label={fact.label}>
                {fact.value}
              </DefinitionItem>
            ))}
          </DefinitionList>
        ) : null}
        {summary != null ? (
          <AssessmentSection label={resolvedLabels.summary}>
            {summary}
          </AssessmentSection>
        ) : null}
        {evidenceContent != null ? (
          <AssessmentSection label={resolvedLabels.evidence}>
            {evidenceContent}
          </AssessmentSection>
        ) : null}
        {caveatContent != null ? (
          <AssessmentSection label={resolvedLabels.caveats}>
            {caveatContent}
          </AssessmentSection>
        ) : null}
        {signalContent != null ? (
          <AssessmentSection label={resolvedLabels.signals}>
            {signalContent}
          </AssessmentSection>
        ) : null}
      </Stack>
    </PanelSection>
  );
}

"use client";

import { Badge } from "@epicbagel/saas-kit/primitives/badge";
import { Button } from "@epicbagel/saas-kit/primitives/button";
import { CallCard, type CallParticipant, type CallSegment } from "@epicbagel/saas-kit/primitives/call-card";
import { DeleteConfirmationDialog } from "@epicbagel/saas-kit/primitives/delete-confirmation-dialog";
import { EmptyState } from "@epicbagel/saas-kit/primitives/empty-state";
import { Icon } from "@epicbagel/saas-kit/primitives/icon";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import { BriefcaseBusiness, Loader2 } from "lucide-react";
import { useState, type ReactNode } from "react";

import type { CallInsights } from "./call-data";

// The call helpers and types live in a module without a client boundary, so
// a server can normalize call data too; they are re-exported here, beside the
// card that reads them.
export {
  normalizeCallParticipants,
  normalizeCallSegments,
  type CallInsights,
  type CallInsightsStatus,
  type CallParticipant,
  type CallPerson,
  type CallSegment,
  type CallTranscript,
  type SearchCallPeople,
} from "./call-data";

/** Host-owned wording for the card's fixed parts. */
export interface CandidateCallCardLabels {
  /** The heading when the call has no title. */
  untitled: string;
  /** The transcript toggle while it is closed. */
  showTranscript: string;
  unlink: ReactNode;
  unlinkTitle: string;
  /** What unlinking does, in the confirmation. */
  unlinkDescription: string;
  /** Names the call in the confirmation when it has no title. */
  unlinkItem: string;
  unlinkConfirm: string;
  /** Starts the first check of the call against open roles. */
  check: ReactNode;
  /** Runs the check again once insights exist. */
  recheck: ReactNode;
  /** Either check button while a check runs. */
  checking: ReactNode;
  noRolesTitle: string;
  noRolesDescription: string;
}

const DEFAULT_LABELS: CandidateCallCardLabels = {
  untitled: "Untitled call",
  showTranscript: "Show transcript",
  unlink: "Unlink",
  unlinkTitle: "Unlink this call?",
  unlinkDescription: "The call will be removed from this person. Its transcript is kept.",
  unlinkItem: "this call",
  unlinkConfirm: "Unlink call",
  check: "Check against open jobs",
  recheck: "Recheck against open jobs",
  checking: "Checking…",
  noRolesTitle: "No suggested roles yet",
  noRolesDescription: "No other live role fits this person from this call.",
};

export interface CandidateCallCardProps {
  /** The call's title. Without one, the card says `labels.untitled`. */
  title?: string | null;
  /** Where the call came from, already worded. */
  source?: ReactNode;
  /** When it happened, already formatted. */
  timestamp?: ReactNode;
  /** Who was on it. `normalizeCallParticipants` prepares raw lists. */
  participants?: readonly CallParticipant[];
  /** Speaker-labelled turns. `normalizeCallSegments` prepares raw lists. */
  segments?: readonly CallSegment[] | null;
  /** The flat transcript, shown when there are no segments. */
  transcript?: ReactNode;
  /** How sure the host is that the call belongs to this person, shown as a badge. */
  confidence?: ReactNode;
  /**
   * Called once the recruiter confirms the unlink. The button shows a spinner
   * until it settles; the host removes the card, or reports why it couldn't.
   */
  onUnlink: () => Promise<void>;
  /** The host's check of the call against its open roles. */
  insights: CallInsights;
  /**
   * The roles the check suggested, usually a CandidateRoleMatchSummary. Once
   * insights are ready and this is empty, the card says no role fits.
   */
  roleMatches?: ReactNode;
  labels?: Partial<CandidateCallCardLabels>;
  /** Class for the card. Its root is the kit's CallCard, which takes no other attributes. */
  className?: string;
}

const isShown = (node: ReactNode) => node != null && node !== false && node !== "";

/**
 * One call linked to a person: the kit's CallCard with a confidence badge,
 * an unlink action behind a confirmation, and the check of the call against
 * open roles. Before insights exist the card offers the check and shows its
 * last error; once they do, it shows the host's role matches, or an empty
 * state when none fit, and offers a recheck.
 */
export function CandidateCallCard({
  title,
  source,
  timestamp,
  participants,
  segments,
  transcript,
  confidence,
  onUnlink,
  insights,
  roleMatches,
  labels,
  className,
}: CandidateCallCardProps) {
  const text = { ...DEFAULT_LABELS, ...labels };
  const [confirmUnlink, setConfirmUnlink] = useState(false);
  const [unlinking, setUnlinking] = useState(false);
  const ready = insights.status === "ready";

  return (
    <>
      <CallCard
        className={className}
        title={title || text.untitled}
        source={source}
        timestamp={timestamp}
        participants={participants as CallParticipant[] | undefined}
        segments={(segments ?? undefined) as CallSegment[] | undefined}
        transcript={transcript}
        transcriptLabel={text.showTranscript}
        headerAside={isShown(confidence)
          ? <Badge variant="secondary" size="micro" titleCase="capitalize">{confidence}</Badge>
          : undefined}
        actions={(
          <Stack gap="sm" width="full">
            <Button variant="ghost" size="sm" disabled={unlinking} onClick={() => setConfirmUnlink(true)}>
              {unlinking ? <Icon icon={Loader2} size="sm" spin /> : text.unlink}
            </Button>
            {ready ? (
              <Stack gap="sm">
                {isShown(roleMatches) ? roleMatches : (
                  <EmptyState
                    variant="empty"
                    size="inline"
                    icon={BriefcaseBusiness}
                    title={text.noRolesTitle}
                    description={text.noRolesDescription}
                  />
                )}
                <Button variant="ghost" size="sm" onClick={() => insights.onGenerate(true)} disabled={insights.generating}>
                  {insights.generating ? text.checking : text.recheck}
                </Button>
              </Stack>
            ) : (
              <Stack gap="xs">
                {insights.error && <Text size="xs" tone="destructive">{insights.error}</Text>}
                <Button variant="outline" size="sm" onClick={() => insights.onGenerate(false)} disabled={insights.generating}>
                  {insights.generating ? text.checking : text.check}
                </Button>
              </Stack>
            )}
          </Stack>
        )}
      />
      <DeleteConfirmationDialog
        open={confirmUnlink}
        onOpenChange={setConfirmUnlink}
        title={text.unlinkTitle}
        description={text.unlinkDescription}
        itemName={title || text.unlinkItem}
        confirmText={text.unlinkConfirm}
        onConfirm={() => {
          setConfirmUnlink(false);
          setUnlinking(true);
          void onUnlink().finally(() => setUnlinking(false));
        }}
      />
    </>
  );
}

