"use client";

import { Button } from "@epicbagel/saas-kit/primitives/button";
import { Icon } from "@epicbagel/saas-kit/primitives/icon";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { ThumbsDown, ThumbsUp } from "lucide-react";
import type { HTMLAttributes, MouseEvent, ReactNode } from "react";

/** The two calls a reviewer can make on a candidate. */
export type CandidateDecisionChoice = "yes" | "no";

/** Host-owned wording for the two buttons. */
export interface CandidateDecisionButtonsLabels {
  yes: ReactNode;
  no: ReactNode;
}

const DEFAULT_LABELS: CandidateDecisionButtonsLabels = {
  yes: "Yes",
  no: "No",
};

export interface CandidateDecisionButtonsProps
  extends Omit<HTMLAttributes<HTMLElement>, "children"> {
  /**
   * Called with the button a person pressed. Nothing is recorded yet: the
   * host usually opens its own sheet or dialog to ask why, then saves.
   */
  onChoose: (decision: CandidateDecisionChoice) => void;
  size?: "sm" | "default";
  /** Share the available width between the two buttons, as in an action bar. */
  stretch?: boolean;
  labels?: Partial<CandidateDecisionButtonsLabels>;
  /**
   * Rendered inside the group after the buttons, usually the host's reason
   * sheet. Events that bubble out of its portal then stop here with the
   * buttons' own, instead of reaching a clickable card.
   */
  children?: ReactNode;
}

/**
 * Yes and No as equal, neutral outline buttons with thumbs icons. Neither is
 * styled as the default answer.
 *
 * Unlike `CandidateDecisionBar`, which shows a recorded value as a pressed
 * option, these buttons hold no value: a press starts the host's decision
 * flow. Every click inside the group stops propagating, so the buttons work
 * inside a clickable candidate card. The root is marked
 * `data-slot="candidate-decision-buttons"`.
 */
export function CandidateDecisionButtons({
  onChoose,
  size = "sm",
  stretch = false,
  labels,
  children,
  onClick,
  ...props
}: CandidateDecisionButtonsProps) {
  const text = { ...DEFAULT_LABELS, ...labels };

  return (
    <Stack
      data-slot="candidate-decision-buttons"
      direction="horizontal"
      gap="sm"
      grow={stretch}
      {...props}
      onClick={(event: MouseEvent<HTMLElement>) => {
        event.stopPropagation();
        onClick?.(event);
      }}
    >
      <Button grow={stretch} size={size} variant="outline" onClick={() => onChoose("yes")}>
        <Icon icon={ThumbsUp} size="sm" /> {text.yes}
      </Button>
      <Button grow={stretch} size={size} variant="outline" onClick={() => onChoose("no")}>
        <Icon icon={ThumbsDown} size="sm" /> {text.no}
      </Button>
      {children}
    </Stack>
  );
}

"use client";

import { Badge } from "@epicbagel/saas-kit/primitives/badge";
import { Button } from "@epicbagel/saas-kit/primitives/button";
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@epicbagel/saas-kit/primitives/dialog";
import { Icon } from "@epicbagel/saas-kit/primitives/icon";
import { Label } from "@epicbagel/saas-kit/primitives/label";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import { Textarea } from "@epicbagel/saas-kit/primitives/textarea";
import { Loader2 } from "lucide-react";
import { useEffect, useId, useState, type ReactNode } from "react";

/** Host-owned wording for the dialog's fixed parts. */
export interface CandidateDecisionReasonDialogLabels {
  /** The eyebrow over the suggestion chips. */
  suggestions: ReactNode;
  /**
   * The reason field's label. Defaults to "Why?", or to "Why? (optional)"
   * with `reasonOptional`.
   */
  reason: ReactNode;
  cancel: ReactNode;
}

const DEFAULT_LABELS: CandidateDecisionReasonDialogLabels = {
  suggestions: "Tap a signal to use it as the reason",
  reason: "Why?",
  cancel: "Cancel",
};

/** The field's default label where the decision can be confirmed without a reason. */
const OPTIONAL_REASON_LABEL = "Why? (optional)";

/** Joins a tapped suggestion onto the reason typed so far. */
const SUGGESTION_SEPARATOR = " · ";

export interface CandidateDecisionReasonDialogProps {
  open: boolean;
  /**
   * Names the decision and who it is about, such as "Reject: Mei Tanaka", or
   * "Reject 12 candidates" for a decision on several people at once.
   */
  title: ReactNode;
  /** One-tap reasons, already worded. Tapping one adds it to the reason. */
  suggestions?: readonly string[];
  placeholder: string;
  confirmLabel: ReactNode;
  /** `destructive` for a rejection, `default` to move forward. */
  confirmTone?: "default" | "destructive";
  /**
   * Lets the decision be confirmed with no reason, for a quick decision
   * where a reason helps but mustn't slow it down, such as one on several
   * people at once. The reason is required without it.
   */
  reasonOptional?: boolean;
  /**
   * Called with the trimmed reason, which is an empty string when
   * `reasonOptional` let the person confirm without one. The confirm button
   * shows a spinner and the dialog's buttons stay disabled until it settles;
   * the host closes the dialog once the decision is saved.
   */
  onSubmit: (reason: string) => Promise<void>;
  /** Called from Cancel, Escape and the close button. */
  onClose: () => void;
  labels?: Partial<CandidateDecisionReasonDialogLabels>;
  /** The reason field's id. A generated one is used when omitted. */
  id?: string;
}

/**
 * Asks why before a decision is recorded, on one candidate or on several: a
 * typed reason, optionally started from one-tap suggestions. The reason is
 * required unless `reasonOptional` says the decision can go ahead without
 * one.
 *
 * The reason resets each time the dialog opens. The host owns the decision,
 * its wording (the title, the confirm label and `labels`) and what is saved;
 * the root is the kit's dialog content and keeps its
 * `data-slot="dialog-content"`.
 */
export function CandidateDecisionReasonDialog(props: CandidateDecisionReasonDialogProps) {
  // Only generate an id when the host has not supplied one, so a host id
  // costs nothing.
  return props.id ? (
    <ReasonDialog {...props} id={props.id} />
  ) : (
    <ReasonDialogWithGeneratedId {...props} />
  );
}

function ReasonDialogWithGeneratedId(props: CandidateDecisionReasonDialogProps) {
  const id = useId();
  return <ReasonDialog {...props} id={id} />;
}

function ReasonDialog({
  open,
  title,
  suggestions = [],
  placeholder,
  confirmLabel,
  confirmTone = "default",
  reasonOptional = false,
  onSubmit,
  onClose,
  labels,
  id,
}: CandidateDecisionReasonDialogProps & { id: string }) {
  const text = {
    ...DEFAULT_LABELS,
    // The field says so itself where it can be left empty.
    ...(reasonOptional ? { reason: OPTIONAL_REASON_LABEL } : null),
    ...labels,
  };
  const [reason, setReason] = useState("");
  const [submitting, setSubmitting] = useState(false);

  useEffect(() => {
    if (!open) return;
    setReason("");
    setSubmitting(false);
  }, [open]);

  const submit = async () => {
    setSubmitting(true);
    try {
      await onSubmit(reason.trim());
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={(next) => !next && onClose()}>
      <DialogContent size="sm">
        <DialogHeader>
          <DialogTitle size="base">{title}</DialogTitle>
        </DialogHeader>
        <Stack direction="vertical" gap="sm">
          {suggestions.length > 0 && (
            <Stack gap="none">
              <Text as="div" variant="eyebrow" marginBottom="sm">
                {text.suggestions}
              </Text>
              <Stack direction="horizontal" gap="xs" wrap>
                {suggestions.map((suggestion, index) => (
                  <Badge
                    key={index}
                    variant="outline"
                    size="micro"
                    weight="normal"
                    interactive
                    onClick={() =>
                      // Spaces alone are no reason to join the suggestion onto.
                      setReason((current) =>
                        current.trim() ? `${current}${SUGGESTION_SEPARATOR}${suggestion}` : suggestion,
                      )
                    }
                  >
                    {suggestion}
                  </Badge>
                ))}
              </Stack>
            </Stack>
          )}
          <Stack gap="xs">
            <Label htmlFor={id} appearance="eyebrow">
              {text.reason}
            </Label>
            <Textarea
              id={id}
              value={reason}
              onChange={(event) => setReason(event.target.value)}
              rows={3}
              placeholder={placeholder}
              aria-required={!reasonOptional}
              autoFocus
            />
          </Stack>
        </Stack>
        <DialogFooter>
          <Button variant="ghost" onClick={onClose} disabled={submitting}>
            {text.cancel}
          </Button>
          <Button
            onClick={submit}
            disabled={submitting || (!reasonOptional && reason.trim().length === 0)}
            variant={confirmTone}
          >
            {submitting ? <Icon icon={Loader2} size="md" spin /> : null}
            {confirmLabel}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

"use client";

import { useDictation } from "@epicbagel/saas-kit/hooks/use-dictation";
import { Button } from "@epicbagel/saas-kit/primitives/button";
import { Chat } from "@epicbagel/saas-kit/primitives/chat";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogTitle,
} from "@epicbagel/saas-kit/primitives/dialog";
import { EmptyState } from "@epicbagel/saas-kit/primitives/empty-state";
import { Icon } from "@epicbagel/saas-kit/primitives/icon";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { ArrowRight, Loader2, X } from "lucide-react";
import { useEffect, useRef, useState, type ReactNode } from "react";

import type { CandidateDecisionChoice } from "./candidate-decision-buttons";

/** Host-owned wording for the sheet's fixed parts. */
export interface CandidateDecisionReasonSheetLabels {
  /** The close button's tooltip and accessible name. Closing decides nothing. */
  cancel: string;
  /** Under the mic. */
  speak: ReactNode;
  /** The switch from speaking to typing. */
  typeInstead: ReactNode;
  /** Over the one-tap reasons. */
  reasons: string;
  /** The typed reason's placeholder. */
  placeholder: string;
  /** In place of the composer while a promise from `onConfirm` is pending. */
  saving: string;
  /** Under the composer when a promise from `onConfirm` rejects. */
  failed: string;
}

const DEFAULT_LABELS: CandidateDecisionReasonSheetLabels = {
  cancel: "Cancel",
  speak: "Tap to speak",
  typeInstead: "or type instead",
  reasons: "or pick a reason",
  placeholder: "Type a reason…",
  saving: "Saving…",
  failed: "That didn't save. Try again.",
};

export interface CandidateDecisionReasonSheetProps {
  open: boolean;
  /** Called from the close button and Escape. Nothing is decided. */
  onClose: () => void;
  /**
   * The answer being explained. It only words the defaults ("Why no?",
   * "Skip — just mark No"): the sheet neither holds nor saves a decision, so
   * leave it out for any other question and pass the wording yourself.
   */
  decision?: CandidateDecisionChoice;
  /** The candidate's name, for the default wording only. */
  candidateName?: string;
  /** The question, as the sheet's heading and its accessible name. */
  title?: ReactNode;
  /** The line under the question, which also describes the sheet to a screen reader. */
  subtitle?: ReactNode;
  /** The dictation overlay's title, such as "Why no on Mei Tanaka?". */
  voiceTitle?: string;
  /** One-tap reasons, already worded. Picking one confirms with it. */
  reasons?: readonly string[];
  /**
   * Called with the reason a person spoke, typed or picked, trimmed, or with
   * none when they skipped. The host saves the decision and closes the sheet.
   * It may return a promise: while that is pending the sheet shows
   * `labels.saving` in place of the composer and Skip is disabled, though
   * the sheet can still be closed; if it rejects, the composer comes back
   * with a typed or spoken reason still in it and `labels.failed` under it.
   */
  onConfirm: (reason?: string) => unknown;
  /**
   * Takes Skip away, so the only ways out are a reason or the close button.
   * A reason is optional without it: encouraged, never demanded.
   */
  reasonRequired?: boolean;
  /** Skip's wording, such as "Skip — just reject Mei Tanaka". */
  skipLabel?: ReactNode;
  /**
   * Host content over the bottom row, such as a switch that changes what the
   * decision does. Its state stays the host's, read when `onConfirm` runs.
   */
  footer?: ReactNode;
  /** Host controls in the bottom row, before Skip, such as another way to decide. */
  actions?: ReactNode;
  /**
   * `false` leaves dictation out, and the sheet opens on the typed reason.
   * It also opens there wherever dictation can't run.
   */
  voice?: boolean;
  /** The language dictation listens for, as a BCP 47 tag. */
  voiceLang?: string;
  labels?: Partial<CandidateDecisionReasonSheetLabels>;
}

function isPromiseLike(value: unknown): value is PromiseLike<unknown> {
  return value != null && typeof (value as PromiseLike<unknown>).then === "function";
}

function shown(node: ReactNode): boolean {
  return node != null && node !== false && node !== "";
}

function defaultTitle(decision: CandidateDecisionChoice | undefined): string {
  if (decision === "yes") return "Why yes?";
  if (decision === "no") return "Why no?";
  return "Why?";
}

function defaultSubtitle(candidateName: string | undefined, hasReasons: boolean): string {
  const whose = candidateName ? ` for ${candidateName}` : "";
  return hasReasons ? `Give your reason${whose}, or pick one.` : `Give your reason${whose}.`;
}

function defaultVoiceTitle(
  decision: CandidateDecisionChoice | undefined,
  candidateName: string | undefined,
  title: ReactNode,
): string {
  if (decision && candidateName) return `Why ${decision} on ${candidateName}?`;
  return typeof title === "string" ? title : defaultTitle(decision);
}

function defaultSkipLabel(decision: CandidateDecisionChoice | undefined): string {
  if (decision === "yes") return "Skip — just mark Yes";
  if (decision === "no") return "Skip — just mark No";
  return "Skip";
}

/**
 * Whether dictation can run here, as the kit's own mic decides it: the
 * host's transport from a `DictationProvider`, or else the browser's speech
 * recognition. `null` until the first effects have run, which is when the
 * kit finds out.
 */
function useDictationSupport(): boolean | null {
  const { supported } = useDictation();
  const [known, setKnown] = useState(false);
  // Declared after the kit's own effect, so both land in one render.
  useEffect(() => setKnown(true), []);
  return known ? supported : null;
}

/**
 * The voice-first "Why?" asked once a reviewer has decided: speaking the
 * reason is the default, a suggested reason is one tap, and typing is a tap
 * away. Each of them calls `onConfirm` with that reason; Skip calls it with
 * none; the close button and Escape call `onClose`, and nothing is decided.
 *
 * The mic, the reason chips and the composer are the kit's `Chat` in its
 * voice-first empty state, inside the kit's `Dialog`, so the sheet keeps its
 * focus when it opens from another dialog, such as a candidate's profile.
 * Dictation is wired as everywhere else in this library: the kit's mic uses
 * the transport of the host's `DictationProvider`
 * (`@epicbagel/saas-kit/primitives/dictation-provider`), or the browser's
 * speech recognition without one. Where neither can run, or with
 * `voice={false}`, the sheet opens on the typed reason instead.
 *
 * Clicks and key presses inside the sheet stop at it, so it can be rendered
 * inside a clickable candidate card, whose handlers they would otherwise
 * reach through the portal. Nothing of the sheet is mounted while it is
 * closed, so each opening starts afresh, and when it closes focus goes back
 * to the control it was opened from, if that is still there. The host owns
 * the decision, the suggested reasons and every word.
 *
 * The root is the kit's dialog content and keeps its
 * `data-slot="dialog-content"`; the sheet's own layout inside it is marked
 * `data-slot="candidate-decision-reason-sheet"`, with `data-decision` when a
 * `decision` is given, and its bottom bar
 * `data-slot="candidate-decision-reason-sheet-footer"`.
 */
export function CandidateDecisionReasonSheet({
  open,
  onClose,
  decision,
  candidateName,
  title,
  subtitle,
  reasons = [],
  ...body
}: CandidateDecisionReasonSheetProps) {
  // What had focus when the sheet opened, usually the Yes or No that asked.
  const opener = useRef<Element | null>(null);

  // A host clears its decision as it closes the sheet, and the wording goes
  // with it: closed, the sheet is gone at once rather than fade out reworded.
  if (!open) return null;

  // The same reason twice would be one chip drawn twice.
  const chips = [...new Set(reasons.map((reason) => reason.trim()).filter(Boolean))];
  const heading = shown(title) ? title : defaultTitle(decision);
  const description = subtitle === undefined ? defaultSubtitle(candidateName, chips.length > 0) : subtitle;
  const described = shown(description);

  return (
    <Dialog open onOpenChange={(next) => { if (!next) onClose(); }}>
      <DialogContent
        size="wide"
        height="viewport-lg"
        layout="column"
        padding="none"
        overflow="hidden"
        hideClose
        // With no description, tell Radix so rather than point at nothing.
        {...(described ? {} : { "aria-describedby": undefined })}
        onOpenAutoFocus={() => {
          opener.current = document.activeElement;
        }}
        // Radix hands focus back to a dialog's trigger, and a sheet opened by
        // the host's own state has none.
        onCloseAutoFocus={(event) => {
          const from = opener.current;
          if (!(from instanceof HTMLElement) || !from.isConnected) return;
          event.preventDefault();
          from.focus();
        }}
        // React events bubble out of a portal along the component tree, so
        // without these a click or a key press in the sheet reaches a
        // clickable card it was rendered in, and typing a space would open
        // the card. Stopping them here cancels neither typing nor sending.
        onClick={(event) => event.stopPropagation()}
        onKeyDown={(event) => event.stopPropagation()}
      >
        {/*
          The dialog's name and description, read when it opens. The words a
          person sees are the composer's own heading and line below, so these
          two are hidden from a screen reader's reading order: it would
          otherwise meet each of them twice.
        */}
        <DialogTitle visuallyHidden asChild>
          <span aria-hidden="true">{heading}</span>
        </DialogTitle>
        {described ? (
          <DialogDescription visuallyHidden asChild>
            <span aria-hidden="true">{description}</span>
          </DialogDescription>
        ) : null}
        <ReasonSheetBody
          {...body}
          onClose={onClose}
          decision={decision}
          candidateName={candidateName}
          heading={heading}
          description={described ? description : undefined}
          chips={chips}
        />
      </DialogContent>
    </Dialog>
  );
}

type ReasonSheetBodyProps = Omit<
  CandidateDecisionReasonSheetProps,
  "open" | "title" | "subtitle" | "reasons"
> & {
  heading: ReactNode;
  description: ReactNode;
  chips: readonly string[];
};

/**
 * What the sheet holds: mounted afresh each time it opens, so a draft, the
 * switch to typing and a failed save never carry over to the next person.
 */
function ReasonSheetBody({
  onClose,
  decision,
  candidateName,
  heading,
  description,
  voiceTitle,
  chips,
  onConfirm,
  reasonRequired = false,
  skipLabel,
  footer,
  actions,
  voice = true,
  voiceLang,
  labels,
}: ReasonSheetBodyProps) {
  const text = { ...DEFAULT_LABELS, ...labels };
  const dictation = useDictationSupport();
  const [saving, setSaving] = useState(false);
  const [failed, setFailed] = useState(false);
  // A second tap before the first re-render must not confirm twice.
  const inFlight = useRef(false);

  const confirm = async (reason?: string) => {
    if (inFlight.current) return;
    setFailed(false);
    try {
      const result = onConfirm(reason);
      if (isPromiseLike(result)) {
        inFlight.current = true;
        setSaving(true);
        await result;
      }
    } catch (cause) {
      setFailed(true);
      // The composer puts a typed or spoken reason back when it sees this.
      throw cause;
    } finally {
      inFlight.current = false;
      setSaving(false);
    }
  };

  const hasBottomRow = shown(actions) || !reasonRequired;

  return (
    <Stack
      data-slot="candidate-decision-reason-sheet"
      data-decision={decision}
      direction="vertical"
      gap="none"
      grow
      minHeight="zero"
    >
      <Stack
        direction="horizontal"
        gap="none"
        align="center"
        justify="end"
        paddingX="md"
        paddingTop="safe"
        paddingBottom="sm"
      >
        {/* Never disabled: a save that hangs must not hold a person in the sheet. */}
        <Button type="button" variant="ghost" size="icon-md" title={text.cancel} onClick={onClose}>
          <Icon icon={X} size="lg" />
        </Button>
      </Stack>

      <Stack direction="vertical" gap="none" justify="center" grow overflow="y-auto" paddingX="md">
        {/* A centred column: the composer would otherwise run edge to edge on a wide screen. */}
        <Stack gap="none" centered width="full" maxWidth="xl">
          {dictation === null ? null : (
            <Chat
              messages={[]}
              onSend={(reason) => confirm(reason.trim() || undefined)}
              // The failure shows under the composer; the host has the rejection itself.
              onSendError={() => undefined}
              pending={saving}
              emptyPendingContent={(
                // The composer is gone while this shows, so it is said aloud.
                <Stack role="status" gap="none" width="full">
                  <EmptyState
                    variant="empty"
                    size="md"
                    icon={Loader2}
                    iconMotion="spin"
                    surface="plain"
                    title={text.saving}
                    description=""
                  />
                </Stack>
              )}
              error={failed ? text.failed : null}
              defaultMode={voice && dictation ? "voice" : "text"}
              voice={voice}
              voiceLang={voiceLang}
              voiceTitle={voiceTitle ?? defaultVoiceTitle(decision, candidateName, heading)}
              voiceHeroLabel={text.speak}
              voiceHeroSwitchLabel={text.typeInstead}
              emptyTitle={heading}
              emptySubtitle={description}
              examplePrompts={chips}
              examplePromptsLabel={text.reasons}
              placeholder={text.placeholder}
            />
          )}
        </Stack>
      </Stack>

      {shown(footer) || hasBottomRow ? (
        <Stack
          data-slot="candidate-decision-reason-sheet-footer"
          direction="vertical"
          gap="sm"
          align="center"
          border="top"
          paddingX="lg"
          paddingY="md"
        >
          {footer}
          {hasBottomRow ? (
            <Stack direction="horizontal" gap="sm" align="center" justify="center" wrap>
              {actions}
              {reasonRequired ? null : (
                <Button
                  type="button"
                  variant="outline"
                  size="lg"
                  disabled={saving}
                  // A failed save shows as `labels.failed`; the host has the rejection itself.
                  onClick={() => void confirm().catch(() => undefined)}
                >
                  {shown(skipLabel) ? skipLabel : defaultSkipLabel(decision)}
                  <Icon icon={ArrowRight} size="md" marginStart="sm" />
                </Button>
              )}
            </Stack>
          ) : null}
        </Stack>
      ) : null}
    </Stack>
  );
}

import { Badge } from "@epicbagel/saas-kit/primitives/badge";
import { Card } from "@epicbagel/saas-kit/primitives/card";
import { FlexItem } from "@epicbagel/saas-kit/primitives/flex-item";
import { PanelSection } from "@epicbagel/saas-kit/primitives/panel-section";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { StatusIconTile } from "@epicbagel/saas-kit/primitives/status-icon-tile";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import { Flag } from "lucide-react";
import type { HTMLAttributes, ReactNode } from "react";

import type { CandidateGradeTone } from "./candidate-grade";

/** A recorded decision on the person for one role. */
export interface CandidateDecisionSummaryDecision {
  /** Whose decision it is, such as "Your decision". */
  heading: ReactNode;
  /** The verdict, such as "Yes". */
  verdict: ReactNode;
  /** Colours the flag tile and the verdict. */
  tone: "positive" | "negative";
  /** Where the decision left the person, such as their stage. */
  stage: ReactNode;
  /** Why, kept as written. */
  reason?: ReactNode;
}

/** An automated assessment of the person for the same role. */
export interface CandidateDecisionSummaryAssessment {
  /** The grade in the tile, such as "A". */
  letter: ReactNode;
  /** The tile's badge tone. */
  tone: CandidateGradeTone;
  /** The tile's tooltip. */
  title?: string;
  /** The row's eyebrow, such as "AI assessment". */
  heading: ReactNode;
  /** What the grade means, and anything still pending. */
  label: ReactNode;
}

export interface CandidateDecisionSummaryProps
  extends Omit<HTMLAttributes<HTMLElement>, "children"> {
  decision?: CandidateDecisionSummaryDecision;
  assessment?: CandidateDecisionSummaryAssessment;
}

/**
 * The headline of a person's detail for the role in focus: the recorded
 * decision with a flag tile, and the assessment grade in a tile, in one card
 * on a muted band. Either row may be left out; with neither it renders
 * nothing. Unlike CandidateAssessment, which lays out a full write-up, this
 * is a two-line summary.
 *
 * The root is the kit PanelSection, marked `data-slot="candidate-decision-summary"`.
 */
export function CandidateDecisionSummary({
  decision,
  assessment,
  ...props
}: CandidateDecisionSummaryProps) {
  if (!decision && !assessment) return null;
  const positive = decision?.tone === "positive";
  const reason = decision?.reason;

  return (
    <PanelSection data-slot="candidate-decision-summary" border="bottom" surface="muted" {...props}>
      <Card overflow="hidden">
        {decision && (
          <Stack direction="horizontal" gap="sm" align="start" padding="compact">
            <StatusIconTile icon={Flag} tone={positive ? "success" : "destructive"} />
            <FlexItem minWidth="zero">
              <Text variant="eyebrow" weight="semibold">{decision.heading}</Text>
              <Stack direction="horizontal" gap="xs" marginTop="xs" align="baseline" textSize="sm">
                <Text variant="inherit" as="span" weight="semibold" tone={positive ? "success" : "destructive"}>
                  {decision.verdict}
                </Text>
                <Text variant="inherit" as="span" tone="muted">· {decision.stage}</Text>
              </Stack>
              {reason != null && reason !== false && reason !== "" && (
                <Text size="sm" tone="muted" marginTop="tight" whitespace="pre-wrap">{reason}</Text>
              )}
            </FlexItem>
          </Stack>
        )}

        {assessment && (
          <Stack
            direction="horizontal"
            gap="compact"
            align="start"
            paddingX="md"
            paddingY="section"
            border={decision ? "top" : "none"}
          >
            <Badge
              variant={assessment.tone}
              size="tile"
              shape="rounded"
              weight="bold"
              shrink
              marginTop="tight"
              title={assessment.title}
            >
              {assessment.letter}
            </Badge>
            <FlexItem minWidth="zero">
              <Text variant="eyebrow" weight="semibold">{assessment.heading}</Text>
              <Text size="sm" tone="muted" marginTop="tight">{assessment.label}</Text>
            </FlexItem>
          </Stack>
        )}
      </Card>
    </PanelSection>
  );
}

"use client";

import {
  ConnectionStatusBar,
  type ConnectionStatusBarAction,
  type ConnectionStatusBarFact,
  type ConnectionStatusBarState,
} from "@epicbagel/saas-kit/primitives/connection-status-bar";
import type { ReactNode } from "react";

type CandidateDestinationActionBase = Omit<
  ConnectionStatusBarAction,
  "ariaLabel" | "iconOnly"
>;

/** Icon-only actions must always supply the accessible name hidden visually. */
export type CandidateDestinationAction =
  | (CandidateDestinationActionBase & {
      iconOnly: true;
      ariaLabel: string;
    })
  | (CandidateDestinationActionBase & {
      iconOnly?: false;
      ariaLabel?: string;
    });
export type CandidateDestinationFact = ConnectionStatusBarFact;
export type CandidateDestinationState = ConnectionStatusBarState;

export interface CandidateDestinationStatusProps {
  state: CandidateDestinationState;
  name: ReactNode;
  description?: ReactNode;
  facts?: readonly CandidateDestinationFact[];
  actions?: readonly CandidateDestinationAction[];
  progress?: number;
  progressLabel?: string;
  details?: ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  className?: string;
}

/** Caller-mapped destination state using the canonical core status surface. */
export function CandidateDestinationStatus({
  state,
  name,
  description,
  facts,
  actions,
  progress,
  progressLabel,
  details,
  open,
  defaultOpen,
  onOpenChange,
  className,
}: CandidateDestinationStatusProps) {
  return (
    <ConnectionStatusBar
      state={state}
      name={name}
      description={description}
      facts={facts}
      actions={actions}
      progress={progress}
      progressLabel={progressLabel}
      open={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
      className={className}
    >
      {details}
    </ConnectionStatusBar>
  );
}

"use client";

import { Badge } from "@epicbagel/saas-kit/primitives/badge";
import { Button } from "@epicbagel/saas-kit/primitives/button";
import { CountBadge } from "@epicbagel/saas-kit/primitives/count-badge";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@epicbagel/saas-kit/primitives/dropdown-menu";
import { FlexItem } from "@epicbagel/saas-kit/primitives/flex-item";
import { Heading } from "@epicbagel/saas-kit/primitives/heading";
import { Icon, type IconProps } from "@epicbagel/saas-kit/primitives/icon";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { Tabs, TabsList, TabsTrigger } from "@epicbagel/saas-kit/primitives/tabs";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import { Loader2, MoreHorizontal, ShieldCheck, X } from "lucide-react";
import type { ElementType, HTMLAttributes, Key, MouseEvent, ReactNode } from "react";

function present(value: ReactNode): boolean {
  return value != null && value !== false && value !== "";
}

export interface CandidateDetailLayoutProps
  extends Omit<HTMLAttributes<HTMLElement>, "children"> {
  /** The fixed header, usually a CandidateDetailHeader. */
  header: ReactNode;
  /** A message between the header and the tabs, such as a failed refresh. */
  alert?: ReactNode;
  /** The fixed tab strip, usually CandidateDetailTabs. */
  tabs: ReactNode;
  /** The active tab's sections. This is the only part that scrolls. */
  children?: ReactNode;
  /** A fixed bar under the body, such as the action bar for the role in focus. */
  footer?: ReactNode;
}

/**
 * The frame of a person's detail pane: a fixed header, an optional alert, a
 * fixed tab strip, a body that grows and scrolls on its own, and an optional
 * fixed footer. It fills its container's height and clips it, so put it in a
 * dialog, drawer or side panel with a definite height.
 *
 * The root is marked `data-slot="candidate-detail-layout"`.
 */
export function CandidateDetailLayout({
  header,
  alert,
  tabs,
  children,
  footer,
  ...props
}: CandidateDetailLayoutProps) {
  return (
    <Stack
      data-slot="candidate-detail-layout"
      direction="vertical"
      gap="none"
      height="full"
      overflow="hidden"
      {...props}
    >
      {header}
      {alert}
      {tabs}
      <FlexItem grow overflow="y-auto">
        {children}
      </FlexItem>
      {footer}
    </Stack>
  );
}

/** A verified badge beside the person's name. */
export interface CandidateDetailVerified {
  /** The badge text, such as "verified". */
  label: ReactNode;
  /** The badge tooltip, such as what was verified and by whom. */
  title?: string;
}

export interface CandidateDetailHeaderProps
  extends Omit<HTMLAttributes<HTMLElement>, "children"> {
  /** The avatar at the start, such as the kit's PersonAvatar at 56px. */
  avatar: ReactNode;
  /** The person's name, the pane's level-3 heading. */
  name: ReactNode;
  /** Shows a success badge with a shield after the name. */
  verified?: CandidateDetailVerified;
  /** When it was verified, already formatted. Shown only with `verified`. */
  verifiedAt?: ReactNode;
  /** The line under the name, such as the current title and company. */
  headline?: ReactNode;
  /** A quieter line under that, such as where the person came from. */
  provenance?: ReactNode;
  /** Controls before the close button, such as a favourite toggle and a CandidateActionMenu. */
  actions?: ReactNode;
  /** Closes the pane. */
  onClose: () => void;
  /** The close button's accessible name. */
  closeLabel?: string;
}

/**
 * The header of a person's detail pane: avatar, name with an optional
 * verified badge, a headline and a provenance line, then the host's actions
 * and a close button. The name and both lines truncate rather than wrap.
 *
 * The root is marked `data-slot="candidate-detail-header"`.
 */
export function CandidateDetailHeader({
  avatar,
  name,
  verified,
  verifiedAt,
  headline,
  provenance,
  actions,
  onClose,
  closeLabel = "Close",
  ...props
}: CandidateDetailHeaderProps) {
  return (
    <Stack
      data-slot="candidate-detail-header"
      direction="horizontal"
      gap="md"
      align="start"
      padding="lg"
      border="bottom"
      {...props}
    >
      {avatar}
      <FlexItem grow minWidth="zero">
        <Stack direction="horizontal" gap="xs" align="center" wrap>
          <Heading level={3} truncate>{name}</Heading>
          {verified && (
            <Badge
              as="span"
              variant="success"
              size="micro-compact"
              gap="xs"
              weight="semibold"
              title={verified.title}
            >
              <Icon icon={ShieldCheck} size="xs" />
              {verified.label}
            </Badge>
          )}
          {verified && present(verifiedAt) && (
            <Text variant="inherit" as="span" size="xs" tone="subtle">
              {verifiedAt}
            </Text>
          )}
        </Stack>
        {present(headline) && (
          <Text as="div" size="sm" tone="muted" truncate marginTop="tight">
            {headline}
          </Text>
        )}
        {present(provenance) && (
          <Text size="xs" tone="subtle" truncate marginTop="xs">
            {provenance}
          </Text>
        )}
      </FlexItem>
      <Stack direction="horizontal" gap="xs" align="center" shrink={false}>
        {actions}
        <Button variant="ghost" size="icon-sm" aria-label={closeLabel} onClick={() => onClose()}>
          <Icon icon={X} size="md" />
        </Button>
      </Stack>
    </Stack>
  );
}

/** One item in a CandidateActionMenu. */
export interface CandidateActionMenuItem<TId extends Key = Key> {
  /** Identifies the item, and is what the menu's `onSelect` receives. */
  id: TId;
  label: ReactNode;
  /** The glyph, as a component reference such as a lucide icon. Leave it out for a text-only item. */
  icon?: ElementType;
  /** Called when the item is chosen, by pointer or keyboard, before the menu's `onSelect`. */
  onSelect?: () => void;
  disabled?: boolean;
  /** The icon's colour, for example `warning` while an item undoes a state. */
  tone?: IconProps["tone"];
}

export interface CandidateActionMenuProps<TId extends Key = Key> {
  /** The items, in order. The host decides which apply. */
  items: readonly CandidateActionMenuItem<TId>[];
  /** Called with the chosen item's `id`, after the item's own `onSelect`. */
  onSelect?: (id: TId) => void;
  /** Shows a spinner in place of the trigger's glyph while an action runs. */
  busy?: boolean;
  /** Disables the trigger, for example while an earlier choice saves. */
  disabled?: boolean;
  /** The trigger's tooltip and accessible name. */
  label?: string;
  /**
   * The trigger's button variant: `ghost` (default) in a header, `quiet`
   * beside a card's other quiet actions.
   */
  variant?: "ghost" | "quiet";
  /** The trigger's glyph size: `md` (default), or `sm` on a compact card row. */
  triggerIconSize?: "sm" | "md";
  /** The items' glyph size: `md` (default), or `sm` to match small buttons. */
  itemIconSize?: "sm" | "md";
  /**
   * Stops a click on the trigger or in the menu from reaching a surrounding
   * clickable card. The menu renders in a portal, but React still bubbles
   * its clicks through the card.
   */
  isolateClicks?: boolean;
}

/**
 * The "…" menu: secondary actions for a person or one of their signals, so
 * a detail header or a card's row stays uncluttered on narrow screens. The
 * host owns the items and what each one does: give an item its own
 * `onSelect`, or handle every item in the menu's `onSelect(id)`.
 * `CandidateSignalMenu` is this menu with a signal's defaults. The menu
 * surface is marked `data-slot="candidate-action-menu"`.
 */
export function CandidateActionMenu<TId extends Key = Key>({
  items,
  onSelect,
  busy = false,
  disabled,
  label = "More actions",
  variant = "ghost",
  triggerIconSize = "md",
  itemIconSize = "md",
  isolateClicks = false,
}: CandidateActionMenuProps<TId>) {
  const isolate = isolateClicks
    ? (event: MouseEvent<HTMLElement>) => event.stopPropagation()
    : undefined;
  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant={variant} size="icon-sm" disabled={disabled} title={label} onClick={isolate}>
          {busy ? (
            <Icon icon={Loader2} size={triggerIconSize} spin />
          ) : (
            <Icon icon={MoreHorizontal} size={triggerIconSize} />
          )}
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" data-slot="candidate-action-menu" onClick={isolate}>
        {items.map((item) => (
          <DropdownMenuItem
            key={item.id}
            onClick={() => {
              item.onSelect?.();
              onSelect?.(item.id);
            }}
            disabled={item.disabled}
          >
            {item.icon && <Icon icon={item.icon} size={itemIconSize} tone={item.tone} />}
            {item.label}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

/** One tab in a CandidateDetailTabs strip. */
export interface CandidateDetailTabItem<TValue extends string = string> {
  value: TValue;
  label: ReactNode;
  /** Something waiting on the tab, shown as a count badge when above zero. */
  count?: number;
}

export interface CandidateDetailTabsProps<TValue extends string = string>
  extends Omit<HTMLAttributes<HTMLDivElement>, "children" | "onChange" | "defaultValue" | "dir"> {
  /** The tabs, in order. */
  tabs: readonly CandidateDetailTabItem<TValue>[];
  /** The active tab. */
  value: TValue;
  /** Called with the tab a person picks. */
  onChange: (value: TValue) => void;
}

/**
 * The tab strip of a person's detail pane, full width and scrolling sideways
 * on a phone. A tab's count shows in the kit's count badge, which is
 * destructive-toned because it marks something to act on, and only when
 * above zero. The host renders the active tab's content.
 *
 * The root is marked `data-slot="candidate-detail-tabs"`.
 */
export function CandidateDetailTabs<TValue extends string = string>({
  tabs,
  value,
  onChange,
  ...props
}: CandidateDetailTabsProps<TValue>) {
  return (
    <Tabs
      data-slot="candidate-detail-tabs"
      value={value}
      onValueChange={(next) => onChange(next as TValue)}
      {...props}
    >
      <TabsList width="full" scrollable marginBottom="none">
        {tabs.map((item) => (
          <TabsTrigger key={item.value} value={item.value}>
            {item.label}
            {item.count != null && item.count > 0 && <CountBadge value={item.count} />}
          </TabsTrigger>
        ))}
      </TabsList>
    </Tabs>
  );
}

/**
 * Host wording for a blank slate: what is missing, and optionally what to do
 * about it. Every Recruit UI list or panel with an empty state takes one as
 * `empty`, and has a plain default for a host that passes none.
 */
export interface CandidateEmptyCopy {
  /** "No <things> yet". */
  title: string;
  description?: string;
}

import { DefinitionItem, DefinitionList } from "@epicbagel/saas-kit/primitives/definition-list";
import { Icon } from "@epicbagel/saas-kit/primitives/icon";
import { List, ListItem } from "@epicbagel/saas-kit/primitives/list";
import { PanelSection } from "@epicbagel/saas-kit/primitives/panel-section";
import { SectionHeader } from "@epicbagel/saas-kit/primitives/section-header";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import { History as HistoryIcon } from "lucide-react";
import type { HTMLAttributes, Key, ReactNode } from "react";

/** One fact about a person, such as the languages they speak. */
export interface CandidateFact {
  id: Key;
  /** What the fact is. Each word is capitalised, so a lower-case kind reads as a title. */
  label: ReactNode;
  /** The value, already formatted, for example with formatFactValue. */
  value: ReactNode;
}

export interface CandidateFactListProps
  extends Omit<HTMLAttributes<HTMLElement>, "title" | "children"> {
  /** The section heading. The count follows it. */
  title?: ReactNode;
  facts: readonly CandidateFact[];
  /** The kit PanelSection's divider. */
  border?: "none" | "top" | "bottom";
}

/**
 * Collected facts about a person, as a counted definition list. Facts are
 * usually gathered over time and many people have none, so with no facts it
 * renders nothing rather than an empty panel.
 *
 * The root is the kit PanelSection, marked `data-slot="candidate-fact-list"`.
 */
export function CandidateFactList({
  title = "Facts",
  facts,
  border = "bottom",
  ...props
}: CandidateFactListProps) {
  if (facts.length === 0) return null;

  return (
    <PanelSection data-slot="candidate-fact-list" border={border} {...props}>
      <SectionHeader icon={<Icon icon={HistoryIcon} size="xs" />} label={title} count={facts.length} />
      <DefinitionList>
        {facts.map((fact) => (
          <DefinitionItem
            key={fact.id}
            label={<Text variant="inherit" as="span" transform="capitalize">{fact.label}</Text>}
          >
            {fact.value}
          </DefinitionItem>
        ))}
      </DefinitionList>
    </PanelSection>
  );
}

/**
 * Formats a stored fact value for display. Text, numbers and booleans read as
 * written; a list of words joins with commas; a record joins its non-empty
 * values with middle dots (dropping `color` and `sentiment`, which are styling
 * hints); a list of records becomes a tight list. An empty value reads as an
 * em dash.
 */
export function formatFactValue(value: unknown): ReactNode {
  if (value === null || value === undefined) return "—";
  if (typeof value === "string" || typeof value === "number" || typeof value === "boolean") return String(value);

  if (Array.isArray(value)) {
    if (value.length === 0) return "—";
    if (typeof value[0] === "string" || typeof value[0] === "number") return value.join(", ");
    return (
      <List spacing="tight">
        {value.map((item, index) => <ListItem key={index} textSize="sm">{formatSingleObject(item)}</ListItem>)}
      </List>
    );
  }

  if (typeof value === "object") return formatSingleObject(value as Record<string, unknown>);
  return String(value);
}

function formatSingleObject(value: unknown): ReactNode {
  if (!value || typeof value !== "object") return String(value ?? "—");
  const entries = Object.entries(value as Record<string, unknown>).filter(
    ([key, item]) => item !== null && item !== undefined && item !== "" && key !== "color" && key !== "sentiment",
  );
  const [first] = entries;
  if (!first) return "—";
  if (entries.length === 1) return formatLeaf(first[1]);

  return entries.map(([key, item], index) => (
    <Text variant="inherit" as="span" key={key}>
      {index > 0 && <Text variant="inherit" as="span" tone="muted"> · </Text>}
      {formatLeaf(item)}
    </Text>
  ));
}

function formatLeaf(value: unknown): string {
  if (value === null || value === undefined) return "";
  if (typeof value === "string") return value.replace(/^null$/i, "").trim();
  if (typeof value === "number" || typeof value === "boolean") return String(value);
  if (Array.isArray(value)) return value.filter(Boolean).map(String).join(", ");
  if (typeof value === "object") {
    return Object.values(value as Record<string, unknown>)
      .filter((item) => item != null && item !== "")
      .map(formatLeaf)
      .filter(Boolean)
      .join(" · ");
  }
  return String(value);
}

"use client";

import { Button } from "@epicbagel/saas-kit/primitives/button";
import { Icon } from "@epicbagel/saas-kit/primitives/icon";
import { Star } from "lucide-react";
import type { ButtonHTMLAttributes, MouseEvent } from "react";

/** Host-owned wording for the two states of the toggle. */
export interface CandidateFavouriteButtonLabels {
  /** Shown while the candidate is not a favourite. */
  add: string;
  /** Shown while the candidate is a favourite. */
  remove: string;
}

const DEFAULT_LABELS: CandidateFavouriteButtonLabels = {
  add: "Add to favourites",
  remove: "Remove from favourites",
};

export interface CandidateFavouriteButtonProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children" | "type" | "onToggle"> {
  favourited: boolean;
  /** Called with no arguments; the host flips and persists the marker. */
  onToggle: () => void;
  labels?: Partial<CandidateFavouriteButtonLabels>;
  /**
   * The star's colour while the candidate is not a favourite: `muted`
   * (default) on a card, or `inherit` to take the surrounding text colour,
   * as the other icon actions in a detail header do.
   */
  idleTone?: "muted" | "inherit";
}

/**
 * A borderless star toggle for marking a candidate as a favourite.
 *
 * The click never reaches a surrounding card, so it works inside a clickable
 * candidate card. The root is the kit Button and keeps the kit's own
 * `data-slot="button"`, which theme stylesheets select on.
 */
export function CandidateFavouriteButton({
  favourited,
  onToggle,
  labels,
  idleTone = "muted",
  onClick,
  ...props
}: CandidateFavouriteButtonProps) {
  const label = favourited
    ? labels?.remove ?? DEFAULT_LABELS.remove
    : labels?.add ?? DEFAULT_LABELS.add;

  return (
    <Button
      type="button"
      variant="ghost"
      size="icon-sm"
      shrink
      aria-pressed={favourited}
      title={label}
      {...props}
      onClick={(event: MouseEvent<HTMLButtonElement>) => {
        event.stopPropagation();
        onClick?.(event);
        if (!event.defaultPrevented) onToggle();
      }}
    >
      <Icon icon={Star} size="md" tone={favourited ? "warning" : idleTone} filled={favourited} />
    </Button>
  );
}

"use client";

import { Icon } from "@epicbagel/saas-kit/primitives/icon";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { Toggle } from "@epicbagel/saas-kit/primitives/toggle";
import type { ElementType, HTMLAttributes, ReactNode } from "react";

import { COARSE_POINTER_TOUCH_TARGET } from "./touch-targets";

/**
 * The kit Toggle's pressed state is a light accent fill with the same label
 * colour as an unpressed chip, about 1.2:1 against it. These are the kit
 * ChipTabs' outline states instead: an unpressed chip has a muted label, and
 * the pressed one a primary border and tint with a full-strength label.
 */
const CHIP_STATES =
  "text-muted-foreground hover:text-foreground data-[state=on]:border-primary data-[state=on]:bg-primary/10 data-[state=on]:font-medium data-[state=on]:text-foreground";

const CHIP_CLASSES = `${CHIP_STATES} ${COARSE_POINTER_TOUCH_TARGET}`;

/** One chip: a value the list can be narrowed to. */
export interface CandidateFilterChipOption<TValue extends string = string> {
  value: TValue;
  label: ReactNode;
  /** An icon component (not an element) drawn before the label. */
  icon?: ElementType;
}

export interface CandidateFilterChipsProps<TValue extends string = string>
  extends Omit<HTMLAttributes<HTMLElement>, "onChange" | "children"> {
  /** The chosen option, or null for the unfiltered chip. */
  value: TValue | null;
  /** Called with an option's value, or null from the unfiltered chip. */
  onChange: (value: TValue | null) => void;
  /** The first chip, which clears the filter, such as "Everyone". */
  allLabel: ReactNode;
  options: readonly CandidateFilterChipOption<TValue>[];
  /** Content before the chips, such as a badge naming where the list came from. */
  context?: ReactNode;
  /** Content pushed to the end of the row, such as a related control. */
  action?: ReactNode;
}

/**
 * A single row of pressed-state chips that narrows a list of people to one
 * kind, such as everyone with a recent job move. The row scrolls sideways
 * rather than wrapping, and sits on a bottom border so it reads as part of
 * the toolbar above the list. Each chip is a toggle button with
 * `aria-pressed`; the pressed one has a primary border and tint and a
 * full-strength label, the others a muted label. Every chip keeps a 44px
 * touch target on a coarse pointer (a touchscreen); a mouse keeps the 28px
 * chip. The host owns the options, their
 * wording and what each one filters. The root is marked
 * `data-slot="candidate-filter-chips"`.
 */
export function CandidateFilterChips<TValue extends string = string>({
  value,
  onChange,
  allLabel,
  options,
  context,
  action,
  ...props
}: CandidateFilterChipsProps<TValue>) {
  return (
    <Stack gap="none" border="bottom" data-slot="candidate-filter-chips" {...props}>
      <Stack direction="horizontal" gap="xs" align="center" paddingY="sm" overflow="x-auto">
        {context}
        <Toggle
          pressed={!value}
          onPressedChange={() => onChange(null)}
          variant="outline"
          size="chip"
          className={CHIP_CLASSES}
        >
          {allLabel}
        </Toggle>
        {options.map((option) => (
          <Toggle
            key={option.value}
            pressed={value === option.value}
            onPressedChange={() => onChange(option.value)}
            variant="outline"
            size="chip"
            className={CHIP_CLASSES}
          >
            {option.icon && <Icon icon={option.icon} size="xs" />}
            {option.label}
          </Toggle>
        ))}
        {action && <Stack marginStart="auto" shrink={false}>{action}</Stack>}
      </Stack>
    </Stack>
  );
}

import { Badge, type BadgeProps } from "@epicbagel/saas-kit/primitives/badge";
import { SentimentBadge, type Sentiment } from "@epicbagel/saas-kit/primitives/sentiment-dot";
import type { HTMLAttributes, ReactNode } from "react";

export type CandidateGrade = "A" | "B" | "C" | "D";

/** Host-owned wording for each display grade. */
export type CandidateGradeLabels = Partial<Record<CandidateGrade, string>>;

/** Visual treatment selected by the host; Recruit UI does not infer grade policy. */
export type CandidateGradeTone =
  | "default"
  | "secondary"
  | "destructive"
  | "outline"
  | "success"
  | "warning"
  | "error"
  | "info"
  | "neutral";

export function normalizeCandidateGrade(
  grade: string | null | undefined,
): CandidateGrade | null {
  const normalized = grade?.trim().toUpperCase();
  return normalized === "A" ||
    normalized === "B" ||
    normalized === "C" ||
    normalized === "D"
    ? normalized
    : null;
}

/** Return presentation only; grade assignment and vocabulary stay host-owned. */
export function candidateGradeLetter(grade: string | null | undefined): string {
  return normalizeCandidateGrade(grade) ?? "—";
}

export function candidateGradeLabel(
  grade: string | null | undefined,
  labels: CandidateGradeLabels,
): string | null {
  const normalized = normalizeCandidateGrade(grade);
  return normalized ? labels[normalized] ?? null : null;
}

export function candidateGradeDisplay(
  grade: string | null | undefined,
  labels: CandidateGradeLabels,
): string {
  const normalized = normalizeCandidateGrade(grade);
  if (!normalized) return "—";
  const label = labels[normalized];
  return label ? `${normalized} — ${label}` : normalized;
}

export interface CandidateGradeBadgeProps
  extends HTMLAttributes<HTMLDivElement> {
  grade: string | null | undefined;
  /**
   * One-off host wording. Takes precedence over `labels`. With no grade, the
   * inline format shows it alone, such as "Needs review", in place of the
   * dash.
   */
  label?: ReactNode;
  /** Host-owned wording map for shared badge instances. */
  labels?: CandidateGradeLabels;
  /** Host-owned semantic treatment; no meaning is inferred from the letter. */
  tone?: CandidateGradeTone;
  showLabel?: boolean;
  /** The kit badge size, such as `compact` for dense rows. */
  size?: BadgeProps["size"];
  /** Root element: a block-level `div` (default) or an inline `span`. */
  as?: "div" | "span";
  /** Keep the badge at its natural width in a flex row. */
  shrink?: boolean;
  /**
   * `split` (default): the letter and the label as separate spans, the letter
   * with an accessible name. `inline`: a single line of text, "A — Strong fit",
   * for a host that names the grade in a tooltip or the surrounding text; with
   * no grade, the label alone, or "—" without one.
   */
  format?: "split" | "inline";
  /**
   * `badge` (default): the kit Badge in `tone`. `sentiment`: the kit's
   * sentiment pill, a coloured dot and text, in `sentiment`. The pill takes
   * only `className`; other attributes are not passed to it.
   */
  appearance?: "badge" | "sentiment";
  /** Host-owned sentiment for `appearance="sentiment"`. */
  sentiment?: CandidateGradeSentiment;
}

/** The kit's sentiment scale, for `appearance="sentiment"`. */
export type CandidateGradeSentiment = Sentiment;

function inlineGradeText(
  grade: CandidateGrade | null,
  label: ReactNode,
): ReactNode {
  const hasLabel = !(label == null || label === false || label === "");
  // An ungraded record with host wording reads as that wording alone.
  if (!grade) return hasLabel ? label : "—";
  if (!hasLabel) return grade;
  // One text node when the label is plain text, as candidateGradeDisplay
  // would format it.
  return typeof label === "string" || typeof label === "number"
    ? `${grade} — ${label}`
    : <>{grade} — {label}</>;
}

/**
 * The grade letter with an optional host label. The root is the kit Badge
 * (or its sentiment pill) and keeps the kit's own `data-slot`, which theme
 * stylesheets select on; `data-grade` names the grade, or `ungraded`.
 */
export function CandidateGradeBadge({
  grade,
  label,
  labels = {},
  tone = "neutral",
  showLabel = true,
  size,
  as,
  shrink,
  format = "split",
  appearance = "badge",
  sentiment = "neutral",
  className,
  ...props
}: CandidateGradeBadgeProps) {
  const normalized = normalizeCandidateGrade(grade);
  const resolvedLabel = label === undefined
    ? candidateGradeLabel(normalized, labels)
    : label;
  const visibleLabel = showLabel ? resolvedLabel : null;

  const content = format === "inline"
    ? inlineGradeText(normalized, visibleLabel)
    : (
      <>
        <span aria-label={normalized ? `Grade ${normalized}` : "Not graded"}>
          {normalized ?? "—"}
        </span>
        {visibleLabel ? <span>{visibleLabel}</span> : null}
      </>
    );

  if (appearance === "sentiment") {
    return (
      <SentimentBadge sentiment={sentiment} className={className}>
        {content}
      </SentimentBadge>
    );
  }

  return (
    <Badge
      data-grade={normalized ?? "ungraded"}
      variant={tone}
      size={size}
      as={as}
      shrink={shrink}
      className={className}
      {...props}
    >
      {content}
    </Badge>
  );
}

