/** One line of a summary, with its sentiment dot. */
export interface CandidateSummaryBullet {
  text: ReactNode;
  sentiment: Sentiment;
  /**
   * The word a screen reader says for this line's dot, in place of the one
   * `labels.sentiment` gives its sentiment, such as the host's "Risk".
   */
  sentimentLabel?: string;
}

/** The word a screen reader says for each sentiment's dot. */
export type CandidateSentimentLabels = Record<Sentiment, string>;

export interface CandidateSummaryBulletsLabels {
  generate: string;
  /** In place of generate once a summary exists. */
  refresh: string;
  generating: string;
  /**
   * Read before each line, because the dot is decorative: without a word, a
   * screen reader announces a positive and a negative line alike, and only
   * the dot's colour tells them apart.
   */
  sentiment: CandidateSentimentLabels;
}

const BULLET_LABELS: CandidateSummaryBulletsLabels = {
  generate: "Generate summary",
  refresh: "Refresh summary",
  generating: "Generating…",
  sentiment: {
    positive: "Positive",
    neutral: "Neutral",
    warning: "Caution",
    negative: "Negative",
  },
};

/** CandidateSummaryBullets' labels as a host gives them: any of them, and any sentiment's word. */
export type CandidateSummaryBulletsLabelOverrides = Partial<Omit<CandidateSummaryBulletsLabels, "sentiment">> & {
  sentiment?: Partial<CandidateSentimentLabels>;
};

export interface CandidateSummaryBulletsProps
  extends Omit<HTMLAttributes<HTMLElement>, "children"> {
  /** The lines to show; the host may fall back to other evidence when there is no summary. */
  bullets: readonly CandidateSummaryBullet[];
  /** Compact pipeline text by default; body uses the small body scale and inherits its surrounding text tone. */
  presentation?: "compact" | "body";
  /** Adds a link-style button that asks the host for a summary. */
  onGenerate?: () => void;
  /** Shows a spinner on the button and disables it. */
  generating?: boolean;
  /** Says refresh instead of generate, once a summary exists. */
  generated?: boolean;
  /** Why the last request failed. */
  error?: ReactNode;
  labels?: CandidateSummaryBulletsLabelOverrides;
}

/**
 * A short summary of a person for one role, as a dense list of lines with
 * sentiment dots, and a link-style button to generate or refresh it.
 *
 * The dot is decorative, so each line also carries its sentiment as a word
 * for screen readers ("Positive", "Caution", …, from `labels.sentiment` or
 * the bullet's own `sentimentLabel`), visually hidden before the text.
 *
 * The root is marked `data-slot="candidate-summary-bullets"`.
 */
export function CandidateSummaryBullets({
  bullets,
  presentation = "compact",
  onGenerate,
  generating = false,
  generated = false,
  error,
  labels,
  ...props
}: CandidateSummaryBulletsProps) {
  const wording = {
    ...BULLET_LABELS,
    ...labels,
    sentiment: { ...BULLET_LABELS.sentiment, ...labels?.sentiment },
  };

  return (
    <Stack data-slot="candidate-summary-bullets" gap="none" {...props}>
      {bullets.length > 0 ? (
        <List spacing="normal" inset="xs">
          {bullets.map((bullet, index) => (
            <ListItem
              key={index}
              layout="row"
              textSize={presentation === "body" ? "sm" : "xs"}
              tone={presentation === "body" ? "inherit" : "soft"}
            >
              <SentimentDot sentiment={bullet.sentiment} />
              {/* Out of the row's flow, so the dot and text keep their layout. */}
              <span className="sr-only" data-slot="candidate-summary-bullet-sentiment">
                {`${bullet.sentimentLabel ?? wording.sentiment[bullet.sentiment]}: `}
              </span>
              <Text variant="inherit" as="span" grow>{bullet.text}</Text>
            </ListItem>
          ))}
        </List>
      ) : null}

      {onGenerate && (
        <Button
          type="button"
          variant="link-muted"
          size="bare"
          marginTop="xs"
          gap="xs"
          onClick={() => onGenerate()}
          disabled={generating}
        >
          {generating ? (
            <Icon icon={Loader2} size="xs" spin />
          ) : (
            <Icon icon={Sparkles} size="xs" />
          )}
          {generating ? wording.generating : generated ? wording.refresh : wording.generate}
        </Button>
      )}
      {present(error) && <Text variant="micro" tone="destructive" marginTop="tight">{error}</Text>}
    </Stack>
  );
}

"use client";

import { Button } from "@epicbagel/saas-kit/primitives/button";
import { Icon } from "@epicbagel/saas-kit/primitives/icon";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import { CircleStop, Mic, RotateCcw, Trash2 } from "lucide-react";
import { useEffect, useRef, useState, type HTMLAttributes, type ReactNode } from "react";

/**
 * Where a recording stands. The recorder moves itself through `idle`,
 * `requesting` (asking for the microphone), `recording`, `uploading` (while
 * `onAccept` runs), `ready`, `preview` (a take whose upload failed, kept to
 * retry) and `error`. `transcribing` is yours to show through
 * `externalState`, as `uploading` can be.
 */
export type CandidatePresentationRecorderState =
  | "idle"
  | "requesting"
  | "recording"
  | "preview"
  | "uploading"
  | "transcribing"
  | "ready"
  | "error";

const MIME_CANDIDATES = [
  "audio/mp4;codecs=mp4a.40.2",
  "audio/mp4",
  "audio/webm;codecs=opus",
  "audio/webm",
  "audio/ogg;codecs=opus",
];

/**
 * The first audio format this browser's MediaRecorder can write, preferring
 * MP4 (which every browser plays back) over WebM and Ogg, or "" when it has
 * no MediaRecorder or supports none of them.
 */
export function supportedRecordingMimeType(): string {
  if (typeof MediaRecorder === "undefined") return "";
  return MIME_CANDIDATES.find((mime) => MediaRecorder.isTypeSupported(mime)) ?? "";
}

function clock(totalSeconds: number): string {
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  return `${minutes}:${String(seconds).padStart(2, "0")}`;
}

export interface CandidatePresentationRecorderLabels {
  /** The muted line above the controls: what the note is for and what happens to it. */
  description: ReactNode;
  /** Starts a first recording. */
  record: ReactNode;
  /** Starts a recording that replaces `existingAudio`. */
  replace: ReactNode;
  /** While the browser asks for the microphone. */
  requesting: ReactNode;
  /** Stops the recording, which hands the take to `onAccept`. */
  stop: ReactNode;
  /** Hands a take whose upload failed to `onAccept` again. */
  retry: ReactNode;
  /** Throws away a take whose upload failed. */
  discard: ReactNode;
  /** While `onAccept` runs. */
  uploading: ReactNode;
  /** While `externalState` is `transcribing`. */
  transcribing: ReactNode;
  /** Under the controls once a new take is accepted. */
  added: ReactNode;
  /** The new take's player's accessible name. */
  takePlayer: string;
  /** The `existingAudio` player's accessible name. */
  existingPlayer: string;
  /** The browser can't record audio. */
  unsupported: ReactNode;
  /** The person or the browser blocked the microphone. */
  blocked: ReactNode;
  /** No microphone was found. */
  noMicrophone: ReactNode;
  /** The recording stopped with an error. */
  interrupted: ReactNode;
  /** The take came back empty. */
  empty: ReactNode;
  /** `onAccept` failed without a message of its own. */
  acceptFailed: ReactNode;
}

const LABELS: CandidatePresentationRecorderLabels = {
  description: "Optional. It’s added automatically when you stop recording.",
  record: "Record voice note",
  replace: "Record a replacement",
  requesting: "Requesting microphone…",
  stop: "Stop recording",
  retry: "Retry voice note",
  discard: "Discard recording",
  uploading: "Uploading…",
  transcribing: "Transcribing…",
  added: "Voice note added. It will be included when you share.",
  takePlayer: "Preview voice recommendation",
  existingPlayer: "Current voice recommendation",
  unsupported: "Voice recording is not supported in this browser.",
  blocked: "Microphone access is blocked. Allow it in your browser, then try again.",
  noMicrophone: "No microphone is available.",
  interrupted: "The recording was interrupted. Try another take.",
  empty: "Nothing was recorded. Try another take.",
  acceptFailed: "The recording could not be uploaded. Your take is still here; retry when ready.",
};

/** What `renderAudio` receives: a playable URL and the player's accessible name. */
export interface CandidatePresentationRecorderAudio {
  src: string;
  label: string;
}

function NativeAudio({ src, label }: CandidatePresentationRecorderAudio) {
  return <audio src={src} aria-label={label} controls preload="metadata" />;
}

export interface CandidatePresentationRecorderProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "children"> {
  /**
   * Called with each finished take, as soon as recording stops. Upload or
   * save it here. While it runs the recorder shows `uploading`; if it throws,
   * the take stays playable with Retry and Discard, and the error's message
   * (or `labels.acceptFailed`) shows under the controls.
   */
  onAccept: (blob: Blob, mimeType: string) => Promise<void>;
  /**
   * Shows `uploading` or `transcribing` from outside, such as while you
   * transcribe an accepted take. Any other value leaves the recorder's own
   * state showing.
   */
  externalState?: CandidatePresentationRecorderState;
  /** A recording already saved, playable until a new take is accepted. */
  existingAudio?: string | null;
  /**
   * Told whether a take is in progress or unsaved (requesting, recording,
   * uploading, transcribing, or a take kept to retry), so you can hold off
   * closing or sharing until it settles.
   */
  onPendingChange?: (pending: boolean) => void;
  /** Disables starting, retrying and discarding. Stopping a recording stays possible. */
  disabled?: boolean;
  /** Renders a player. Defaults to the browser's own audio controls. */
  renderAudio?: (audio: CandidatePresentationRecorderAudio) => ReactNode;
  labels?: Partial<CandidatePresentationRecorderLabels>;
}

/**
 * Records a short voice note to send with a person's profile, such as your
 * recommendation to a client: Record, a running clock, Stop, then a player
 * for the take. Each take goes straight to your `onAccept`; a failed one
 * stays playable to retry or discard, so nobody has to record it again. It
 * uses the browser's MediaRecorder and picks the format with
 * `supportedRecordingMimeType`. Uploading, transcribing and saving are yours.
 *
 * The root is marked `data-slot="candidate-presentation-recorder"`.
 */
export function CandidatePresentationRecorder({
  onAccept,
  externalState = "idle",
  existingAudio,
  onPendingChange,
  disabled = false,
  renderAudio = NativeAudio,
  labels,
  ...props
}: CandidatePresentationRecorderProps) {
  const copy = { ...LABELS, ...labels };
  const [state, setState] = useState<CandidatePresentationRecorderState>(existingAudio ? "ready" : "idle");
  const [error, setError] = useState<ReactNode>(null);
  const [elapsed, setElapsed] = useState(0);
  const [take, setTake] = useState<{ blob: Blob; mimeType: string; url: string } | null>(null);
  const recorderRef = useRef<MediaRecorder | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const chunksRef = useRef<Blob[]>([]);

  const shownState = externalState === "uploading" || externalState === "transcribing" ? externalState : state;

  const pending = ["requesting", "recording", "uploading", "transcribing"].includes(shownState)
    || (state === "preview" && !!take);
  useEffect(() => {
    onPendingChange?.(pending);
  }, [pending, onPendingChange]);

  useEffect(() => {
    if (state !== "recording") return;
    const timer = window.setInterval(() => setElapsed((value) => value + 1), 1_000);
    return () => window.clearInterval(timer);
  }, [state]);

  useEffect(() => () => {
    if (recorderRef.current?.state === "recording") recorderRef.current.stop();
    streamRef.current?.getTracks().forEach((track) => track.stop());
    if (take) URL.revokeObjectURL(take.url);
  }, [take]);

  async function start() {
    setError(null);
    if (!navigator.mediaDevices?.getUserMedia || typeof MediaRecorder === "undefined") {
      setError(copy.unsupported);
      setState("error");
      return;
    }
    setState("requesting");
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mimeType = supportedRecordingMimeType();
      const recorder = mimeType ? new MediaRecorder(stream, { mimeType }) : new MediaRecorder(stream);
      streamRef.current = stream;
      recorderRef.current = recorder;
      chunksRef.current = [];
      setElapsed(0);
      recorder.ondataavailable = (event) => {
        if (event.data.size > 0) chunksRef.current.push(event.data);
      };
      recorder.onerror = () => {
        setError(copy.interrupted);
        setState("error");
      };
      recorder.start();
      setState("recording");
    } catch (reason) {
      const name = (reason as { name?: unknown } | null)?.name;
      setError(name === "NotAllowedError" || name === "SecurityError" ? copy.blocked : copy.noMicrophone);
      setState("error");
    }
  }

  function stop() {
    const recorder = recorderRef.current;
    if (!recorder || recorder.state === "inactive") return;
    recorder.onstop = () => {
      streamRef.current?.getTracks().forEach((track) => track.stop());
      streamRef.current = null;
      recorderRef.current = null;
      const mimeType = recorder.mimeType || supportedRecordingMimeType() || "audio/webm";
      const blob = new Blob(chunksRef.current, { type: mimeType });
      chunksRef.current = [];
      if (!blob.size) {
        setError(copy.empty);
        setState("error");
        return;
      }
      if (take) URL.revokeObjectURL(take.url);
      const recorded = { blob, mimeType, url: URL.createObjectURL(blob) };
      setTake(recorded);
      void accept(recorded);
    };
    recorder.stop();
  }

  function discard() {
    if (take) URL.revokeObjectURL(take.url);
    setTake(null);
    setState(existingAudio ? "ready" : "idle");
    setError(null);
    setElapsed(0);
  }

  async function accept(recorded = take) {
    if (!recorded) return;
    setError(null);
    setState("uploading");
    try {
      await onAccept(recorded.blob, recorded.mimeType);
      setState("ready");
    } catch (reason) {
      // Keep the playable take so a transient upload failure never forces
      // anyone to record the note again.
      const message = (reason as { message?: unknown } | null)?.message;
      setError(typeof message === "string" && message ? message : copy.acceptFailed);
      setState("preview");
    }
  }

  return (
    <Stack data-slot="candidate-presentation-recorder" gap="md" {...props}>
      <Stack direction="horizontal" align="start" justify="between" gap="md">
        <Stack gap="xs">
          <Text size="sm" tone="muted">
            {copy.description}
          </Text>
        </Stack>
        {(shownState === "recording" || shownState === "preview") && (
          <Text size="sm" font="mono">{clock(elapsed)}</Text>
        )}
      </Stack>

      {take && renderAudio({ src: take.url, label: copy.takePlayer })}
      {!take && existingAudio && renderAudio({ src: existingAudio, label: copy.existingPlayer })}

      <Stack direction="horizontal" gap="sm" wrap>
        {(shownState === "idle" || shownState === "ready" || shownState === "error") && (
          <Button type="button" variant="outline" disabled={disabled} onClick={() => void start()}>
            <Icon icon={Mic} size="sm" /> {existingAudio ? copy.replace : copy.record}
          </Button>
        )}
        {shownState === "requesting" && <Button type="button" variant="outline" disabled>{copy.requesting}</Button>}
        {shownState === "recording" && (
          <Button type="button" variant="outline" onClick={stop}><Icon icon={CircleStop} size="sm" /> {copy.stop}</Button>
        )}
        {shownState === "preview" && (
          <>
            <Button type="button" variant="outline" disabled={disabled} onClick={() => void accept()}>
              <Icon icon={RotateCcw} size="sm" /> {copy.retry}
            </Button>
            <Button type="button" variant="quiet" disabled={disabled} onClick={discard}>
              <Icon icon={Trash2} size="sm" /> {copy.discard}
            </Button>
          </>
        )}
        {(shownState === "uploading" || shownState === "transcribing") && (
          <Button type="button" variant="outline" disabled>
            {shownState === "uploading" ? copy.uploading : copy.transcribing}
          </Button>
        )}
      </Stack>
      {shownState === "ready" && take && <Text size="sm" tone="muted">{copy.added}</Text>}
      {error && <Text role="alert" size="sm" tone="destructive">{error}</Text>}
    </Stack>
  );
}

"use client";

import { useIsMobile } from "@epicbagel/saas-kit/hooks/use-mobile";
import { cn } from "@epicbagel/saas-kit/lib/utils";
import { Button, type ButtonProps } from "@epicbagel/saas-kit/primitives/button";
import { FlexItem } from "@epicbagel/saas-kit/primitives/flex-item";
import { Icon } from "@epicbagel/saas-kit/primitives/icon";
import {
  ResponsiveDialog,
  ResponsiveDialogBody,
  ResponsiveDialogClose,
  ResponsiveDialogContent,
  ResponsiveDialogDescription,
  ResponsiveDialogFooter,
  ResponsiveDialogHeader,
  ResponsiveDialogTitle,
  ResponsiveDialogTrigger,
} from "@epicbagel/saas-kit/primitives/responsive-dialog";
import {
  Sheet,
  SheetClose,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@epicbagel/saas-kit/primitives/sheet";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { X } from "lucide-react";
import { forwardRef, type ReactElement, type ReactNode } from "react";

/**
 * How the profile opens. `dialog` is a centred dialog, and a bottom drawer
 * below the kit dialog's 1024px breakpoint. `sheet` slides in from the right,
 * beside the list it was opened from, and up from the bottom below the kit's
 * 768px mobile breakpoint, so between the two a dialog is already a drawer
 * while a sheet is still at the side.
 *
 * The footer differs on a phone too: a dialog's (`footerLayout="auto"`)
 * becomes a two-column grid, while a sheet's stays one right-aligned row.
 */
export type CandidateProfileDialogPresentation = "dialog" | "sheet";

/**
 * The centred dialog's height on desktop. `viewport` fixes it at 85% of the
 * viewport, so a profile doesn't change height as its sections load or as a
 * person moves between profiles. `content` sizes it to what it holds, up to
 * the same cap, for a short profile such as an example. A drawer and a sheet
 * already fit their content, so this applies to the desktop dialog only.
 */
export type CandidateProfileDialogHeight = "viewport" | "content";

export interface CandidateProfileDialogProps {
  accessibleTitle: ReactNode;
  accessibleDescription?: ReactNode;
  trigger?: ReactElement;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  /** `dialog` (the default) or `sheet`. */
  presentation?: CandidateProfileDialogPresentation;
  /** `viewport` (the default) or `content`; the desktop dialog's only. */
  height?: CandidateProfileDialogHeight;
  /**
   * The visible head, such as a CandidateProfileHeader. It keeps its natural
   * height and only the body scrolls, also in a drawer or bottom sheet, whose
   * height is capped rather than fixed. A CandidateProfileHeader with
   * `padding="dialog"` starts at the body's left edge.
   */
  header?: ReactNode;
  children: ReactNode;
  footer?: ReactNode;
  footerLayout?: "auto" | "fill";
  /**
   * Disable only when a composed header or footer supplies its own close: the
   * kit's ResponsiveDialogClose in a dialog, its SheetClose in a sheet.
   */
  showClose?: boolean;
  closeLabel?: string;
  /**
   * Class for the dialog or sheet surface. A sheet is as wide as the centred
   * dialog by default; widen it here, for example for a two-column profile.
   */
  contentClassName?: string;
  bodyClassName?: string;
}

const DEFAULT_CLOSE_LABEL = "Close candidate profile";

/**
 * The header slot. It never shrinks: a drawer or bottom sheet only caps its
 * height, so a tall body makes the column shrink its items, and a header that
 * clips its content (a cover header does) has no minimum height and would lose
 * its last lines. The body scrolls, so it takes the shrinking instead.
 */
function ProfileHeaderSlot({ children }: { children: ReactNode }) {
  if (children == null || typeof children === "boolean") return null;
  return (
    <FlexItem data-slot="candidate-profile-dialog-header" shrink={false}>
      {children}
    </FlexItem>
  );
}

/** The close control both presentations pin to the top-right corner. */
const CloseButton = forwardRef<HTMLButtonElement, ButtonProps>(function CloseButton(props, ref) {
  return (
    <Button
      ref={ref}
      type="button"
      variant="quiet"
      size="icon"
      data-slot="candidate-profile-dialog-close"
      className="absolute right-2 top-2 z-10"
      {...props}
    >
      <Icon icon={X} size="lg" />
    </Button>
  );
});

/**
 * Responsive profile shell with explicit accessibility and composition slots,
 * presented as a centred dialog or as a side sheet.
 *
 * The surface is marked `data-slot="candidate-profile-dialog"`, with
 * `data-presentation` naming the presentation and, for a dialog,
 * `data-height` its height; for a sheet, `data-side` names the edge it opens
 * from. A `header` sits in an element marked
 * `data-slot="candidate-profile-dialog-header"`.
 */
export function CandidateProfileDialog({
  presentation = "dialog",
  height = "viewport",
  ...props
}: CandidateProfileDialogProps) {
  return presentation === "sheet" ? (
    <CandidateProfileSheet {...props} />
  ) : (
    <CandidateProfileCentredDialog height={height} {...props} />
  );
}

type PresentationProps = Omit<CandidateProfileDialogProps, "presentation" | "height">;

/**
 * The kit's preview dialog is `sm:h-[85vh]`; `content` lets it shrink to fit,
 * keeping the kit's max-h-[85vh] cap (the class merge drops the fixed height).
 */
const CONTENT_HEIGHT = "sm:h-auto";

function CandidateProfileCentredDialog({
  accessibleTitle,
  accessibleDescription,
  trigger,
  open,
  defaultOpen,
  onOpenChange,
  height,
  header,
  children,
  footer,
  footerLayout = "auto",
  showClose = true,
  closeLabel = DEFAULT_CLOSE_LABEL,
  contentClassName,
  bodyClassName,
}: PresentationProps & { height: CandidateProfileDialogHeight }) {
  return (
    <ResponsiveDialog
      open={open}
      defaultOpen={defaultOpen}
      onOpenChange={onOpenChange}
    >
      {trigger ? (
        <ResponsiveDialogTrigger asChild>{trigger}</ResponsiveDialogTrigger>
      ) : null}
      <ResponsiveDialogContent
        data-slot="candidate-profile-dialog"
        data-presentation="dialog"
        data-height={height}
        presentation="preview"
        className={cn(height === "content" && CONTENT_HEIGHT, contentClassName)}
      >
        {showClose ? (
          <ResponsiveDialogClose asChild>
            <CloseButton aria-label={closeLabel} />
          </ResponsiveDialogClose>
        ) : null}
        <ResponsiveDialogHeader visibility="screen-reader">
          <ResponsiveDialogTitle>{accessibleTitle}</ResponsiveDialogTitle>
          {accessibleDescription != null ? (
            <ResponsiveDialogDescription>
              {accessibleDescription}
            </ResponsiveDialogDescription>
          ) : null}
        </ResponsiveDialogHeader>
        <ProfileHeaderSlot>{header}</ProfileHeaderSlot>
        <ResponsiveDialogBody className={bodyClassName}>
          {children}
        </ResponsiveDialogBody>
        {footer != null ? (
          <ResponsiveDialogFooter layout={footerLayout}>
            {footer}
          </ResponsiveDialogFooter>
        ) : null}
      </ResponsiveDialogContent>
    </ResponsiveDialog>
  );
}

/**
 * The kit's Sheet, from the right on desktop and from the bottom below the
 * kit's mobile breakpoint. The body is the dialog's own, so a profile reads
 * the same in either presentation; the footer is the same bordered action
 * row.
 */
function CandidateProfileSheet({
  accessibleTitle,
  accessibleDescription,
  trigger,
  open,
  defaultOpen,
  onOpenChange,
  header,
  children,
  footer,
  footerLayout = "auto",
  showClose = true,
  closeLabel = DEFAULT_CLOSE_LABEL,
  contentClassName,
  bodyClassName,
}: PresentationProps) {
  const isMobile = useIsMobile();
  const side = isMobile ? "bottom" : "right";
  const surfaceClassName = [
    "gap-0",
    // As tall as the dialog's drawer on a phone; as wide as the dialog on desktop.
    isMobile ? "max-h-[92dvh] rounded-t-xl" : "w-full sm:max-w-2xl",
    contentClassName,
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <Sheet open={open} defaultOpen={defaultOpen} onOpenChange={onOpenChange}>
      {trigger ? <SheetTrigger asChild>{trigger}</SheetTrigger> : null}
      <SheetContent
        data-slot="candidate-profile-dialog"
        data-presentation="sheet"
        data-side={side}
        side={side}
        padding="none"
        hideClose
        // With no description, tell Radix so rather than point at nothing.
        {...(accessibleDescription == null ? { "aria-describedby": undefined } : {})}
        className={surfaceClassName}
      >
        {showClose ? (
          <SheetClose asChild>
            <CloseButton aria-label={closeLabel} />
          </SheetClose>
        ) : null}
        <SheetHeader className="sr-only">
          <SheetTitle>{accessibleTitle}</SheetTitle>
          {accessibleDescription != null ? (
            <SheetDescription>{accessibleDescription}</SheetDescription>
          ) : null}
        </SheetHeader>
        <ProfileHeaderSlot>{header}</ProfileHeaderSlot>
        <ResponsiveDialogBody className={bodyClassName}>
          {children}
        </ResponsiveDialogBody>
        {footer != null ? (
          <Stack
            data-slot="candidate-profile-dialog-footer"
            direction="horizontal"
            gap="sm"
            align="center"
            justify="end"
            shrink={false}
            border="top"
            surface="background"
            padding="action-row"
            className={footerLayout === "fill" ? "[&>*]:min-w-0 [&>*]:flex-1" : undefined}
          >
            {footer}
          </Stack>
        ) : null}
      </SheetContent>
    </Sheet>
  );
}

"use client";

import { Anchor } from "@epicbagel/saas-kit/primitives/anchor";
import { Button } from "@epicbagel/saas-kit/primitives/button";
import { Icon } from "@epicbagel/saas-kit/primitives/icon";
import type { AnchorHTMLAttributes, ElementType, MouseEvent, ReactNode } from "react";

export interface CandidateProfileLinkButtonProps
  extends Omit<AnchorHTMLAttributes<HTMLAnchorElement>, "children" | "href" | "title" | "target"> {
  /** Where the profile lives. The host resolves it, including any search fallback. */
  href: string;
  /** Tooltip and accessible name, worded by the host. */
  title: string;
  /** The glyph for the profile's network or source, as a component reference. */
  icon: ElementType;
  /** Icon-only size. */
  size?: "default" | "lg";
  /** An icon-only ghost button, or an outline button with a visible label. */
  presentation?: "icon" | "button";
  /** Visible label for `presentation="button"`. */
  buttonLabel?: ReactNode;
  /** Icon colour: `disabled` mutes it, for example when the host has no exact profile. */
  iconTone?: "info" | "disabled";
}

/**
 * Opens a candidate's external profile in a new tab.
 *
 * The icon form stops the click from reaching a surrounding candidate card.
 * Recruit UI ships no network glyph or URL scheme: the host passes both. The
 * root is the kit Button rendered as a link, and keeps the kit's own
 * `data-slot="button"`, which theme stylesheets select on.
 */
export function CandidateProfileLinkButton({
  href,
  title,
  icon,
  size = "default",
  presentation = "icon",
  buttonLabel = "Open profile",
  iconTone = "info",
  onClick,
  ...props
}: CandidateProfileLinkButtonProps) {
  if (presentation === "button") {
    return (
      <Button asChild variant="outline" size="sm" shrink>
        <Anchor href={href} target="_blank" rel="noreferrer" title={title} onClick={onClick} {...props}>
          <Icon icon={icon} size="md" tone={iconTone} /> {buttonLabel}
        </Anchor>
      </Button>
    );
  }

  return (
    <Button asChild variant="ghost" size={size === "lg" ? "icon-md" : "icon-sm"} shrink>
      <Anchor
        href={href}
        target="_blank"
        rel="noreferrer"
        onClick={(event: MouseEvent<HTMLAnchorElement>) => {
          event.stopPropagation();
          onClick?.(event);
        }}
        title={title}
        {...props}
      >
        <Icon icon={icon} size={size === "lg" ? "lg" : "md"} tone={iconTone} />
      </Anchor>
    </Button>
  );
}

import { cn } from "@epicbagel/saas-kit/lib/utils";
import { ContactHeader } from "@epicbagel/saas-kit/primitives/contact-header";
import { FlexItem } from "@epicbagel/saas-kit/primitives/flex-item";
import { Heading } from "@epicbagel/saas-kit/primitives/heading";
import { PanelSection } from "@epicbagel/saas-kit/primitives/panel-section";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import type { HTMLAttributes, ReactNode } from "react";

import { CandidateCoverHeader, type CandidateCoverHeaderPadding } from "./candidate-cover-header";

export interface CandidateProfileProps
  extends Omit<HTMLAttributes<HTMLElement>, "title"> {
  header?: ReactNode;
  children: ReactNode;
  footer?: ReactNode;
  /**
   * `default` prints the card as it looks on screen. `flat` prints it without
   * its border (or a shadow a host gave it), so a printed profile reads as a
   * page rather than a card on one.
   */
  printMode?: CandidateProfilePrintMode;
}

/** How a CandidateProfile prints. */
export type CandidateProfilePrintMode = "default" | "flat";

/** Structural profile composition. Data loading and record policy stay outside. */
export function CandidateProfile({
  header,
  children,
  footer,
  printMode = "default",
  className,
  ...props
}: CandidateProfileProps) {
  return (
    <Stack
      as="article"
      data-slot="candidate-profile"
      gap="none"
      surface="card"
      radius="xl"
      overflow="hidden"
      className={cn(printMode === "flat" && "print:border-0 print:shadow-none", className)}
      {...props}
    >
      {header}
      {children}
      {footer}
    </Stack>
  );
}

export interface CandidateProfileHeaderProps
  extends HTMLAttributes<HTMLDivElement> {
  name: ReactNode;
  avatar?: ReactNode;
  cover?: ReactNode;
  eyebrow?: ReactNode;
  status?: ReactNode;
  meta?: ReactNode;
  summary?: ReactNode;
  actions?: ReactNode;
  /**
   * Where `actions` sit. `name` (the default) puts them on the name line, at
   * its end, with the meta running under them. `aside` gives them a column
   * of their own beside the whole identity, top-aligned, so a control taller
   * than the name's line doesn't push the meta away from the name.
   */
  actionsPlacement?: CandidateProfileHeaderActionsPlacement;
  /**
   * `lg` (the default) pads the header like a card's. `dialog` pads it like
   * the kit's dialog header, so as a CandidateProfileDialog's `header` the
   * name starts at the body's left edge, in line with what the body holds.
   * `none` sits it flush in a container the host already pads, such as a
   * drawer body.
   */
  padding?: Extract<CandidateCoverHeaderPadding, "lg" | "dialog" | "none">;
  /**
   * The name's heading level. 1 (the default) suits a profile that is the
   * page. 2, 3 or 4 suit one inside something that already has the page's
   * h1, such as a dialog over a page or a section of one. Only the tag
   * changes: the name looks the same at every level.
   */
  titleLevel?: CandidateProfileHeaderTitleLevel;
}

/** Where a CandidateProfileHeader puts its actions. */
export type CandidateProfileHeaderActionsPlacement = "name" | "aside";

/** The heading level of a CandidateProfileHeader's name. */
export type CandidateProfileHeaderTitleLevel = 1 | 2 | 3 | 4;

/**
 * The person's identity: avatar, name with its status, actions and meta. At
 * level 1 it is the kit's ContactHeader, whose name is an h1. At any other
 * level it is the same composition with the name at that level: the
 * ContactHeader's rows, gaps and name type, restated from kit primitives,
 * because the kit's name takes no level.
 */
function ProfileIdentity({
  level,
  avatar,
  name,
  status,
  meta,
  actions,
}: {
  level: CandidateProfileHeaderTitleLevel;
  avatar?: ReactNode;
  name: ReactNode;
  status?: ReactNode;
  meta?: ReactNode;
  actions?: ReactNode;
}) {
  if (level === 1) {
    return (
      <ContactHeader
        avatar={avatar}
        name={name}
        status={status}
        meta={meta}
        actions={actions}
        spacing="none"
      />
    );
  }

  return (
    <Stack direction="horizontal" gap="md" align="start">
      {avatar ? <FlexItem shrink={false}>{avatar}</FlexItem> : null}
      <FlexItem grow minWidth="zero">
        <Stack direction="horizontal" gap="compact" align="start" justify="between">
          {/* The ContactHeader name's type: the level-2 size without its
              leading-tight (restating the size drops it), so the line height
              is the size's own. */}
          <Heading level={2} as={`h${level}`} className="min-w-0 text-xl md:text-2xl">
            <span className="inline-flex min-w-0 max-w-full items-center gap-2">
              {name}
              {status}
            </span>
          </Heading>
          {/* 6px between actions and between meta items: half a step off the
              Stack scale, as the ContactHeader sets them. */}
          {actions ? (
            <Stack direction="horizontal" align="center" shrink={false} className="gap-1.5">
              {actions}
            </Stack>
          ) : null}
        </Stack>
        {meta ? (
          <Stack direction="horizontal" align="center" wrap className="mt-1.5 gap-1.5">
            {meta}
          </Stack>
        ) : null}
      </FlexItem>
    </Stack>
  );
}

export function CandidateProfileHeader({
  name,
  avatar,
  cover,
  eyebrow,
  status,
  meta,
  summary,
  actions,
  actionsPlacement = "name",
  padding = "lg",
  titleLevel = 1,
  className,
  ...props
}: CandidateProfileHeaderProps) {
  const aside = actionsPlacement === "aside" && actions != null;
  const identity = (
    <ProfileIdentity
      level={titleLevel}
      avatar={avatar}
      name={name}
      status={status}
      meta={meta}
      actions={aside ? undefined : actions}
    />
  );

  return (
    <CandidateCoverHeader
      cover={cover}
      padding={padding}
      data-slot="candidate-profile-header"
      className={className}
      {...props}
    >
      <Stack gap="sm">
        {eyebrow != null ? (
          <Text variant="eyebrow">{eyebrow}</Text>
        ) : null}
        {aside ? (
          <Stack direction="horizontal" gap="sm" align="start">
            <FlexItem grow minWidth="zero">
              {identity}
            </FlexItem>
            {/* An action cluster like the kit ContactHeader's, beside the
                identity: a row that keeps its width, at the kit's nearest gap. */}
            <Stack
              data-slot="candidate-profile-header-actions"
              direction="horizontal"
              gap="xs"
              align="center"
              shrink={false}
            >
              {actions}
            </Stack>
          </Stack>
        ) : (
          identity
        )}
        {summary != null ? (
          <Text variant="muted" size="sm">
            {summary}
          </Text>
        ) : null}
      </Stack>
    </CandidateCoverHeader>
  );
}

export interface CandidateProfileBodyProps
  extends HTMLAttributes<HTMLDivElement> {
  children: ReactNode;
  divided?: boolean;
}

export function CandidateProfileBody({
  children,
  divided = false,
  className,
  ...props
}: CandidateProfileBodyProps) {
  return (
    <PanelSection
      as="div"
      data-slot="candidate-profile-body"
      border="top"
      className={cn(divided && "divide-y", className)}
      {...props}
    >
      {children}
    </PanelSection>
  );
}

export interface CandidateProfileFooterProps
  extends HTMLAttributes<HTMLElement> {
  children: ReactNode;
  /** Where the row's content sits along it. `start` by default. */
  justify?: CandidateProfileFooterJustify;
  /**
   * The kit PanelSection's padding: `default` (26px) for a row of actions,
   * `compact` for a single line such as a credit.
   */
  padding?: CandidateProfileFooterPadding;
  /** `hidden` leaves the footer off a printed profile. */
  printVisibility?: CandidateProfileFooterPrintVisibility;
}

/** Where a CandidateProfileFooter puts its content along the row. */
export type CandidateProfileFooterJustify = "start" | "center" | "end" | "between";
/** The space inside a CandidateProfileFooter. */
export type CandidateProfileFooterPadding = "default" | "compact";
/** Whether a CandidateProfileFooter prints. */
export type CandidateProfileFooterPrintVisibility = "visible" | "hidden";

// `start` is a flex row's own default, so it adds nothing.
const FOOTER_JUSTIFY: Record<CandidateProfileFooterJustify, string> = {
  start: "",
  center: "justify-center",
  end: "justify-end",
  between: "justify-between",
};

export function CandidateProfileFooter({
  children,
  justify = "start",
  padding = "default",
  printVisibility = "visible",
  className,
  ...props
}: CandidateProfileFooterProps) {
  return (
    <PanelSection
      as="footer"
      data-slot="candidate-profile-footer"
      border="top"
      layout="row"
      gap="sm"
      padding={padding}
      className={cn(
        FOOTER_JUSTIFY[justify],
        printVisibility === "hidden" && "print:hidden",
        className,
      )}
      {...props}
    >
      {children}
    </PanelSection>
  );
}

"use client";

import { Button } from "@epicbagel/saas-kit/primitives/button";
import { FlexItem } from "@epicbagel/saas-kit/primitives/flex-item";
import { PanelSection } from "@epicbagel/saas-kit/primitives/panel-section";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import { useState, type BlockquoteHTMLAttributes, type MouseEvent, type ReactNode } from "react";

/** Clamps a long excerpt behind a show-more toggle on the attribution line. */
export interface CandidateQuoteCollapsible {
  /** Lines shown while collapsed. */
  lines: 1 | 2 | 3;
  /**
   * Offer the toggle only when the excerpt is longer than this many
   * characters. It applies to a plain-string excerpt; any other excerpt
   * always gets the toggle.
   */
  threshold?: number;
  moreLabel: ReactNode;
  lessLabel: ReactNode;
}

export interface CandidateQuoteProps
  extends BlockquoteHTMLAttributes<HTMLQuoteElement> {
  children: ReactNode;
  attribution?: ReactNode;
  action?: ReactNode;
  /** Clamp the excerpt to this many lines. `collapsible` replaces it. */
  lineClamp?: 1 | 2 | 3;
  collapsible?: CandidateQuoteCollapsible;
}

/** A quiet excerpt whose hierarchy comes from whitespace, never a nested card. */
export function CandidateQuote({
  children,
  attribution,
  action,
  lineClamp,
  collapsible,
  ...props
}: CandidateQuoteProps) {
  const [expanded, setExpanded] = useState(false);
  const canExpand =
    collapsible?.threshold == null ||
    typeof children !== "string" ||
    children.length > collapsible.threshold;
  const clamp = collapsible ? (expanded ? undefined : collapsible.lines) : lineClamp;
  const toggle = collapsible != null && canExpand ? (
    <Button
      type="button"
      variant="link"
      size="bare"
      shrink
      onClick={(event: MouseEvent<HTMLButtonElement>) => {
        // The quote often sits inside a clickable candidate card.
        event.stopPropagation();
        setExpanded((value) => !value);
      }}
    >
      {expanded ? collapsible.lessLabel : collapsible.moreLabel}
    </Button>
  ) : null;
  const actions = action != null && toggle != null ? <>{action}{toggle}</> : action ?? toggle;

  return (
    <PanelSection
      as="blockquote"
      data-slot="candidate-quote"
      padding="default"
      {...props}
    >
      <Text as="div" variant="muted" size="sm" italic lineClamp={clamp}>
        <span aria-hidden>&ldquo;</span>
        {children}
        <span aria-hidden>&rdquo;</span>
      </Text>
      {attribution != null || actions != null ? (
        <Stack direction="horizontal" gap="compact" align="center" marginTop="sm">
          <FlexItem grow minWidth="zero">
            {attribution != null ? (
              <Text as="span" variant="caption" size="xs" tone="subtle">
                <span aria-hidden>— </span>
                {attribution}
              </Text>
            ) : null}
          </FlexItem>
          {actions}
        </Stack>
      ) : null}
    </PanelSection>
  );
}

"use client";

import { Badge } from "@epicbagel/saas-kit/primitives/badge";
import { Button } from "@epicbagel/saas-kit/primitives/button";
