const LOCALE = "en-GB";
const plain = new Intl.NumberFormat(LOCALE, { maximumFractionDigits: 0 });

const ROLE_DETAILS = ["quota", "equity", "avgDealSize", "biggestDeal", "salesCycle", "motion"] as const;

// A brief can name dozens of target companies: the section shows this many
// and folds the rest under a toggle that counts them.
const TARGET_COMPANIES_SHOWN = 5;

// A title fits a sidebar row and a card heading alike.
const MAX_TITLE_LENGTH = 72;

// Values a parser returns when a field is absent rather than a real value.
const ABSENT_VALUE =
  /^(?:n\/?a|none|null|nil|unknown|tbd|tbc|not (?:specified|provided|stated|known)|unspecified|confidential|undisclosed|untitled|role|job|position|title|various|multiple(?: roles)?|-+)$/i;

/** Trimmed text; absent, blank and non-text are all undefined. */
function text(value: unknown): string | undefined {
  return typeof value === "string" ? value.trim() || undefined : undefined;
}

function finite(value: unknown): number | undefined {
  return typeof value === "number" && Number.isFinite(value) ? value : undefined;
}

function truncate(value: string, max: number): string {
  const clean = value.trim();
  return clean.length > max ? `${clean.slice(0, max - 3).trimEnd()}…` : clean;
}

/** A title part as display text: whitespace collapsed, quotes and markdown stripped, a placeholder dropped. */
function titleText(value: unknown, max: number): string | undefined {
  if (typeof value !== "string") return undefined;
  const clean = value
    .replace(/\s+/g, " ")
    .replace(/^[\s"'“”‘’`*#]+|[\s"'“”‘’`*]+$/g, "")
    .trim();
  return clean && !ABSENT_VALUE.test(clean) ? truncate(clean, max) : undefined;
}

function capitalise(value: string): string {
  return `${value.charAt(0).toUpperCase()}${value.slice(1)}`;
}

/** Formats one amount: with the currency's symbol when there is one, else a bare grouped number. */
function amountFormat(currency: unknown): (value: number) => string {
  const code = text(currency);
  if (!code) return (value) => plain.format(value);
  try {
    const money = new Intl.NumberFormat(LOCALE, {
      style: "currency",
      currency: code,
      currencyDisplay: "narrowSymbol",
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    });
    return (value) => money.format(value);
  } catch {
    // Not an ISO 4217 code: shown as given, a symbol ("£") against the
    // amount and a word apart from it.
    return (value) => (/\p{L}$/u.test(code) ? `${code} ${plain.format(value)}` : `${code}${plain.format(value)}`);
  }
}

function fact(id: string, label: string, value: string | null | undefined): JobBriefViewFact[] {
  return value ? [{ id, label, value }] : [];
}

/**
 * A brief's title: "Role · Company", or the role alone when there is no
 * company, the role already names it, or the pair would run past 72
 * characters (a long role is cut to fit). A placeholder the parser returns
 * for an absent field ("TBD", "N/A", "Role") counts as no value. With no role,
 * `fallback`.
 */
export function jobBriefTitle(
  content: Pick<JobBriefContent, "roleTitle" | "companyName">,
  fallback: string = jobBriefLabels.title,
): string {
  const role = titleText(content.roleTitle, 240);
  if (!role) return fallback;
  const company = titleText(content.companyName, 120);
  if (company && !role.toLowerCase().includes(company.toLowerCase())) {
    const combined = `${role} · ${company}`;
    if (combined.length <= MAX_TITLE_LENGTH) return combined;
  }
  return truncate(role, MAX_TITLE_LENGTH);
}

/**
 * A brief's salary band in full, grouped numbers: "80,000–100,000", one
 * figure when both ends agree, "From 80,000" or "Up to 100,000" with one
 * end. The currency's symbol leads each amount only when `currency` is set
 * ("£80,000"). Null with neither end.
 */
export function formatJobBriefSalary(
  content: Pick<JobBriefContent, "salaryMin" | "salaryMax" | "currency">,
  labels: Partial<Pick<JobBriefLabels, "salaryFrom" | "salaryUpTo">> = {},
): string | null {
  const min = finite(content.salaryMin);
  const max = finite(content.salaryMax);
  const amount = amountFormat(content.currency);
  if (min !== undefined && max !== undefined) {
    return min === max ? amount(min) : `${amount(Math.min(min, max))}–${amount(Math.max(min, max))}`;
  }
  if (min !== undefined) return (labels.salaryFrom ?? jobBriefLabels.salaryFrom)(amount(min));
  if (max !== undefined) return (labels.salaryUpTo ?? jobBriefLabels.salaryUpTo)(amount(max));
  return null;
}

function persona({ role, category, notes }: JobBriefPersona, categories: Readonly<Record<string, string>>): string {
  const who = text(role);
  const key = text(category);
  const kind = key ? (Object.hasOwn(categories, key) ? categories[key] : key.replace(/_/g, " ")) : undefined;
  const name = who ? (kind ? `${who} (${kind})` : who) : kind ? capitalise(kind) : "";
  return [name, text(notes)].filter(Boolean).join(" — ");
}

function interviewSteps(
  steps: readonly JobBriefInterviewStep[],
  named: boolean,
  labels: JobBriefLabels,
): string[] {
  return steps
    .map((step, index) => ({ step, index }))
    .sort(
      (left, right) =>
        (finite(left.step.stepNumber) ?? left.index + 1) - (finite(right.step.stepNumber) ?? right.index + 1) ||
        left.index - right.index,
    )
    .map(({ step }, index) => {
      const label = text(step.label);
      const format = text(step.expectedFormat);
      const interviewer = text(step.interviewerName);
      const name = label ?? format ?? labels.interviewStep(finite(step.stepNumber) ?? index + 1);
      const run = named && interviewer ? labels.interviewWith(name, interviewer) : name;
      return label && format ? `${run} · ${format}` : run;
    });
}

function companyFacts(content: JobBriefContent, labels: JobBriefLabels): JobBriefViewFact[] {
  const company = content.companyOverview ?? {};
  const founded = finite(company.founded);
  const headcount = finite(company.headcount);
  const arr = [...(company.arr ?? [])]
    .filter(({ year, value }) => finite(year) !== undefined && text(value))
    .sort((left, right) => left.year - right.year)
    .map(({ year, value }) => `${year}: ${text(value)}`);
  const team = (company.teamDistribution ?? [])
    .filter(({ region, count }) => text(region) && finite(count) !== undefined)
    .map(({ region, count }) => `${text(region)} ${plain.format(count)}`);
  return [
    ...fact("website", labels.website, text(content.companyWebsite)),
    ...fact("founded", labels.founded, founded === undefined ? null : String(founded)),
    ...fact("headcount", labels.headcount, headcount === undefined ? null : plain.format(headcount)),
    ...fact("hq", labels.hq, text(company.hq)),
    ...fact("arr", labels.arr, arr.join(" · ")),
    ...fact("team", labels.team, team.join(" · ")),
  ];
}

const ALL_RULES: readonly JobBriefRuleKind[] = ["mustHaves", "niceToHaves", "redFlags"];
const PUBLIC_RULES: readonly JobBriefRuleKind[] = ["mustHaves", "niceToHaves"];

/**
 * What a JobBriefCard shows for a brief, so the same brief reads the same
 * wherever it appears: spread the result onto the card and add only the
 * host's own props (presentation, status, editing, footer, open state).
 *
 * - The title follows `jobBriefTitle`, or is `labels.title` with `title:
 *   "generic"`.
 * - The description is the role description, else the summary, whether the
 *   brief is current or not.
 * - The facts are location, salary (`formatJobBriefSalary`) and on-target
 *   earnings, in that order, each only when the brief has it.
 * - The lists are the brief's own, in its order and as written, so an editable
 *   card hands back exactly what it was given.
 * - The sections are the role details, the target companies (the first five,
 *   the rest folded), target company types, buying personas, the interview
 *   process in step order and the company, then `extraSections`; only those
 *   with something in them.
 * - A current brief previews three facts and entries, an earlier one none.
 * - The lists are named, and their entries called, by `labels`, so the
 *   card's controls ("Add must-have…") read the same as the brief.
 *
 * With `audience: "public"`, the red flags, on-target earnings, role details,
 * target companies, company section and interviewers' names are left out, and
 * the red-flag list isn't among the `rules`.
 */
export function jobBriefView(content: JobBriefContent, options: JobBriefViewOptions = {}): JobBriefView {
  const { current = true, title = "role", audience, extraSections = [] } = options;
  const labels: JobBriefLabels = {
    ...jobBriefLabels,
    ...options.labels,
    personaCategories: { ...jobBriefLabels.personaCategories, ...options.labels?.personaCategories },
  };
  // A public page leaves out what the role's own team may not want seen outside it.
  const internal = audience !== "public";
  const details = content.roleDetails ?? {};
  const sections: JobBriefViewSection[] = [
    {
      id: "role-details",
      title: labels.roleDetails,
      facts: internal ? ROLE_DETAILS.flatMap((key) => fact(key, labels[key], text(details[key]))) : [],
    },
    {
      id: "target-companies",
      title: labels.targetCompanies,
      items: internal ? [...(content.targetCompanies ?? [])] : [],
      previewCount: TARGET_COMPANIES_SHOWN,
    },
    { id: "target-company-types", title: labels.targetCompanyTypes, items: [...(content.icp ?? [])] },
    {
      id: "buying-personas",
      title: labels.buyingPersonas,
      items: (content.buyingPersonas ?? []).map((entry) => persona(entry, labels.personaCategories)).filter(Boolean),
    },
    {
      id: "interview-process",
      title: labels.interviewProcess,
      ordered: true,
      items: interviewSteps(content.interviewSteps ?? [], internal, labels),
    },
    { id: "company", title: labels.company, facts: internal ? companyFacts(content, labels) : [] },
    ...extraSections,
  ];

  return {
    title: title === "generic" ? labels.title : jobBriefTitle(content, labels.title),
    description: text(content.roleDescription) ?? text(content.summary),
    facts: [
      ...fact("location", labels.location, text(content.location)),
      ...fact("salary", labels.salary, formatJobBriefSalary(content, labels)),
      ...(internal ? fact("ote", labels.ote, text(details.ote)) : []),
    ],
    mustHaves: [...(content.mustHaves ?? [])],
    niceToHaves: [...(content.niceToHaves ?? [])],
    redFlags: internal ? [...(content.redFlags ?? [])] : [],
    rules: [...(internal ? ALL_RULES : PUBLIC_RULES)],
    sections: sections.filter((section) => (section.facts?.length ?? 0) + (section.items?.length ?? 0) > 0),
    previewCount: current ? 3 : 0,
    ruleLabels: {
      mustHaves: labels.mustHaves,
      niceToHaves: labels.niceToHaves,
      redFlags: labels.redFlags,
      mustHaveItem: labels.mustHaveItem,
      niceToHaveItem: labels.niceToHaveItem,
      redFlagItem: labels.redFlagItem,
    },
  };
}

/* ---------- versions ---------- */

/** The words a brief's version reads in, as `jobBriefVersionLabel` puts them together. */
export interface JobBriefVersionLabels {
  /** A version's number as it reads: "v3". */
  number: (number: number) => string;
  /** What marks the version in force now: "Current". */
  current: string;
  /** What marks a version a later one replaced: "Earlier". Empty for the number alone. */
  earlier: string;
  /** Between the number and its mark: " · ". */
  separator: string;
}

/** The default wording of a brief's version. Pass `labels` to `jobBriefVersionLabel` to change any of it. */
export const jobBriefVersionLabels: Readonly<JobBriefVersionLabels> = Object.freeze({
  number: (number: number) => `v${number}`,
  current: "Current",
  earlier: "Earlier",
  separator: " · ",
});

/**
 * Which version of a brief a card shows: JobBriefCard's `version`, which it
 * draws in its status slot.
 */
export interface JobBriefVersion {
  /** The version's number, counted from 1. */
  number: number;
  /** Whether this is the version in force now, rather than one a later version replaced. */
  current: boolean;
  /** The version's whole wording, in place of `jobBriefVersionLabel`'s. */
  label?: string;
  /**
   * A second, neutral badge after the version's, such as the number another
   * system gives the same version ("Partner v48"), so people using either
   * name the same one.
   */
  secondaryLabel?: string;
}

/**
 * A version's wording: its number and whether it is in force, "v3 · Current"
 * for the version in force now and "v2 · Earlier" for one a later version
 * replaced, so the state is always in words and never in a badge's colour
 * alone. A number that isn't a whole number from 1 is left out, leaving the
 * mark ("Current"); an empty `labels.earlier` leaves an earlier version's
 * number alone ("v2"). The version's own `label`, when it has one, wins.
 */
export function jobBriefVersionLabel(
  version: Pick<JobBriefVersion, "number" | "current" | "label">,
  labels: Partial<JobBriefVersionLabels> = {},
): string {
  const own = text(version.label);
  if (own) return own;
  const words = { ...jobBriefVersionLabels, ...labels };
  const number = validVersion(version.number) ? words.number(version.number) : "";
  const mark = version.current ? words.current : words.earlier;
  return [number, mark].filter(Boolean).join(words.separator);
}

function validVersion(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value > 0;
}

/* ---------- what a version changed ---------- */

/**
 * What one change did: `set` a field's value, `cleared` it, `added` or
 * `removed` a list's entry, `reworded` one, `moved` one, or `replaced` a
 * whole field (a list of steps, say) at once.
 */
export type JobBriefChangeKind = "set" | "cleared" | "added" | "removed" | "reworded" | "moved" | "replaced";

/**
 * A value as a change shows it: text (whitespace collapsed, cut to 80
 * characters), a number (grouped, "80,000", so pass a year as text), or a
 * list, counted ("3 entries").
 */
export type JobBriefChangeValue = string | number | readonly unknown[];

/**
 * One change a version of a brief made, as display values: a host maps its
 * own record of a change onto this, naming the field in its own words.
 *
 * | kind | reads | uses |
 * | --- | --- | --- |
 * | `added` | Added must-have: Python | `item` |
 * | `removed` | Removed red flag: Job hopping | `item` |
 * | `reworded` | Reworded must-have: "Python" → "Python 3" | `from`, `to` |
 * | `moved` | Moved must-have "Python" to position 1 | `item`, `to` (the position) |
 * | `set` | Location: Remote → Hybrid | `fieldTitle`, `from`, `to` |
 * | `cleared` | Removed the location (was Remote) | `from` |
 * | `replaced` | Replaced the interview steps (3 entries) | `to` |
 *
 * An `added` or `removed` change can be about several entries of one list at
 * once, in `items`: "Added 12 target companies: Example Labs, Fictional
 * Robotics, Sample Analytics and 9 more". `groupJobBriefChanges` makes these
 * from a version's single changes, as `JobBriefChanges` does by default.
 *
 * With `prose`, the line says only that the field was added, updated or
 * removed ("Updated the role description"), since its text would swamp a line.
 */
export interface JobBriefChange {
  /** Stable key for the line. Defaults to its place in the list. */
  id?: string;
  kind: JobBriefChangeKind;
  /** The field's name as it reads mid-sentence: "must-have", "location", "OTE". */
  field: string;
  /** The field's name where it leads a `set` line: "Location". Defaults to `field` with a capital. */
  fieldTitle?: string;
  /**
   * The field's name for several of its entries, mid-sentence: "must-haves",
   * "target companies". Defaults to `field` made plural by `labels.plural`.
   */
  fieldPlural?: string | null;
  /** The list entry an `added`, `removed` or `moved` change is about. */
  item?: string | null;
  /**
   * The entries of one list an `added` or `removed` change is about, when it
   * is about several: the line counts them and names the first three.
   */
  items?: readonly string[] | null;
  /**
   * What it was: a `reworded` entry's old words, a `set` field's old value,
   * a `cleared` field's last value. Left out for a field set for the first time.
   */
  from?: JobBriefChangeValue | null;
  /**
   * What it is now: a `reworded` entry's new words, a `set` field's new
   * value, what a `replaced` field holds now. For `moved`, the entry's new
   * position, counted from 1.
   */
  to?: JobBriefChangeValue | null;
  /**
   * A prose field, such as a role description or a summary: the line says
   * only that it was added (no `from`), updated (a `from`) or removed
   * (`cleared`), never its text.
   */
  prose?: boolean;
}

/**
 * The words a version's changes read in. Each line's wording takes its
 * values already shaped for a line, and an empty string for one that is
 * absent.
 */
export interface JobBriefChangeLabels {
  /** "Added must-have: Python". */
  added: (field: string, item: string) => string;
  /** "Removed red flag: Job hopping". */
  removed: (field: string, item: string) => string;
  /**
   * Several entries added to one list, given the field's plural, how many,
   * and `someEntries`' words for them: "Added 12 target companies: Example
   * Labs, Fictional Robotics, Sample Analytics and 9 more".
   */
  addedSeveral: (fieldPlural: string, count: string, entries: string) => string;
  /** Several entries removed from one list: "Removed 4 must-haves: Python, Go, Rust and 1 more". */
  removedSeveral: (fieldPlural: string, count: string, entries: string) => string;
  /**
   * The entries a line names, then how many it leaves out: "Example Labs,
   * Fictional Robotics, Sample Analytics and 9 more"; with none left out,
   * "Python, Go and Rust".
   */
  someEntries: (entries: readonly string[], more: number) => string;
  /**
   * A field's name for several entries, from its name for one, for a change
   * with no `fieldPlural`: "must-have" → "must-haves", "target company" →
   * "target companies".
   */
  plural: (field: string) => string;
  /** 'Reworded must-have: "Python" → "Python 3"'. */
  reworded: (field: string, from: string, to: string) => string;
  /** 'Moved must-have "Python" to position 1'; without a position, 'Moved must-have "Python"'. */
  moved: (field: string, item: string, position: string) => string;
  /** "Location: Remote → Hybrid"; without an old value, "Location: Hybrid". */
  set: (fieldTitle: string, from: string, to: string) => string;
  /** "Removed the location (was Remote)"; without its last value, "Removed the location". */
  cleared: (field: string, from: string) => string;
  /** "Replaced the interview steps (3 entries)". */
  replaced: (field: string, to: string) => string;
  /** A prose field set for the first time: "Added a role description". */
  proseAdded: (field: string) => string;
  /** A prose field rewritten: "Updated the role description". */
  proseUpdated: (field: string) => string;
  /** A prose field removed: "Removed the role description". */
  proseCleared: (field: string) => string;
  /** A list as a value, by how many entries it holds: "3 entries". */
  entries: (count: number) => string;
  /** JobBriefChanges' toggle, by how many changes it folds away: "2 more changes". */
  more: (count: number) => string;
  /** JobBriefChanges' name for a screen reader, by the version the changes made: "What changed in v3". */
  groupName: (version?: number) => string;
}

/** The default wording of a version's changes. Pass `labels` to change any of it. */
export const jobBriefChangeLabels: Readonly<JobBriefChangeLabels> = Object.freeze({
  added: (field: string, item: string) => (item ? `Added ${field}: ${item}` : `Added ${field}`),
  removed: (field: string, item: string) => (item ? `Removed ${field}: ${item}` : `Removed ${field}`),
  addedSeveral: (fieldPlural: string, count: string, entries: string) =>
    entries ? `Added ${count} ${fieldPlural}: ${entries}` : `Added ${count} ${fieldPlural}`,
  removedSeveral: (fieldPlural: string, count: string, entries: string) =>
    entries ? `Removed ${count} ${fieldPlural}: ${entries}` : `Removed ${count} ${fieldPlural}`,
  someEntries: (entries: readonly string[], more: number) => {
    if (more > 0) return `${entries.join(", ")} and ${plain.format(more)} more`;
    return entries.length > 1 ? `${entries.slice(0, -1).join(", ")} and ${entries.at(-1)}` : (entries[0] ?? "");
  },
  plural: (field: string) => {
    if (/[^aeiou]y$/i.test(field)) return `${field.slice(0, -1)}ies`;
    return /(?:s|x|z|ch|sh)$/i.test(field) ? `${field}es` : `${field}s`;
  },
  reworded: (field: string, from: string, to: string) =>
    from && to ? `Reworded ${field}: "${from}" → "${to}"` : to ? `Reworded ${field}: "${to}"` : `Reworded ${field}`,
  moved: (field: string, item: string, position: string) => {
    const moved = item ? `Moved ${field} "${item}"` : `Moved ${field}`;
    return position ? `${moved} to position ${position}` : moved;
  },
  set: (fieldTitle: string, from: string, to: string) =>
    from && to ? `${fieldTitle}: ${from} → ${to}` : to ? `${fieldTitle}: ${to}` : fieldTitle,
  cleared: (field: string, from: string) => (from ? `Removed the ${field} (was ${from})` : `Removed the ${field}`),
  replaced: (field: string, to: string) => (to ? `Replaced the ${field} (${to})` : `Replaced the ${field}`),
  proseAdded: (field: string) => `Added ${/^[aeiou]/i.test(field) ? "an" : "a"} ${field}`,
  proseUpdated: (field: string) => `Updated the ${field}`,
  proseCleared: (field: string) => `Removed the ${field}`,
  entries: (count: number) => `${plain.format(count)} ${count === 1 ? "entry" : "entries"}`,
  more: (count: number) => `${plain.format(count)} more ${count === 1 ? "change" : "changes"}`,
  groupName: (version?: number) =>
    validVersion(version) ? `What changed in ${jobBriefVersionLabels.number(version)}` : "What changed",
});

// A value longer than this is cut, so one change never swamps its line.
const MAX_CHANGE_VALUE_LENGTH = 80;
const grouped = new Intl.NumberFormat(LOCALE);
// A line about several entries of a list names this many and counts the rest.
const NAMED_ENTRIES = 3;

/** A change's value as a line shows it, or an empty string for none. */
function changeValue(value: unknown, labels: JobBriefChangeLabels): string {
  if (typeof value === "string") {
    // Cut by characters, never through one (a surrogate pair stays whole).
    const characters = Array.from(value.replace(/\s+/g, " ").trim());
    return characters.length > MAX_CHANGE_VALUE_LENGTH
      ? `${characters.slice(0, MAX_CHANGE_VALUE_LENGTH - 3).join("").trimEnd()}…`
      : characters.join("");
  }
  if (typeof value === "number") return Number.isFinite(value) ? grouped.format(value) : "";
  if (Array.isArray(value)) return labels.entries(value.length);
  return "";
}

/**
 * One change as a line: "Added must-have: Python", "Location: Remote →
 * Hybrid", "Removed the location (was Remote)", in the field's own words
 * (`field`, and `fieldTitle` where it leads the line). Each value is shaped
 * for a line: text with its whitespace collapsed and cut to 80 characters
 * with an ellipsis, a number grouped ("80,000"), a list counted ("3
 * entries"). A `set` with nothing new and an old value reads as `cleared`; a
 * `prose` field says only that it was added, updated or removed. An `added`
 * or `removed` change about several entries (`items`) counts them under the
 * field's plural and names the first three: "Added 12 target companies:
 * Example Labs, Fictional Robotics, Sample Analytics and 9 more".
 */
export function jobBriefChangeText(change: JobBriefChange, labels: Partial<JobBriefChangeLabels> = {}): string {
  const words: JobBriefChangeLabels = { ...jobBriefChangeLabels, ...labels };
  const field = text(change.field) ?? "";
  const from = changeValue(change.from, words);
  const to = changeValue(change.to, words);
  const entries = (Array.isArray(change.items) ? change.items : []).map((entry) => changeValue(entry, words)).filter(Boolean);
  // One entry in `items` is a single change, worded as one.
  const item = entries.length === 1 ? entries[0]! : changeValue(change.item, words);
  if (change.prose) {
    if (change.kind === "cleared" || change.kind === "removed") return words.proseCleared(field);
    return from ? words.proseUpdated(field) : words.proseAdded(field);
  }
  if (entries.length > 1 && (change.kind === "added" || change.kind === "removed")) {
    const plural = text(change.fieldPlural) ?? words.plural(field);
    const named = entries.slice(0, NAMED_ENTRIES);
    const listed = words.someEntries(named, entries.length - named.length);
    const count = plain.format(entries.length);
    return change.kind === "added" ? words.addedSeveral(plural, count, listed) : words.removedSeveral(plural, count, listed);
  }
  switch (change.kind) {
    case "added":
      return words.added(field, item);
    case "removed":
      return words.removed(field, item);
    case "reworded":
      return words.reworded(field, from, to);
    case "moved":
      return words.moved(field, item, to);
    case "cleared":
      return words.cleared(field, from);
    case "replaced":
      return words.replaced(field, to);
    case "set":
    default:
      // A kind this release doesn't know reads as a new value, never as nothing.
      if (!to && from) return words.cleared(field, from);
      return words.set(text(change.fieldTitle) ?? capitalise(field), from, to);
  }
}

// How many entries one list can gain, or lose, in a version before they read as one line.
const GROUP_ABOVE = 3;

/** An added or removed entry of a list, as a group can hold it: its key, and its words. */
function groupableEntry(change: JobBriefChange): { key: string; entry: string } | null {
  if ((change.kind !== "added" && change.kind !== "removed") || change.prose || change.items != null) return null;
  const entry = typeof change.item === "string" ? change.item.trim() : "";
  const field = text(change.field);
  return entry && field ? { key: `${change.kind}\u0000${field}`, entry } : null;
}

/**
 * A version's changes with the entries one list gained, or lost, read
 * together once there are more than `above` of them (three by default): one
 * `added` or `removed` change holding them all in `items`, in the place of the
 * first, keyed by its `id` and named by its `field` and `fieldPlural`. So a
 * version that adds a dozen target companies reads "Added 12 target
 * companies: Example Labs, Fictional Robotics, Sample Analytics and 9 more",
 * not twelve lines. Every other change stays as it is, in its order. Entries
 * belong to one list when their changes name the same `field`.
 */
export function groupJobBriefChanges(
  changes: readonly JobBriefChange[],
  above: number = GROUP_ABOVE,
): JobBriefChange[] {
  const limit = Number.isNaN(above) ? GROUP_ABOVE : above;
  const counts = new Map<string, number>();
  for (const change of changes) {
    const groupable = groupableEntry(change);
    if (groupable) counts.set(groupable.key, (counts.get(groupable.key) ?? 0) + 1);
  }
  const groups = new Map<string, string[]>();
  const lines: JobBriefChange[] = [];
  for (const change of changes) {
    const groupable = groupableEntry(change);
    if (!groupable || (counts.get(groupable.key) ?? 0) <= limit) {
      lines.push(change);
      continue;
    }
    const entries = groups.get(groupable.key);
    if (entries) {
      entries.push(groupable.entry);
      continue;
    }
    const first = [groupable.entry];
    groups.set(groupable.key, first);
    const { item: _item, from: _from, to: _to, ...rest } = change;
    lines.push({ ...rest, items: first });
  }
  return lines;
}

import { Badge } from "@epicbagel/saas-kit/primitives/badge";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import type { HTMLAttributes, ReactNode } from "react";

export interface JobClientBadgeProps
  extends Omit<HTMLAttributes<HTMLSpanElement>, "children"> {
  /** The organisation the job is for, as the host names it. */
  name: ReactNode;
  /**
   * Tooltip. Defaults to the name when the name is plain text; pass your own
   * wording, such as "Client: …".
   */
  title?: string;
}

/**
 * The organisation a job is for: a quiet secondary badge with the name on one
 * line. It names an organisation, not a contact person. The root is the kit
 * Badge and keeps the kit's own `data-slot="badge"`, which theme stylesheets
 * select on.
 */
export function JobClientBadge({ name, title, ...props }: JobClientBadgeProps) {
  return (
    <Badge
      as="span"
      variant="secondary"
      title={title ?? (typeof name === "string" ? name : undefined)}
      {...props}
    >
      <Text as="span" variant="inherit" truncate minWidth="zero">
        {name}
      </Text>
    </Badge>
  );
}

"use client";

import { Icon } from "@epicbagel/saas-kit/primitives/icon";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import { Timeline, TimelineRow } from "@epicbagel/saas-kit/primitives/timeline";
import { Check, Circle, CircleDot } from "lucide-react";
import type { HTMLAttributes, Key, ReactNode } from "react";

/** Where a step of a search stands. */
export type JobSearchStepState = "done" | "current" | "upcoming";

/** One step of a search, as the person waiting on it reads it. */
export interface JobSearchStep {
  id: Key;
  /** The step's name, such as "Shortlist". */
  title: ReactNode;
  state: JobSearchStepState;
  /** What happens in this step, or what happened. */
  description?: ReactNode;
  /** At the row's end, such as a date or how long the step takes. */
  meta?: ReactNode;
  /**
   * Under the description, such as a link to book a call. Usually given
   * only on the current step: it is what the reader does next.
   */
  action?: ReactNode;
}

/** Host-owned wording for each state, read out beside the step's name. */
export interface JobSearchProgressLabels {
  done: string;
  current: string;
  upcoming: string;
}

const DEFAULT_LABELS: JobSearchProgressLabels = {
  done: "Done",
  current: "In progress",
  upcoming: "Not started",
};

const GLYPHS = { done: Check, current: CircleDot, upcoming: Circle } as const;

export interface JobSearchProgressProps
  extends Omit<HTMLAttributes<HTMLElement>, "children"> {
  /** The steps, in the order they happen. */
  steps: readonly JobSearchStep[];
  labels?: Partial<JobSearchProgressLabels>;
}

/**
 * Where a search stands, for the person it is run for: its steps in order,
 * each done, in progress or still to come, with the current step's next
 * action under it. A client's view of a search, or a recruiter's summary of
 * one.
 *
 * The host decides the steps, their wording and which is current: the
 * component holds no workflow. A step's state is a glyph and a visually
 * hidden word (`labels`), never colour alone, and the current step carries
 * `aria-current="step"`. Upcoming steps are muted. The root is marked
 * `data-slot="job-search-progress"`; each step is a kit timeline row inside
 * a list item marked `data-slot="job-search-step"` with its state in
 * `data-state`.
 */
export function JobSearchProgress({ steps, labels, ...props }: JobSearchProgressProps) {
  const text = { ...DEFAULT_LABELS, ...labels };

  return (
    <Stack as="section" data-slot="job-search-progress" gap="none" {...props}>
      <Timeline spacing="tight">
        <ol className="m-0 list-none space-y-2 p-0">
          {steps.map((step) => (
            <li
              key={step.id}
              data-slot="job-search-step"
              data-state={step.state}
              aria-current={step.state === "current" ? "step" : undefined}
            >
              <TimelineRow
                surface={step.state === "current" ? "muted" : "transparent"}
                icon={
                  <Text
                    as="span"
                    variant="inherit"
                    tone={step.state === "upcoming" ? "muted" : undefined}
                  >
                    <Icon icon={GLYPHS[step.state]} size="sm" />
                    <span className="sr-only">{text[step.state]}: </span>
                  </Text>
                }
                title={
                  <Text
                    as="span"
                    variant="inherit"
                    weight={step.state === "current" ? "semibold" : undefined}
                    tone={step.state === "upcoming" ? "muted" : undefined}
                  >
                    {step.title}
                  </Text>
                }
                timestamp={step.meta}
              >
                {/* Under the title rather than as the row's subtitle, which the kit keeps to one line. */}
                {step.description != null && step.description !== false && step.description !== "" ? (
                  <Text size="sm" tone="muted">
                    {step.description}
                  </Text>
                ) : null}
                {step.action != null && step.action !== false ? (
                  <Stack direction="horizontal" gap="sm" wrap marginTop="sm">
                    {step.action}
                  </Stack>
                ) : null}
              </TimelineRow>
            </li>
          ))}
        </ol>
      </Timeline>
    </Stack>
  );
}

"use client";

import { DefinitionItem, DefinitionList } from "@epicbagel/saas-kit/primitives/definition-list";
import { FlexItem } from "@epicbagel/saas-kit/primitives/flex-item";
import { Heading } from "@epicbagel/saas-kit/primitives/heading";
import { InteractiveCard } from "@epicbagel/saas-kit/primitives/interactive-card";
import { PanelSection } from "@epicbagel/saas-kit/primitives/panel-section";
import { ResourceCard, ResourceCardFooter } from "@epicbagel/saas-kit/primitives/resource-card";
import { Spacer } from "@epicbagel/saas-kit/primitives/spacer";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import type { HTMLAttributes, ReactNode } from "react";

/** One labelled fact on a job card, such as a location or a count. */
export interface JobSummaryFact {
  /** Stable key for the row. */
  id: string;
  label: ReactNode;
  value: ReactNode;
}

export interface JobSummaryCardProps
  extends Omit<HTMLAttributes<HTMLDivElement>, "title" | "children"> {
  /** The job title, rendered as the card's level-3 heading. */
  title: ReactNode;
  /** A muted line under the title. */
  subtitle?: ReactNode;
  /** Media before the title, such as the client's logo. */
  logo?: ReactNode;
  /** A badge at the end of the header, such as `JobClientBadge` or a status. */
  badge?: ReactNode;
  /** The rows of the fact list, in order. */
  facts: readonly JobSummaryFact[];
  /** Called when the header or facts are activated. */
  onSelect?: () => void;
  /** Actions in a footer row outside the clickable area. */
  footer?: ReactNode;
  footerAlign?: "start" | "end" | "between";
}

function shown(node: ReactNode): boolean {
  return node != null && node !== false && node !== "";
}

/**
 * A job at a glance: identity, a divided fact list, and optional actions.
 *
 * The header and facts are one button that opens the job. The footer sits
 * outside it, so its actions never also open the job. Every value enters
 * through a slot: the host decides which facts to show and how to word them.
 * The root is the kit ResourceCard, marked `data-slot="job-summary-card"`.
 */
export function JobSummaryCard({
  title,
  subtitle,
  logo,
  badge,
  facts,
  onSelect,
  footer,
  footerAlign = "start",
  ...props
}: JobSummaryCardProps) {
  const hasFooter = shown(footer);

  return (
    <ResourceCard data-slot="job-summary-card" {...props}>
      <InteractiveCard
        type="button"
        display="block"
        border="none"
        joined={hasFooter ? "top" : "none"}
        onClick={onSelect}
      >
        <PanelSection padding="none" paddingX="md" paddingTop="lg" paddingBottom="lg">
          <Stack direction="horizontal" gap="sm" justify="between" align="center" wrap>
            <FlexItem grow minWidth="zero" basis="sm">
              <Stack direction="horizontal" gap="sm" align="center" minWidth="zero">
                {logo}
                <FlexItem grow minWidth="zero">
                  <Heading level={3} as="h3">{title}</Heading>
                  {shown(subtitle) ? (
                    <Text size="sm" tone="muted" marginTop="xs">{subtitle}</Text>
                  ) : null}
                </FlexItem>
              </Stack>
            </FlexItem>
            {shown(badge) ? <Stack as="span" minWidth="zero">{badge}</Stack> : null}
          </Stack>
        </PanelSection>
        <DefinitionList variant="divided" inset="lg">
          {facts.map((fact) => (
            <DefinitionItem key={fact.id} label={fact.label}>{fact.value}</DefinitionItem>
          ))}
        </DefinitionList>
        {hasFooter ? null : <Spacer size="lg" />}
      </InteractiveCard>
      {hasFooter ? (
        <ResourceCardFooter align={footerAlign} wrap>{footer}</ResourceCardFooter>
      ) : null}
    </ResourceCard>
  );
}

"use client";

import { Button } from "@epicbagel/saas-kit/primitives/button";
import { CallCard, type CallParticipant } from "@epicbagel/saas-kit/primitives/call-card";
import { EmptyState } from "@epicbagel/saas-kit/primitives/empty-state";
import { Icon } from "@epicbagel/saas-kit/primitives/icon";
import { Input } from "@epicbagel/saas-kit/primitives/input";
import { List, ListItem } from "@epicbagel/saas-kit/primitives/list";
import {
  ResponsiveDialog,
  ResponsiveDialogBody,
  ResponsiveDialogContent,
  ResponsiveDialogHeader,
  ResponsiveDialogTitle,
} from "@epicbagel/saas-kit/primitives/responsive-dialog";
import { Stack } from "@epicbagel/saas-kit/primitives/stack";
import { Text } from "@epicbagel/saas-kit/primitives/text";
import { BriefcaseBusiness, Loader2, Sparkles, UserSearch } from "lucide-react";
import { Fragment, useState, type ReactNode } from "react";

import type {
  CallInsights,
  CallPerson,
  CallSegment,
  CallTranscript,
  SearchCallPeople,
} from "./call-data";
import { CALL_PEOPLE_SEARCH_MIN_LENGTH, useCallPeopleSearch, useCallTranscript } from "./call-hooks";

/** Host-owned wording for the card's fixed parts. */
export interface MatchedCallCardLabels {
  /** The heading when the call has no title and no linked people. */
  untitled: string;
  /** The transcript toggle while it is closed. */
  showTranscript: string;
  /** Between two linked people in the heading. */
  peopleSeparator: ReactNode;
  /** Accessible name of a linked person's button. */
  openPerson: (name: string) => string;
  /** The heading over the insights. */
  insights: ReactNode;
  generate: ReactNode;
  regenerate: ReactNode;
  noRolesTitle: string;
  noRolesDescription: string;
  /** The header action that opens the link dialog. */
  linkPerson: ReactNode;
  linkTitle: ReactNode;
  searchPlaceholder: string;
  searching: ReactNode;
  noMatchesTitle: string;
  noMatchesDescription: string;
}

const DEFAULT_LABELS: MatchedCallCardLabels = {
  untitled: "Untitled call",
  showTranscript: "Show full transcript",
  peopleSeparator: " and ",
  openPerson: (name) => `Open ${name}`,
  insights: "Call insights",
  generate: "Generate",
  regenerate: "Regenerate",
  noRolesTitle: "No suggested roles yet",
  noRolesDescription: "No other live role fits this person from this call.",
  linkPerson: "Link another person",
  linkTitle: "Link this call to another person",
  searchPlaceholder: "Search people…",
  searching: "Searching…",
  noMatchesTitle: "No people match that name",
  noMatchesDescription: "Try a different name or spelling.",
};

/** Links the call to one more person, found by name. */
export interface MatchedCallLinkPerson<TPerson extends CallPerson = CallPerson> {
  searchPeople: SearchCallPeople<TPerson>;
  /**
   * Links the call. Resolve once it is linked: the dialog then closes and
   * clears its search, and the host adds the person to `people`. Reject when
   * it failed, having told the user why; the dialog stays open.
   */
  onLink: (person: TPerson) => Promise<void>;
}

export interface MatchedCallCardProps<TPerson extends CallPerson = CallPerson> {
  /** The call's title, shown when no person is linked yet. */
  title?: ReactNode;
  /** The people the call is linked to. They replace the title as buttons that open each one. */
  people?: readonly TPerson[];
  onOpenPerson?: (person: TPerson) => void;
  source?: ReactNode;
  timestamp?: ReactNode;
  /** Who was on the call besides the people in the heading. */
  participants?: readonly CallParticipant[];
  summary?: ReactNode;
  /** The transcript preview, until the full transcript loads. */
  transcript?: ReactNode;
  segments?: readonly CallSegment[] | null;
  /** Fetches the full transcript the first time it is opened. */
  loadTranscript?: () => Promise<CallTranscript | null | undefined>;
  /** Offers to link the call to another person. Omit it and the header has no link action. */
  linkPerson?: MatchedCallLinkPerson<TPerson>;
  /** The host's check of the call against its open roles. */
  insights: CallInsights;
  /** The roles the check suggested. Once insights are ready and this is empty, the card says no role fits. */
  roleMatches?: ReactNode;
  labels?: Partial<MatchedCallCardLabels>;
  /** Class for the card. Its root is the kit's CallCard, which takes no other attributes. */
  className?: string;
}

const isShown = (node: ReactNode) => node != null && node !== false && node !== "";

const noSearch: SearchCallPeople<never> = async () => [];

/**
 * A call already linked to one or more people, so it can be found again: the
 * linked people head the card and open each person, the transcript loads in
 * full when opened, and the footer holds the call's insights with a generate
 * action. A header action links the call to one more person through a search
 * dialog. The card keeps no record of its own: the host updates `people`
 * once a link is saved.
 */
export function MatchedCallCard<TPerson extends CallPerson>({
  title,
  people = [],
  onOpenPerson,
  source,
  timestamp,
  participants,
  summary,
  transcript,
  segments,
  loadTranscript,
  linkPerson,
  insights,
  roleMatches,
  labels,
  className,
}: MatchedCallCardProps<TPerson>) {
  const text = { ...DEFAULT_LABELS, ...labels };
  const call = useCallTranscript({ transcript, segments, loadTranscript });
  const [linkOpen, setLinkOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [linking, setLinking] = useState(false);
  const { results, searching } = useCallPeopleSearch<TPerson>(
    query,
    linkOpen && linkPerson != null,
    linkPerson?.searchPeople ?? noSearch,
  );
  const ready = insights.status === "ready";

  async function link(person: TPerson) {
    if (!linkPerson) return;
    setLinking(true);
    try {
      await linkPerson.onLink(person);
      setLinkOpen(false);
      setQuery("");
    } catch {
      // The host has said why; the dialog stays open to try again.
    } finally {
      setLinking(false);
    }
  }

  const heading = people.length > 0 ? (
    <Stack direction="horizontal" gap="xs" align="center" wrap>
      {people.map((person, index) => (
        <Fragment key={person.id}>
          {index > 0 && <Text as="span" variant="inherit">{text.peopleSeparator}</Text>}
          {onOpenPerson ? (
            <Button
              variant="ghost"
              size="compact"
              onClick={() => onOpenPerson(person)}
              aria-label={text.openPerson(person.name)}
            >
              {person.name}
            </Button>
          ) : (
            <Text as="span" variant="inherit">{person.name}</Text>
          )}
        </Fragment>
      ))}
    </Stack>
  ) : (title || text.untitled);

  return (
    <>
      <CallCard
        className={className}
        title={heading}
        source={source}
        timestamp={timestamp}
        participants={participants as CallParticipant[] | undefined}
        summary={summary}
        headerAside={linkPerson ? (
          <Button variant="outline" size="compact" onClick={() => setLinkOpen(true)} disabled={linking}>
            {text.linkPerson}
          </Button>
        ) : undefined}
        transcript={call.transcript}
        segments={call.segments}
        transcriptLabel={text.showTranscript}
        onLoadTranscript={call.onLoadTranscript}
        actions={
          <Stack gap="md" width="full" textAlign="start">
            <Stack direction="horizontal" justify="between" align="center">
              <Stack direction="horizontal" gap="xs" align="center">
                <Icon icon={Sparkles} size="sm" />
                <Text variant="small" weight="medium">{text.insights}</Text>
              </Stack>
              <Button variant="ghost" size="compact" onClick={() => insights.onGenerate(ready)} disabled={insights.generating}>
                {insights.generating ? <Icon icon={Loader2} size="sm" spin /> : <Icon icon={Sparkles} size="sm" />} {ready ? text.regenerate : text.generate}
              </Button>
            </Stack>
            {/* Keep generated insights directly beneath their action. */}
            {ready && (
              isShown(roleMatches) ? roleMatches : (
                <EmptyState
                  variant="empty"
                  size="inline"
                  icon={BriefcaseBusiness}
                  title={text.noRolesTitle}
                  description={text.noRolesDescription}
                />
              )
            )}
            {insights.error && <Text variant="small" tone="destructive">{insights.error}</Text>}
          </Stack>
        }
      />
      {linkPerson && (
        <ResponsiveDialog open={linkOpen} onOpenChange={setLinkOpen}>
          <ResponsiveDialogContent>
            <ResponsiveDialogHeader><ResponsiveDialogTitle>{text.linkTitle}</ResponsiveDialogTitle></ResponsiveDialogHeader>
            <ResponsiveDialogBody>
              <Stack gap="sm">
                <Input value={query} onChange={(event) => setQuery(event.target.value)} placeholder={text.searchPlaceholder} autoFocus />
                {searching && <Text variant="small" tone="muted">{text.searching}</Text>}
                {results.length > 0 && (
                  <List surface="bordered" radius="md">
                    {results.map((person) => (
                      <ListItem key={person.id}>
                        <Button variant="ghost" width="full" align="start" onClick={() => void link(person)} disabled={linking}>
                          {person.name}
                        </Button>
                      </ListItem>
                    ))}
                  </List>
                )}
                {!searching && query.trim().length >= CALL_PEOPLE_SEARCH_MIN_LENGTH && results.length === 0 && (
                  <EmptyState
                    variant="search"
                    size="inline"
                    icon={UserSearch}
                    title={text.noMatchesTitle}
                    description={text.noMatchesDescription}
                  />
                )}
              </Stack>
            </ResponsiveDialogBody>
          </ResponsiveDialogContent>
        </ResponsiveDialog>
      )}
    </>
  );
}

import { useRef, useState } from "react";

function isPromiseLike(value: unknown): value is PromiseLike<unknown> {
  return value != null && typeof (value as PromiseLike<unknown>).then === "function";
}

/**
 * Runs a host callback with the arguments given. While a returned promise is
 * pending, `pending` is true and `pendingArgs` holds what the latest call
 * passed, so a control can keep showing what it sent (a list it saved, say)
 * until the host answers, without the host tracking it. Only the latest call
 * settles the state: an earlier promise that settles after a later call began
 * changes nothing. A callback that returns no promise is never pending. The
 * host handles a failure in its own callback; this only waits for it to
 * settle.
 */
export function usePendingCall<TArgs extends unknown[]>(
  action: ((...args: TArgs) => unknown) | undefined,
) {
  const [pendingArgs, setPendingArgs] = useState<TArgs | null>(null);
  const latest = useRef(0);
  const run = (...args: TArgs) => {
    if (!action) return;
    const call = ++latest.current;
    const result = action(...args);
    if (isPromiseLike(result)) {
      setPendingArgs(args);
      const settle = () => {
        if (latest.current === call) setPendingArgs(null);
      };
      void Promise.resolve(result).then(settle, settle);
    } else {
      setPendingArgs(null);
    }
  };
  return [pendingArgs !== null, run, pendingArgs] as const;
}

/**
 * Runs a button's action. While a returned promise is pending, `pending` is
 * true, so the button can show a spinner or disable itself without the host
 * tracking which row is busy. The host handles a failure in its own callback;
 * the button only waits for it to settle. The runner passes none of its own
 * arguments on, so it can be a click handler without handing the host the
 * event.
 */
export function usePendingAction(action: (() => unknown) | undefined) {
  const [pending, run] = usePendingCall(action);
  return [pending, () => run()] as const;
}

"use client";

import { Collapsible } from "@epicbagel/saas-kit/primitives/collapsible";
import { Icon } from "@epicbagel/saas-kit/primitives/icon";
import { LazyMarkdown } from "@epicbagel/saas-kit/primitives/lazy-markdown";
import type { MarkdownComponents } from "@epicbagel/saas-kit/primitives/markdown";
import { Circle, CircleCheck, CircleDot, CircleMinus, CircleStop, CircleX, type LucideIcon } from "lucide-react";
import { useState } from "react";

import {
  ChainOfThought,
  ChainOfThoughtContent,
  ChainOfThoughtItem,
  ChainOfThoughtStatic,
  ChainOfThoughtStep,
  ChainOfThoughtTrigger,
} from "./chain-of-thought";

/** A step's status as the sourcing process reports it. */
export type SourcingStepStatus = "pending" | "running" | "done" | "error" | "skipped";

/** A step as it is shown: as reported, or `stopped` once its run isn't under way. */
export type SourcingStepShownStatus = SourcingStepStatus | "stopped";

/** One step of a sourcing run, written for the person the search is run for. */
export interface SourcingTraceStep {
  /** Stable for the life of the step, so a poll that inserts or reorders steps keeps what the reader opened. */
  key: string;
  title: string;
  status: SourcingStepStatus;
  /** A short second line under the title. */
  description?: string | null;
  /** Markdown, folded under the step. */
  detail?: string | null;
}

/** Host-owned wording: what each status glyph says to a screen reader, and how a run is named. */
export interface SourcingTraceLabels {
  pending: string;
  running: string;
  done: string;
  error: string;
  skipped: string;
  stopped: string;
  /** The name of the run under way, such as "How Scout is sourcing". */
  live: (agentName: string) => string;
  /** The name of a run that isn't under way, such as "How Scout searched". */
  settled: (agentName: string) => string;
}

export const sourcingTraceLabels: Readonly<SourcingTraceLabels> = {
  pending: "Up next",
  running: "In progress",
  done: "Done",
  error: "Failed",
  skipped: "Skipped",
  stopped: "Stopped",
  live: (agentName) => `How ${agentName} is sourcing`,
  settled: (agentName) => `How ${agentName} searched`,
};

const unfinished = (status: SourcingStepStatus) => status === "pending" || status === "running";

/** How a step shows: as reported while its run is live, and stopped if the run left it pending or running. */
export function sourcingStepShownStatus(status: SourcingStepStatus, live: boolean): SourcingStepShownStatus {
  return !live && unfinished(status) ? "stopped" : status;
}

/**
 * The one line a folded run shows: how far it got ("5 steps", "3 of 5 steps
 * done"), with the steps that failed or were skipped, and "stopped" when it
 * left steps pending or running. `failed` turns the line red.
 */
export function sourcingTraceSummary(steps: ReadonlyArray<Pick<SourcingTraceStep, "status">>) {
  const total = steps.length;
  let done = 0;
  let failed = 0;
  let skipped = 0;
  let stopped = 0;
  for (const step of steps) {
    if (step.status === "done") done += 1;
    else if (step.status === "error") failed += 1;
    else if (step.status === "skipped") skipped += 1;
    else stopped += 1;
  }
  const count = `${total} ${total === 1 ? "step" : "steps"}`;
  const parts = [done === total ? count : `${done} of ${count} done`];
  if (failed > 0) parts.push(`${failed} failed`);
  if (skipped > 0) parts.push(`${skipped} skipped`);
  if (stopped > 0) parts.push("stopped");
  return { description: parts.join(" · "), failed: failed > 0 };
}

/**
 * Each status's glyph, one family of circles. No sentiment colour: the line
 * turns an error red, and a running step's title shimmers (still, for a
 * reader who asks for less motion), so nothing here spins.
 */
const STEP_ICONS: Record<SourcingStepShownStatus, LucideIcon> = {
  pending: Circle,
  running: CircleDot,
  done: CircleCheck,
  error: CircleX,
  skipped: CircleMinus,
  stopped: CircleStop,
};

/** The timeline's line state: running shimmers, an error is red, and a step still to come, skipped or stopped is dimmed. */
const LINE_STATUS: Record<SourcingStepShownStatus, "pending" | "running" | "error" | undefined> = {
  pending: "pending",
  running: "running",
  done: undefined,
  error: "error",
  skipped: "pending",
  stopped: "pending",
};

/**
 * A step, and under it its detail when it has some, folded behind the line.
 * Until the reader opens or closes it, the detail is open while the step
 * runs, so it folds again as the step finishes.
 */
function SourcingStepItem({
  step,
  live,
  labels,
  markdownComponents,
  isLast,
}: {
  step: SourcingTraceStep;
  live: boolean;
  labels: SourcingTraceLabels;
  markdownComponents?: MarkdownComponents;
  isLast?: boolean;
}) {
  const [opened, setOpened] = useState<boolean | null>(null);
  const status = sourcingStepShownStatus(step.status, live);
  const line = {
    status: LINE_STATUS[status],
    "data-step-status": status,
    description: step.description,
    // The glyph is the only sign of the status, so a screen reader names it.
    leftIcon: <Icon icon={STEP_ICONS[status]} role="img" aria-hidden={false} aria-label={labels[status]} />,
  };
  return (
    <ChainOfThoughtStep isLast={isLast} open={opened ?? status === "running"} onOpenChange={setOpened}>
      {step.detail ? (
        <>
          <ChainOfThoughtTrigger {...line} swapIconOnHover={false}>{step.title}</ChainOfThoughtTrigger>
          <ChainOfThoughtContent>
            <ChainOfThoughtItem>
              <LazyMarkdown size="sm" tone="muted" components={markdownComponents}>{step.detail}</LazyMarkdown>
            </ChainOfThoughtItem>
          </ChainOfThoughtContent>
        </>
      ) : <ChainOfThoughtStatic {...line}>{step.title}</ChainOfThoughtStatic>}
    </ChainOfThoughtStep>
  );
}

export interface SourcingTraceProps {
  /** The run's steps, in order. With none, nothing is drawn. */
  steps: readonly SourcingTraceStep[];
  /** Who did the work, for the run's name ("How Scout searched"). */
  agentName: string;
  /**
   * The run under way: every step shows, as reported. Any other run
   * (finished, gone quiet or overtaken) folds into one line that opens to its
   * steps, a step it left pending or running shown stopped.
   */
  live?: boolean;
  labels?: Partial<SourcingTraceLabels>;
  /** Per-element overrides for the steps' Markdown detail, such as a host's heading face. */
  markdownComponents?: MarkdownComponents;
}

/**
 * How a sourcing run went, for the person the search is run for: a line per
 * step, in order, each with its status (ticked once done, red on an error,
 * the running one shimmering with its detail open) and its short
 * description, the Markdown detail folded under it.
 *
 * The host decides which run is live and words the steps: the component
 * holds no workflow and fetches nothing. A status is a glyph named for a
 * screen reader (`labels`), never colour alone.
 */
export function SourcingTrace({ steps, agentName, live = false, labels, markdownComponents }: SourcingTraceProps) {
  if (steps.length === 0) return null;
  const text = { ...sourcingTraceLabels, ...labels };
  const items = steps.map((step) => (
    <SourcingStepItem key={step.key} step={step} live={live} labels={text} markdownComponents={markdownComponents} />
  ));
  if (live) {
    return <ChainOfThought role="group" aria-label={text.live(agentName)}>{items}</ChainOfThought>;
  }
  const summary = sourcingTraceSummary(steps);
  const title = text.settled(agentName);
  return (
    <Collapsible role="group" aria-label={title}>
      <ChainOfThoughtTrigger status={summary.failed ? "error" : undefined} description={summary.description}>
        {title}
      </ChainOfThoughtTrigger>
      <ChainOfThoughtContent timeline={false}>
        <ChainOfThought>{items}</ChainOfThought>
      </ChainOfThoughtContent>
    </Collapsible>
  );
}

// A compact control is sized for a mouse. On a coarse pointer (a touchscreen)
// it grows to a 44px touch target, whatever size it asked for; a mouse keeps
// the dense size. 44 CSS pixels rather than the kit's h-11 (2.75rem): below
// 768px the kit scales its root type to 87.5%, which makes h-11 38.5px on a
// phone, and the larger of the two where a host's root is bigger. min-height
// and min-width rather than a size, so a control already larger keeps its own.

/** On a coarse pointer, this element is at least 44px square. */
export const COARSE_POINTER_TOUCH_TARGET =
  "pointer-coarse:min-h-[max(44px,2.75rem)] pointer-coarse:min-w-[max(44px,2.75rem)]";

/** On a coarse pointer, every link and button inside this element is at least 44px square. */
export const COARSE_POINTER_TOUCH_TARGETS_WITHIN =
  "pointer-coarse:[&_a]:min-h-[max(44px,2.75rem)] pointer-coarse:[&_a]:min-w-[max(44px,2.75rem)] pointer-coarse:[&_button]:min-h-[max(44px,2.75rem)] pointer-coarse:[&_button]:min-w-[max(44px,2.75rem)]";
